function completedReflectionCycles(){const all=[data,...history,sampleArchive()].filter(r=>r.status==='Selesai');return all.filter((r,i)=>all.findIndex(x=>x.year===r.year)===i).sort((a,b)=>b.year.localeCompare(a.year))}
function reflectionSave(){localStorage.setItem('spmp-self-reflections-v2',JSON.stringify(reflections))}
function selectReflectionCycle(year){if(!completedReflectionCycles().some(r=>r.year===year))return;reflectionYear=year;reflections[year]??={scores:{},notes:{},completed:false};const r=reflections[year];reflectionStep=r.completed?6:reflectionRubrics.findIndex((_,i)=>r.scores[i]===undefined);if(reflectionStep<0)reflectionStep=6;render()}
function reflectionChoose(score){if(!completedReflectionCycles().some(r=>r.year===reflectionYear)||reflectionStep>5)return;const r=reflections[reflectionYear];if(r.completed)return;r.scores[reflectionStep]=score;r.completed=false;reflectionSave();const kb=document.activeElement?.matches?.('.sd-radio input');render();if(kb)document.querySelector('.sd-radio input:checked')?.focus()}
function reflectionNote(value){if(reflections[reflectionYear]?.completed)return;reflections[reflectionYear].notes[reflectionStep]=value;reflectionSave()}
function reflectionNext(){const r=reflections[reflectionYear];if(r.scores[reflectionStep]===undefined)return toast('Pilih penilaian untuk tahap ini terlebih dahulu.');const scrollPosition=window.scrollY;reflectionStep++;render();window.scrollTo({top:scrollPosition,left:0,behavior:'instant'})}
function finishReflection(){const r=reflections[reflectionYear];if(!r||r.completed)return;if(reflectionRubrics.some((_,i)=>r.scores[i]===undefined))return toast('Lengkapi penilaian keenam tahap terlebih dahulu.');const cycle=completedReflectionCycles().find(c=>c.year===reflectionYear);if(!cycle)return;const ev=reflectionEvidence(cycle);const missing=reflectionRubrics.findIndex((_,i)=>r.scores[i]!==ev[i].score&&!r.justifications?.[i]?.trim());if(missing>=0){toast('Lengkapi alasan perbedaan penilaian pada tahap '+names[missing]+'.');document.getElementById('reflection-justification-'+missing)?.focus();return}r.completed=true;r.evidenceSnapshot=ev;r.savedAt=new Date().toISOString();reflectionSave();reflectionList();toast('Evaluasi diri tersimpan.')}
function reflectionList(){reflectionYear='';reflectionStep=0;render();window.scrollTo(0,0)}
function selfEvaluation(){const cycles=completedReflectionCycles(),labels=REFLECTION_LABELS;if(!cycles.some(c=>c.year===reflectionYear))reflectionYear='';if(reflectionYear)return `<div class="eyebrow">Siklus ${esc(reflectionYear)}</div><h1>Evaluasi Diri</h1><p class="muted">Refleksikan cara sekolah menjalani setiap tahap untuk memperbaiki siklus berikutnya.</p>${reflectionStep===6?reflectionSummary(labels):reflectionQuestion(labels)}`;return `<div class="eyebrow">Belajar dari perjalanan sekolah</div><h1>Evaluasi Diri</h1><p class="muted">Refleksikan siklus yang sudah selesai. Mulai penilaian, lanjutkan draf, atau lihat hasil refleksi sebelumnya.</p>${!cycles.length?`<div class="card"><h2>Belum ada siklus yang selesai</h2><p>Evaluasi diri tersedia setelah sekolah menyelesaikan satu Siklus 6M.</p>${sdBtn('Buka siklus sekolah',{variant:'secondary',onclick:"go('home')"})}</div>`:`<div class="card reflection-list-card">${sdTable({caption:'Daftar siklus evaluasi diri',columns:[{label:'Siklus'},{label:'Progres refleksi'},{label:'Kematangan budaya mutu'},{label:'Status'},{label:'Tindakan',align:'right'}],rows:cycles.map(c=>{const r=reflections[c.year],count=reflectionRubrics.filter((_,i)=>r?.scores[i]!==undefined).length,status=r?.completed?'Selesai':count?'Draf':'Belum dimulai';return [`<span class="sd-cell-title">Siklus ${esc(c.year)}</span><span class="sd-cell-sub">Juli ${esc(c.year.split('/')[0])} – Juni ${esc(c.year.split('/')[1])}</span>`,`${count} dari 6 tahap`,r?.completed&&r.evidenceSnapshot?sdBadge(reflectionMaturity(r.scores,r.evidenceSnapshot).label,'blue'):'<span class="sub">—</span>',sdBadge(status,status==='Selesai'?'green':'gray'),sdBtn(r?.completed?'Buka hasil':count?'Lanjutkan':'Mulai evaluasi diri',{variant:r?.completed?'secondary':'ultimate',onclick:`selectReflectionCycle('${c.year}')`})]})})}</div>`}`}

function reflectionQuestion(labels){const r=reflections[reflectionYear],q=reflectionRubrics[reflectionStep];return `<article class="card reflection-question"><div class="row reflection-progress-heading"><div class="reflection-stage-title">${names[reflectionStep]}<span>Tahap ${reflectionStep+1} dari 6</span></div><span class="sd-status">${sdIcon('check')}Tersimpan otomatis</span></div><div class="reflection-dots" aria-label="Progres refleksi">${names.map((n,i)=>`<span class="${i===reflectionStep?'current':r.scores[i]!==undefined?'filled':''}" aria-label="${esc(n)}"></span>`).join('')}</div><p class="reflection-def">${esc(q.definition)}</p>${sdRadioGroup({legend:q.question,name:'reflection-score',value:r.scores[reflectionStep],options:labels.map((label,i)=>({value:i,label:'Level '+(i+1)+' · '+label,help:q.levels[i]})),onchange:'reflectionChoose(Number(this.value))'})}${sdAccordion({id:'reflection-evidence-'+reflectionStep,title:'Bukti yang diharapkan',className:'sd-accordion-card reflection-evidence-needed',body:`<p class="reflection-accordion-text">${esc(q.evidence)}</p>`})}<div class="actions">${sdBtn('Sebelumnya',{variant:'secondary',disabled:reflectionStep===0,onclick:'reflectionStep--;render()',leadingIcon:'arrow-left'})}${sdBtn(reflectionStep===5?'Tinjau penilaian':'Lanjut',{onclick:'reflectionNext()',trailingIcon:'arrow-right'})}</div></article>`}
function reflectionEvidence(cycle){const P=cycle.priorities||[],K=cycle.activities||[],roots=cycle.roots||{},progress=cycle.progress||{},evaluation=cycle.evaluation||{},follow=cycle.follow||{};const result=[];const add=(score,reasons)=>result.push({score,reasons});const targets=P.filter(id=>typeof ind(id)?.score==='number'&&Number(cycle.targets?.[id])>0).length;
add(!P.length?0:targets<P.length?1:!cycle.teamAgreement?2:!cycle.targetsReviewed?3:4,[`${P.length} indikator prioritas ditetapkan.`,`${targets} dari ${P.length} prioritas memiliki capaian awal dan target tercatat.`,cycle.teamAgreement?'Kesepakatan tim tercatat.':'Kesepakatan TPMPS belum tercatat di prototipe.',cycle.targetsReviewed?'Peninjauan target dari evaluasi sebelumnya tercatat.':'Peninjauan target dari evaluasi sebelumnya belum tercatat.','Referensi menggunakan target 4 tahun; prototipe saat ini belum mengumpulkannya.']);
const mapped=P.filter(id=>roots[id]?.length).length;const deep=P.filter(id=>cycle.rootAnalysis?.[id]?.method&&cycle.rootAnalysis[id].layers?.length>=2).length;
add(!mapped?0:mapped<P.length?1:!P.every(id=>cycle.rootAnalysis?.[id])?2:deep===P.length?4:3,[`${mapped} dari ${P.length} prioritas memiliki akar masalah.`,`${deep} dari ${P.length} prioritas memiliki analisis lintas lapis dan metode tercatat.`]);
const linked=K.filter(a=>a.root&&(roots[a.indicator]||[]).includes(a.root)).length,covered=P.filter(id=>K.some(a=>a.indicator===id)).length,costed=K.filter(a=>a.needsBudget===true||Number(a.budget)>0),budgetComplete=costed.filter(a=>(a.budgetLines||[]).some(r=>r.description?.trim()&&r.month&&Number(r.quantity)>0&&r.unit?.trim()&&r.price!==''&&Number.isFinite(Number(r.price)))).length;
add(!K.length?0:linked<K.length||covered<P.length?1:budgetComplete<costed.length?2:cycle.budgetChecksPassed===true?4:3,[`${linked} dari ${K.length} kegiatan terhubung dengan akar masalah.`,`${covered} dari ${P.length} prioritas memiliki kegiatan.`,`${budgetComplete} dari ${costed.length} kegiatan beranggaran memiliki rincian lengkap.`,cycle.budgetChecksPassed?'Pemeriksaan rancangan RKAS tercatat.':'Pemeriksaan batas komponen RKAS/BOSP belum tersedia; rincian anggaran tidak dianggap sebagai bukti persetujuan ARKAS.']);
const run=K.filter(a=>{const p=progress[a.id]||{};return p.notes?.trim()||p.link?.trim()||p.files?.length||Number(p.achieved)>0}).length,proof=K.filter(a=>progress[a.id]?.link?.trim()||progress[a.id]?.files?.length).length,ratio=K.length?proof/K.length:0,monitoring=cycle.monitoring?.length||0;
add(!run?0:ratio<.5?1:ratio<.8||monitoring<2?2:K.filter(a=>evaluation[a.id]?.result==='Efektif').length*2>=K.length?4:3,[`${run} dari ${K.length} kegiatan memiliki catatan atau aktivitas pelaksanaan.`,`${proof} dari ${K.length} kegiatan memiliki tautan atau lampiran bukti.`,`${monitoring} catatan monitoring berkala tercatat.`]);
const evaluated=K.filter(a=>evaluation[a.id]?.result).length;
add(!evaluated?0:evaluated<K.length?1:ratio<.8?2:K.every(a=>follow[a.id]?.action?.trim())?4:3,[`${evaluated} dari ${K.length} kegiatan memiliki penilaian efektivitas.`,`${K.length-evaluated} kegiatan belum dievaluasi.`,'Prototipe tidak lagi mengumpulkan target output numerik; hasil ini memakai penilaian efektivitas yang tercatat. Perubahan indikator antarsiklus belum dinilai otomatis.']);
const needs=K.filter(a=>['Perlu penyesuaian','Tidak efektif'].includes(evaluation[a.id]?.result)),actions=K.filter(a=>follow[a.id]?.action?.trim()),addressed=needs.filter(a=>follow[a.id]?.action?.trim()).length,carry=actions.some(a=>follow[a.id]?.carry);
add(!actions.length?0:addressed<needs.length?1:!carry?2:new Set(actions.map(a=>follow[a.id]?.type).filter(Boolean)).size>=2?4:3,[`${actions.length} kegiatan memiliki rencana tindak lanjut.`,`${addressed} dari ${needs.length} kegiatan yang perlu perbaikan memiliki tindak lanjut.`,carry?'Ada tindak lanjut yang dibawa ke siklus berikutnya.':'Belum ada tindak lanjut yang dibawa ke siklus berikutnya.']);return result}
function reflectionMaturity(scores,ev){const per=names.map((_,i)=>(Number(scores[i])+Number(ev[i].score))/2),avg=per.reduce((a,b)=>a+b,0)/per.length,index=Math.round(avg/4*1000)/10,band=MATURITY_BANDS.filter(b=>index>=b[1]).at(-1);return {index,label:band[0],level:MATURITY_BANDS.indexOf(band)}}
function maturityBlock(m){return `<section class="maturity-card" aria-label="Kematangan budaya mutu"><div class="maturity-main"><span class="maturity-eyebrow">Kematangan budaya mutu</span><strong class="maturity-label">${esc(m.label)}</strong><span class="maturity-index">Indeks ${String(m.index).replace('.',',')} dari 100</span></div><ol class="maturity-scale">${REFLECTION_LABELS.map((l,i)=>`<li class="${i===m.level?'is-current':i<m.level?'is-passed':''}"${i===m.level?' aria-current="true"':''}><span>${esc(l)}</span></li>`).join('')}</ol><p class="maturity-note">Angka ini memakai formula sementara: rata-rata level penilaian diri dan level berdasarkan bukti dari enam tahap, dikonversi ke skala 0–100 dan dibagi ke lima kriteria. Formula konversi resmi belum ditetapkan.</p></section>`}
function reflectionComparisonStatus(self,evidence){return self===evidence?'Konsisten':self>evidence?'Di atas penilaian berdasarkan bukti':'Di bawah penilaian berdasarkan bukti'}
function reviewReflectionScore(index,value){const r=reflections[reflectionYear],scroll=window.scrollY;if(!r||r.completed)return;r.scores[index]=Number(value);r.completed=false;reflectionSave();render();window.scrollTo({top:scroll,left:0,behavior:'instant'})}
function reflectionJustify(index,value){const r=reflections[reflectionYear];if(!r||r.completed)return;r.justifications??={};r.justifications[index]=value;r.completed=false;reflectionSave();const status=document.getElementById('reflection-review-save-status');if(status)status.textContent='Draf tersimpan otomatis';const button=document.getElementById('reflection-review-save');if(button)button.hidden=false}
function reflectionSummary(labels){const r=reflections[reflectionYear],cycle=completedReflectionCycles().find(c=>c.year===reflectionYear);if(!cycle)return '';const ev=r.completed&&r.evidenceSnapshot?r.evidenceSnapshot:reflectionEvidence(cycle),different=names.map((_,i)=>i).filter(i=>r.scores[i]!==ev[i].score);const basisPlain=i=>`<ul class="reflection-accordion-list">${ev[i].reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul>${r.notes[i]?`<p class="reflection-accordion-text">Catatan refleksi Anda: ${esc(r.notes[i])}</p>`:''}`,basis=i=>sdAccordion({id:'reflection-basis-'+i,title:'Dasar penilaian',className:'sd-accordion-card',body:basisPlain(i)});return `<article class="card reflection-summary reflection-focus-review">${sdBadge(r.completed?'Evaluasi diri tersimpan':'Tinjau Evaluasi Diri',r.completed?'green':'gray')}<h2>Refleksi Siklus ${esc(reflectionYear)}</h2>${maturityBlock(reflectionMaturity(r.scores,ev))}<p class="sub">Bandingkan penilaian Anda dengan bukti aktivitas yang tercatat. Tingkat berdasarkan bukti tidak menggantikan penilaian sekolah.</p>${sdBanner({tone:different.length?'info':'success',children:`<p>${different.length?`${different.length} tahap memiliki perbedaan penilaian. ${r.completed?'Alasan penilaian tersimpan di bawah tahap terkait.':'Lengkapi alasan untuk setiap penilaian yang lebih tinggi maupun lebih rendah.'}`:'Seluruh penilaian diri konsisten dengan bukti yang tercatat.'}</p>`})}${sdTable({caption:'Perbandingan penilaian Anda dengan bukti',className:'reflection-comparison-table',columns:[{label:'Tahap'},{label:'Penilaian Anda'},{label:'Berdasarkan bukti'}],rows:names.flatMap((name,i)=>{const own=r.completed?`<span class="sd-cell-title">${labels[r.scores[i]]}</span>`:sdSelect({label:'Penilaian diri '+name,hideLabel:true,value:r.scores[i],options:labels.map((label,j)=>({value:j,label})),onchange:`reviewReflectionScore(${i},this.value)`});const row=[`<span class="sd-cell-title">${name}</span>`,own,`<span class="sd-cell-title">${labels[ev[i].score]}</span>`];if(r.scores[i]===ev[i].score)return [row];return [row,{full:`<div class="reflection-justification-row"><section class="reflection-difference-entry">${r.completed?`<p class="reflection-difference-label">Mengapa Anda memilih ${labels[r.scores[i]]}, sementara bukti menunjukkan ${labels[ev[i].score]}?</p><p class="reflection-saved-reason">${esc(r.justifications?.[i]||'—')}</p>`:sdTextArea({label:`Mengapa Anda memilih ${labels[r.scores[i]]}, sementara bukti menunjukkan ${labels[ev[i].score]}?`,id:'reflection-justification-'+i,value:r.justifications?.[i]||'',placeholder:'Jelaskan pertimbangan atau konteks sekolah.',rows:3,attrs:'required aria-required="true"',oninput:`reflectionJustify(${i},this.value)`})}${basis(i)}</section></div>`}]})})}${different.length<names.length?`${sdAccordion({id:'reflection-basis-consistent',title:'Dasar penilaian tahap yang konsisten',className:'sd-accordion-card',body:names.map((name,i)=>r.scores[i]===ev[i].score?`<section class="reflection-consistent-item"><h3>${name}</h3>${basisPlain(i)}</section>`:'').join('')})}`:''}<p class="source-text">Penilaian berdasarkan data yang tercatat di prototipe. Unsur rubrik yang belum dikumpulkan ditandai pada dasar penilaian dan tidak diasumsikan terpenuhi.</p><div class="actions">${r.completed?sdBtn('Kembali ke daftar evaluasi diri',{variant:'secondary',onclick:'reflectionList()',leadingIcon:'arrow-left'}):sdBtn('Kembali',{variant:'secondary',onclick:'reflectionStep=5;render()',leadingIcon:'arrow-left'})}<span class="sd-status">${sdIcon('check')}<span id="reflection-review-save-status">${r.completed?'Evaluasi diri telah tersimpan':'Draf tersimpan otomatis'}</span></span>${sdBtn('Simpan evaluasi diri',{id:'reflection-review-save',onclick:'finishReflection()',attrs:r.completed?'hidden':''})}</div></article>`}

function raporNavbar(){const on=(...p)=>p.includes(page),link=(label,p,list)=>`<button class="${on(...list)?'active':''}" ${on(...list)?'aria-current="page"':''} onclick="go('${p}')">${label}</button>`;return `<header class="platform-navbar rapor-navbar"><div class="navbar-identity"><span class="navbar-brand"><img class="rapor-logo-emblem" src="assets/nav/logo-tut-wuri.png" width="44" height="44" alt=""><img class="rapor-logo-wordmark" src="assets/nav/logo-rapor-pendidikan.svg" width="137" height="44" alt="Rapor Pendidikan"></span></div><nav aria-label="Navigasi utama">${link('Ringkasan','rapor',['rapor','rapor-root'])}${link('Unduh','downloads',['downloads'])}${link('Glosarium','glossary',['glossary'])}<button type="button" aria-label="Pusat Bantuan, buka di tab baru" onclick="openHelp()">Pusat Bantuan</button>${entryOn('navbar')?`<button type="button" class="rapor-nav-spmp" aria-label="Platform SPMP, buka di tab baru" onclick="openSpmp()">Platform SPMP${sdIcon('open-in-new')}</button>`:''}</nav><details class="navbar-account rapor-account"><summary aria-label="Menu profil"><span class="avatar" aria-hidden="true">AR</span><img class="navbar-chevron" src="assets/nav/arrow-down.svg" width="24" height="24" alt="" aria-hidden="true"></summary><div class="rapor-profile-menu" role="menu" aria-label="Menu profil"><div class="rapor-profile-info"><b>Rapor Satdik Demo</b><span>rapor-demo@contoh.sch.id</span></div><button type="button" role="menuitem" onclick="this.closest('details').open=false;toast('Prototipe tidak memiliki sesi masuk, jadi tidak ada yang keluar.')">Keluar</button></div></details></header>`}
function raporEntryBanners(){return `<div class="rapor-banners">${!entryOn('banner')?'':sdBanner({tone:'info',title:'Susun perbaikan dari capaian Rapor Anda',children:'<p>Platform SPMP membantu satuan pendidikan menetapkan prioritas, menyusun rencana, dan mengevaluasi perbaikan lewat Siklus 6M dan Evaluasi Diri. Platform terbuka di tab baru.</p>',action:sdBtn('Buka Platform SPMP',{variant:'secondary',size:'sm',trailingIcon:'open-in-new',onclick:'openSpmp()'}),onClose:"this.closest('.sd-banner').remove()"})}</div>`}
function mainNavbar(){if(RAPOR)return raporNavbar();return `<header class="platform-navbar"><details class="navbar-identity"><summary><span class="emblem" aria-hidden="true"><img src="assets/nav/logo-kemendikbud.png" alt=""></span><span class="navbar-brand-copy"><b>Platform SPMP</b><span>SMA Rakyat 3</span></span><img class="navbar-chevron" src="assets/nav/arrow-down.svg" width="24" height="24" alt="" aria-hidden="true"></summary><div class="navbar-dropdown"><b>SMA Rakyat 3</b><p>NPSN 20260001</p><span>Identitas sekolah demonstrasi</span></div></details><nav aria-label="Navigasi utama"><button class="${['home','flow','review','detail','menetapkan-alternative','menetapkan-cards'].includes(page)?'active':''}" ${['home','flow','review','detail'].includes(page)?'aria-current="page"':''} onclick="go('home')">Siklus 6M</button><button class="${page==='self-evaluation'?'active':''}" ${page==='self-evaluation'?'aria-current="page"':''} onclick="go('self-evaluation')">Evaluasi Diri</button></nav><details class="navbar-account"><summary aria-label="Menu akun sekolah"><span class="avatar">SR</span><img class="navbar-chevron" src="assets/nav/arrow-down.svg" width="24" height="24" alt="" aria-hidden="true"></summary><div class="navbar-dropdown"><b>Akun satuan pendidikan</b><p>SMA Rakyat 3</p><span>Prototipe demonstrasi</span><div class="navbar-profile-menu"><button type="button" disabled>Glosarium</button></div></div></details></header>`}

function pageTitleBanner(){if(RAPOR)return '';if(page==='rapor'||page==='rapor-root')return '';let title='Diagnosis',description='Kenali kondisi mutu sekolah melalui capaian indikator dan telusuri area yang perlu diperbaiki.',context='SMA Rakyat 3 · Tahun data 2025';if(page==='menetapkan-cards'){title=headings[0];description=descriptions[0];context='Design alternatives 2 · Menetapkan · Siklus '+data.year}else if(page==='menetapkan-alternative'){title=headings[0];description=descriptions[0];context='Alternatif desain · Menetapkan lama · Siklus '+data.year}else if(page==='home'){title='Siklus 6M';description='Susun dan jalankan langkah perbaikan sekolah, lalu gunakan hasil evaluasi untuk siklus berikutnya.';context=''}else if(page==='flow'){title=headings[stage];description=descriptions[stage];context='Siklus '+data.year+' · '+names[stage]}else if(page==='review'){title='Tinjau rencana';description='Periksa RKT dan RKAS seperti yang akan Anda unduh. Rencana yang sudah disimpan tidak bisa diedit lagi.';context=''}else if(page==='detail'){title=outcomeView==='summary'?'Ringkasan siklus':outcomeView==='doc'?'Siklus '+data.year:'Ringkasan rencana';description=outcomeView==='summary'?'Rekapan hasil satu siklus perbaikan sekolah, dari capaian indikator sampai tindak lanjut.':outcomeView==='doc'?`${period()} · ${data.priorities.length} prioritas, ${data.activities.length} kegiatan · Langkah ${Math.min(cycleStage(data).step,5)+1} dari 6, ${cycleStage(data).label}`:'Tinjau prioritas perbaikan, kegiatan, anggaran, dan capaian rencana sekolah.';context='Siklus '+data.year}else if(page==='self-evaluation'){title='Evaluasi Diri';description=reflectionYear?'Refleksikan cara sekolah menjalani setiap tahap untuk memperbaiki siklus berikutnya.':'Refleksikan siklus yang sudah selesai. Mulai penilaian, lanjutkan draf, atau lihat hasil refleksi sebelumnya.';context=reflectionYear?'':'Belajar dari perjalanan sekolah'}else if(page==='downloads'){title='Unduh';description='Unduh Rapor Pendidikan dan dapatkan rekomendasi Perencanaan Berbasis Data satuan pendidikan Anda.';context=''}else if(page==='rapor-root'){title=ind(reportIndicator).name;description='Pelajari akar masalah dan inspirasi perbaikan berdasarkan capaian indikator sekolah.'}else if(page==='diagnosis-alternatives'){context='Alternatif desain · Diagnosis lama'}else if(!['rapor','home','flow','review','detail','self-evaluation','rapor-root','diagnosis-alternatives'].includes(page)){title='Pusat Bantuan';description='Panduan singkat menyusun dan menjalankan siklus perbaikan sekolah.';context='Panduan penggunaan'}let crumbs='',rail='';if(page==='self-evaluation'&&reflectionYear){const sep='<li class="crumb-sep" aria-hidden="true"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 6l6 6-6 6"/></svg></li>';crumbs=`<nav class="page-breadcrumb" aria-label="Breadcrumb"><ol><li><button type="button" onclick="reflectionList()">Evaluasi diri</button></li>${sep}<li aria-current="page">Siklus ${esc(reflectionYear)}</li></ol></nav>`}if(['flow','review','detail'].includes(page)){const current=page==='flow'?names[stage]:page==='review'?'Tinjau rencana':outcomeView==='doc'?'Siklus '+data.year:outcomeView==='summary'?'Ringkasan siklus':'Ringkasan rencana';context='';crumbs=`<nav class="page-breadcrumb" aria-label="Breadcrumb"><ol><li><button type="button" onclick="go('home')">Siklus 6M${outcomeView==='doc'?'':' '+esc(data.year)}</button></li><li class="crumb-sep" aria-hidden="true"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 6l6 6-6 6"/></svg></li><li aria-current="page">${esc(current)}</li></ol></nav>`;if(page==='flow'&&!hasPreview())rail=flowStepper()}return `<section class="page-title-banner ${page==='downloads'?'download-title-banner':''} ${crumbs?'has-breadcrumb':''} " aria-label="Judul halaman"><div class="page-title-inner">${crumbs}${context?`<p class="page-title-context">${esc(context)}</p>`:''}<div class="page-title-row"><h1>${esc(title)}</h1></div><p class="page-title-description">${esc(description)}</p>${rail}</div></section>`}

function render(){ syncOwnIndicators(); if(page==='flow'&&stage<3&&data.status==='Draf'&&data.lastStep!==stage){data.lastStep=stage;save()} if(stage>=3)previewFrom=null; $('#app').innerHTML=`${protoBar()}${mainNavbar()}${pageTitleBanner()}<main class="wrap page-${page} ${page==='self-evaluation'&&reflectionYear&&reflectionStep<6?'reflection-compact-page':''}">${page==='menetapkan-cards'?menetapkanAlternative():page==='menetapkan-alternative'?legacyMenetapkan():page==='downloads'?downloadsPage():page==='glossary'?glossaryPage():page==='home'?home():page==='flow'?flowLayout(flow()):page==='review'?review():page==='detail'?detail():page==='diagnosis-alternatives'?legacyRapor():page==='rapor'?rapor():page==='rapor-root'?raporRoot():page==='self-evaluation'?selfEvaluation():help()}</main>${priorityTargetDialog()}${RAPOR?raporFab():''}`;lockReadonlyFlow();if(RAPOR)updateRaporFab()}
let outcomeView='';
function go(p){page=p;outcomeView='';previewFrom=null;if(p==='self-evaluation')reflectionYear='';render();window.scrollTo(0,0)}
let docView=null;
function hasSavedPlan(r){return ['Sudah ada rencana','Selesai'].includes(r.status)&&(r.activities||[]).length>0}
function setSavedDocTab(v){docScrollTo(v)}
function downloadDoc(type){if(!docView)return;const current=data;data=recordFor(docView.kind,docView.index);try{if(type==='rkas')downloadRkas();else downloadRkt(type)}finally{data=current}}
function docSetTab(v){document.querySelectorAll('.doc-tabs .sd-tab').forEach(t=>t.setAttribute('aria-current',t.id==='saved-doc-tab-'+v?'true':'false'))}
function docScrollTo(v,instant){const el=document.getElementById('doc-sec-'+v);if(!el)return;docSetTab(v);window.__docLock=Date.now()+1400;el.scrollIntoView({behavior:instant?'auto':'smooth',block:'start'})}
function docSpy(){if(!document.querySelector('.doc-page .doc-tabs')||Date.now()<(window.__docLock||0))return;const secs=[...document.querySelectorAll('.doc-section')];if(!secs.length)return;let cur=secs[0];const atEnd=window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-2;if(atEnd)cur=secs[secs.length-1];else secs.forEach(el=>{if(el.getBoundingClientRect().top<=200)cur=el});docSetTab(cur.id.replace('doc-sec-',''))}
function docTabs(r){const res=r.evaluationSubmitted||r.status==='Selesai',items=[['ringkasan','Ringkasan'],['rkt','RKT'],['rkas','RKAS'],...(res?[['hasil','Hasil dan Tindak Lanjut']]:[])];return `<nav class="sd-tabs doc-tabs" aria-label="Bagian halaman siklus">${items.map(([v,l],k)=>`<button type="button" class="sd-tab" id="saved-doc-tab-${v}" aria-current="${k===0?'true':'false'}" onclick="docScrollTo('${v}')">${l}</button>`).join('')}</nav>`}
function docSummary(r){const total=r.activities.reduce((sum,a)=>sum+Number(a.budget||0),0);return `<dl class="doc-stats"><div><dt>Prioritas</dt><dd>${r.priorities.length}</dd></div><div><dt>Kegiatan</dt><dd>${r.activities.length}</dd></div><div><dt>Total anggaran</dt><dd>${money(total)}</dd></div></dl>${r.priorities.length?`<section class="card doc-targets" aria-labelledby="doc-targets-title"><div class="doc-targets-head"><h2 id="doc-targets-title">${r.evaluationOpen||r.evaluationSubmitted||r.status==='Selesai'?'Target dan hasil capaian':'Target capaian'}</h2><p>Capaian awal dari Rapor Pendidikan. Target ditetapkan untuk siklus ${esc(r.year)}.${r.evaluationOpen||r.evaluationSubmitted||r.status==='Selesai'?' Hasil dibandingkan dengan target.':''}</p></div><ul>${r.priorities.map(id=>{const showResult=!!(r.evaluationOpen||r.evaluationSubmitted||r.status==='Selesai'),i=ind(id),start=Number(i.score),has=r.targets[id]!==undefined&&r.targets[id]!=='',tv=Number(r.targets[id]),unit=esc(i.unit||'skor'),gain=has&&typeof i.score==='number'?Math.round((tv-start)*100)/100:null;return `<li class="doc-target${showResult?' has-result':''}"><div class="doc-target-name"><b>${esc(i.name)}</b><span>${esc(i.code)} · ${esc(i.source)}, periode ${esc(i.period)}</span></div><div class="doc-target-val"><span>Capaian awal</span><b>${scoreText(i)} ${unit}</b></div><div class="doc-target-val is-target"><span>Target ${esc(r.year)}</span><b>${has?scoreText({score:tv})+' '+unit:'Belum ditetapkan'}</b></div>${showResult?`<div class="doc-target-val"><span>Hasil ${esc(r.year)}</span><b>${indicatorOutcomeValid(id)?scoreText({score:Number(currentIndicatorOutcome(id))})+' '+unit:'Belum tersedia'}</b>${isDummyIndicatorOutcome(id)?'<em class="work-dummy">data dummy</em>':''}</div><div class="doc-target-val doc-target-status"><span>Status</span>${indicatorOutcomeParts(id).badge}<small>${esc(indicatorOutcomeParts(id).note)}</small></div>`:`<div class="doc-target-val"><span>Kenaikan</span><b>${gain===null?'-':(gain>=0?'+':'')+scoreText({score:gain})+' poin'}</b></div>`}</li>`}).join('')}</ul></section>`:''}`}
function docResults(r){if(!(r.evaluationSubmitted||r.status==='Selesai'))return '';const acts=r.activities||[],ev=a=>(r.evaluation||{})[a.id]||{},fo=a=>(r.follow||{})[a.id]||{},pr=a=>(r.progress||{})[a.id]||{},tone=x=>x==='Efektif'?'green':x==='Perlu penyesuaian'?'amber':x==='Tidak efektif'?'red':'gray',list=['Efektif','Perlu penyesuaian','Tidak efektif'],carried=acts.filter(a=>fo(a).carry).length,evaluated=acts.filter(a=>ev(a).result).length;const groups=r.priorities.map(id=>{const own=acts.filter(a=>a.indicator===id);if(!own.length)return '';const rows=own.map(a=>{const e=ev(a),f=fo(a),links=evidenceLinks(pr(a));return {cells:[`<div class="table-indicator-title"><h3>${esc(activitySummaryTitle(a))}</h3><p class="table-secondary">${esc(chainName(a.root)||'Akar masalah belum ditentukan')}</p></div>`,e.result?sdBadge(e.result,tone(e.result)):sdBadge('Belum dievaluasi','gray'),`<p class="sum-text">${esc(e.notes||'Belum ada catatan evaluasi.')}</p>`,links.length?`<ul class="sum-links">${links.map((u,n)=>`<li><a href="${esc(u.url)}" target="_blank" rel="noopener noreferrer">Tautan ${n+1} ↗</a>${u.snp?`<span class="sub"> · ${esc(u.snp)}</span>`:''}</li>`).join('')}</ul>`:'<span class="sub">Data belum tersedia</span>',`<div class="sum-follow">${f.type?sdBadge(f.type,'blue'):''}<p class="sum-text">${esc(f.action||'Belum ada tindak lanjut.')}</p>${f.carry?sdBadge('Dibawa ke RKT berikutnya','green'):''}</div>`]}});return `<div class="doc-result-group"><h4>${esc(ind(id).name)}</h4>${sdTable({caption:'Hasil kegiatan untuk '+ind(id).name,className:'sum-table',columns:[{label:'Kegiatan'},{label:'Hasil evaluasi'},{label:'Alasan penilaian'},{label:'Bukti pelaksanaan'},{label:'Tindak lanjut'}],rows})}</div>`}).join('');return `<div class="doc-section" id="doc-sec-hasil"><section class="saved-docs-card" aria-labelledby="doc-sec-hasil-title"><div class="saved-docs-panel"><div class="review-doc-head"><div><h3 id="doc-sec-hasil-title">Hasil dan Tindak Lanjut</h3><p class="sub">${evaluated} dari ${acts.length} kegiatan sudah dievaluasi.</p></div><div class="doc-outcome-badges">${list.map(x=>{const n=acts.filter(a=>ev(a).result===x).length;return sdBadge(n+' '+x.toLowerCase(),n?tone(x):'gray')}).join('')}${carried?sdBadge(carried+' dibawa ke RKT berikutnya','blue'):''}</div></div>${groups}</div></section></div>`}
function docSection(type){const isRkt=type==='rkt',head=isRkt?['Rencana Kerja Tahunan (RKT)','Tabel kegiatan benahi untuk lampiran RKT.',sdBtn('Unduh Word',{variant:'secondary',leadingIcon:'download',onclick:"downloadDoc('docx')"})+sdBtn('Unduh Excel',{variant:'secondary',leadingIcon:'download',onclick:"downloadDoc('xlsx')"}),reviewRktTable()]:['Rancangan ARKAS (RKAS)','Rincian anggaran yang bisa dibawa ke ARKAS.',sdBtn('Unduh Excel',{variant:'secondary',leadingIcon:'download',onclick:"downloadDoc('rkas')"}),reviewRkasTable()];return `<div class="doc-section" id="doc-sec-${type}"><section class="saved-docs-card" aria-labelledby="doc-sec-${type}-title"><div class="saved-docs-panel"><div class="review-doc-head"><div><h3 id="doc-sec-${type}-title">${head[0]}</h3><p class="sub">${head[1]}</p></div><div class="review-doc-actions">${head[2]}</div></div>${head[3]}</div></section></div>`}
function showDocRecord(kind,index,doc,keepScroll){const current=data,y=window.scrollY;data=recordFor(kind,index);const r=data;docView={kind,index};page='detail';outcomeView='doc';$('#app').innerHTML='';render();const saved=hasSavedPlan(r),done=!!window.__docJustDone&&kind==='current'&&r.status==='Selesai';window.__docJustDone=false;const carried=(r.activities||[]).filter(a=>(r.follow||{})[a.id]?.carry).length;$('.wrap').innerHTML=`<div class="doc-page">${done?sdBanner({tone:'success',title:`Siklus ${r.year} selesai`,children:`<p>Hasil evaluasi dan tindak lanjut sudah tersimpan.${carried?` ${carried} kegiatan dibawa sebagai draf siklus berikutnya.`:''}</p>`,action:`<div class="doc-done-actions">${sdBtn('Mulai siklus '+(Number(r.year.split('/')[0])+1)+'/'+(Number(r.year.split('/')[1])+1),{onclick:'newCycle()',trailingIcon:'arrow-right'})}${sdBtn('Buka hasil dan tindak lanjut',{variant:'secondary',onclick:"docScrollTo('hasil')"})}</div>`}):''}${saved?`${docTabs(r)}<div class="doc-section doc-summary-sec" id="doc-sec-ringkasan">${docSummary(r)}</div>${docSection('rkt')}${docSection('rkas')}${docResults(r)}`:`${docSummary(r)}<div class="notice doc-draft-note"><span>RKT dan RKAS tersedia setelah rencana disimpan.</span>${kind==='current'&&r.status==='Draf'?sdBtn('Hapus draf',{variant:'secondary',onclick:'deleteCurrentDraft()'}):''}</div>`}</div>`;data=current;if(!window.__docSpy){window.__docSpy=true;window.addEventListener('scroll',docSpy,{passive:true})}window.scrollTo(0,0);if(saved&&(doc==='rkas'||(doc==='hasil'&&document.getElementById('doc-sec-hasil'))))docScrollTo(doc,true)}
let showOlderCycles=false;
function cycleRows(){const all=[...(data.priorities.length||data.status!=='Draf'?[dashboardRow(data,'current',0)]:[]),...history.map((h,i)=>dashboardRow(h,'history',i)).reverse()];return all.length>4&&!showOlderCycles?all.slice(0,3):all}
function cycleMore(){const total=(data.priorities.length||data.status!=='Draf'?1:0)+history.length;if(total<=4)return '';const hidden=total-3;return `<div class="cycle-more">${sdBtn(showOlderCycles?'Sembunyikan siklus sebelumnya':`Tampilkan ${hidden} siklus sebelumnya`,{variant:'quiet',trailingIcon:showOlderCycles?'expand-less':'expand-more',onclick:'toggleOlderCycles()'})}</div>`}
document.addEventListener('click',e=>{const tr=e.target.closest&&e.target.closest('.rkt-list tbody tr');if(!tr||e.target.closest('button,a,summary,details'))return;tr.querySelector('.rkt-row-actions button')?.click()});
function toggleOlderCycles(){showOlderCycles=!showOlderCycles;const y=window.scrollY;render();window.scrollTo(0,y)}
function home(){if(data.status==='Draf'&&!data.priorities.length&&!data.activities.length&&!history.length)return sixMIntroduction('start()');const active=data.status==='Sudah ada rencana'&&listRktStatus(data)==='Sudah ada rencana';return `<div class="row"><div><div class="eyebrow">SMA Rakyat 3 · NPSN 20260001</div><h1>Siklus 6M</h1></div>${sdBadge('Tahun ajaran '+data.year,'gray')}</div>${dashboardBanner()}<div class="row section"><div><h2>Siklus Sekolah</h2><p class="muted">Satu perjalanan perbaikan untuk setiap tahun ajaran.</p></div></div><div class="card rkt-table-card">${sdTable({caption:'Daftar siklus sekolah per tahun ajaran',className:'rkt-list',columns:[{label:'Tahun ajaran'},{label:'Prioritas dan kegiatan'},{label:'Langkah'},{label:'Tindakan',align:'right'}],rows:cycleRows()})}${cycleMore()}</div>`}
function sixMIcon(index){const files=['img-expectation-score-arrow-target','img-magnifying-glass-identify','img-document-pencil-fill','img-task-checklist','img-presentation-data-chart','img-circulation-progress-chart-data-document'];return `<img class="sx-art" src="assets/illustrations/${files[index]}.svg" width="60" height="60" alt="" aria-hidden="true">`}
function sixMIntroduction(action){const steps=[['Menetapkan','Pilih prioritas perbaikan sekolah'],['Memetakan','Kenali akar masalahnya'],['Merencanakan','Susun kegiatan dan anggaran'],['Melaksanakan','Jalankan kegiatan yang direncanakan'],['Mengevaluasi','Nilai efektivitas kegiatan sekolah'],['Mengendalikan','Tentukan perbaikan dan tindak lanjut']];const nextYear=data.status==='Selesai'?(Number(data.year.split('/')[0])+1)+'/'+(Number(data.year.split('/')[1])+1):data.year;return `<section class="sx-intro" aria-labelledby="sx-intro-title"><div class="sx-panel"><h2 id="sx-intro-title">Kenali langkah perbaikan sekolah</h2><p class="sx-lede">Enam langkah mengubah data menjadi perbaikan yang berangkat dari kebutuhan murid, selama satu tahun ajaran.</p><ol class="sx-track">${steps.map(([name,description],j)=>`<li><div class="sx-node">${sixMIcon(j)}<b>${j+1}</b></div><h3>${name}</h3><p>${description}</p></li>`).join('')}</ol><div class="sx-loop" aria-hidden="true"><span>Hasil evaluasi menjadi bekal siklus berikutnya</span></div><p class="sr-only">Hasil evaluasi menjadi bekal siklus berikutnya.</p></div><div class="sx-start"><div><div class="sx-start-title"><h2>Siklus ${esc(nextYear)}</h2>${sdBadge(`Belum dimulai`,'gray')}</div><p>Mulai dengan memilih 2–3 prioritas yang paling dibutuhkan murid.</p></div><div class="sx-actions">${sdBtn('Pelajari selengkapnya',{variant:'secondary',size:'lg',onclick:"go('help')"})}${sdBtn('Mulai siklus '+nextYear,{size:'lg',onclick:action,trailingIcon:'arrow-right'})}</div></div></section>`}
function dashboardBanner(){let title,description,action,label,mode='';if(data.status==='Sudah ada rencana'&&data.evaluationSubmitted){mode='followup';title='Jadikan hasil evaluasi sebagai langkah berikutnya';description='Tentukan kegiatan yang perlu diperbaiki, dipertahankan, atau dilanjutkan pada tahun ajaran berikutnya.';label='Lanjutkan tindak lanjut';action='openFollowup()'}else if(data.status==='Sudah ada rencana'&&data.evaluationOpen){mode='evaluation';title='Saatnya meninjau dampak kegiatan sekolah';description=`Periode evaluasi dibuka: ${evaluationWindow()}. Gunakan bukti pelaksanaan untuk menilai efektivitas kegiatan, bukan hanya jumlah kegiatan yang selesai. Bandingkan target dan capaian untuk menentukan langkah perbaikan berikutnya.`;label='Lakukan evaluasi';action='openEvaluation()'}else if(data.status==='Sudah ada rencana'){title='Terus dampingi kemajuan sekolah';description='Catat capaian dan bukti kegiatan yang sudah berjalan. Setiap pembelajaran menjadi bekal untuk perbaikan berikutnya. Masa evaluasi dibuka 1 Juni '+data.year.split('/')[1]+'.';label='Lanjutkan pelaksanaan';action='openExecution()'}else if(data.status==='Draf'&&data.priorities.length){title='Lanjutkan rencana perbaikan sekolah';description='Draf Anda sudah tersimpan. Lengkapi prioritas dan kegiatan untuk memulai perubahan yang berarti bagi murid.';label='Lanjutkan penyusunan';action='start()'}else if(!['Draf','Selesai'].includes(data.status)){title='Rencana sekolah siap dijalankan';description='Tinjau ringkasan rencana dan catat capaian pelaksanaannya.';label='Buka ringkasan rencana';action="go('detail')"}else{title='Mulai rencana baru untuk kemajuan sekolah';description='Pilih 2–3 prioritas yang paling dibutuhkan murid dan rancang kegiatan perbaikannya untuk satu tahun ajaran.';label='Mulai siklus';action=data.status==='Selesai'?'newCycle()':'start()'}if(label==='Mulai siklus')return sixMIntroduction(action);let progressText='';if(data.status==='Sudah ada rencana'&&data.activities.length){const acts=data.activities,n=acts.length,f=data.evaluationSubmitted?acts.filter(a=>data.follow[a.id]?.action?.trim()).length:data.evaluationOpen?acts.filter(a=>data.evaluation[a.id]?.result).length:acts.filter(a=>validExecutionEvidence(data.progress[a.id]?.link)).length,noun=data.evaluationSubmitted?'punya tindak lanjut':data.evaluationOpen?'sudah dievaluasi':'punya tautan bukti';progressText=`${f} dari ${n} kegiatan ${noun}`}const art=mode==='evaluation'?'img-presentation-data-chart':mode==='followup'?'img-circulation-progress-chart-data-document':'img-task-checklist';const cs=cycleStage(data);return `<section class="sx-next" aria-labelledby="sx-next-title"><div class="sx-next-art" aria-hidden="true"><img src="assets/illustrations/${art}.svg" width="72" height="72" alt=""></div><div class="sx-next-copy"><span class="sx-next-eyebrow">Siklus ${esc(data.year)} · Langkah ${Math.min(cs.step,5)+1} dari 6 · ${esc(cs.label.replace('Draf · ',''))}</span><h2 id="sx-next-title">${title}</h2><p>${description}</p>${progressText?`<p class="sx-next-progress">${progressText}</p>`:''}</div>${sdBtn(label,{size:'lg',onclick:action,trailingIcon:'arrow-right'})}</section>`}
function cycleStage(r){if(r.status==='Selesai'){const n=r.activities.length,eff=r.activities.filter(a=>(r.evaluation||{})[a.id]?.result==='Efektif').length;return {label:'Selesai',tone:'green',step:6,note:n?`${eff} dari ${n} kegiatan efektif`:'Enam langkah selesai'}}if(r.evaluationSubmitted)return {label:names[5],tone:'blue',step:5,note:'Langkah 6 dari 6'};if(r.evaluationOpen)return {label:names[4],tone:'amber',step:4,note:'Langkah 5 dari 6 · sampai 30 Juni '+r.year.split('/')[1]};if(listRktStatus(r)==='Sudah ada rencana')return {label:names[3],tone:'blue',step:3,note:'Langkah 4 dari 6'};const k=Number.isInteger(r.lastStep)?r.lastStep:r.activities.length?2:r.priorities.length?1:0;return {label:'Draf · '+names[k],tone:'gray',step:k,note:'Langkah '+(k+1)+' dari 6'}}
function cycleStageCell(r){const c=cycleStage(r);return `<div class="cycle-stage">${sdBadge(c.label,c.tone)}<span class="cycle-stage-note">${c.note}</span></div>`}
function dashboardRow(rkt,kind,index){const primary=sdBtn('Buka siklus',{variant:'secondary',onclick:`showRktRecord('${kind}',${index})`});return [`<span class="sd-cell-title">Siklus ${esc(rkt.year)}</span><span class="sd-cell-sub">Juli ${esc(rkt.year.split('/')[0])} – Juni ${esc(rkt.year.split('/')[1])}</span>`,`${rkt.priorities.length?rkt.priorities.map(id=>`<span class="sd-cell-title">${esc(ind(id).name)}</span>`).join(''):'<span class="sd-cell-sub">Belum ada prioritas</span>'}<span class="sd-cell-sub">${rkt.activities.length} kegiatan</span>`,cycleStageCell(rkt),`<div class="rkt-row-actions">${primary}</div>`]}
function positionRowMenu(el){if(!el.open)return;document.querySelectorAll('.row-overflow').forEach(other=>{if(other!==el)other.open=false});const rect=el.querySelector('summary').getBoundingClientRect();const menu=el.querySelector('.row-overflow-menu');menu.style.right=Math.max(16,window.innerWidth-rect.right)+'px';const height=menu.getBoundingClientRect().height;if(rect.bottom+height+12>window.innerHeight){menu.style.top='auto';menu.style.bottom=(window.innerHeight-rect.top+6)+'px'}else{menu.style.bottom='auto';menu.style.top=(rect.bottom+6)+'px'}}
function sampleArchive(){const s=seed();s.year='2026/2027';s.status='Selesai';s.budget='Disetujui';s.priorities=['lit','num'];s.targets={lit:35,num:50};s.roots={lit:[ind('lit').roots[0]],num:[ind('num').roots[0]]};s.activities=s.priorities.map((id,j)=>({id:'old-'+id,indicator:id,name:j?'Pembelajaran numerasi berbasis masalah sehari-hari':'Pendampingan pembelajaran literasi',root:s.roots[id][0],implementation:j?'Guru mencoba masalah sehari-hari dalam pembelajaran numerasi dan merefleksikan hasilnya bersama.':'Dua guru inti mendampingi praktik membaca teks informasi melalui komunitas belajar.',needsBudget:j===0,budget:j===0?2500000:0,budgetLines:j===0?[{description:'Bahan pendampingan dan bacaan',month:'Agu',quantity:25,unit:'paket',price:100000}]:[],months:[]}));s.evaluationOpen=true;s.evaluationSubmitted=true;s.activities.forEach(a=>{s.progress[a.id]={notes:'Kegiatan terlaksana dan dibahas dalam refleksi bersama guru.',link:'',files:[]};s.evaluation[a.id]={result:'Efektif',notes:'Guru menerapkan praktik pembelajaran yang disepakati.'};s.follow[a.id]={type:'Pemeliharaan',action:'Pertahankan pendampingan dan bagikan praktik baik.',carry:true}});return s}
function recordFor(kind,index){return kind==='current'?data:kind==='history'?history[index]:sampleArchive()}
function showRktRecord(kind,index){showDocRecord(kind,index,'plan')}
function reviseCurrent(){if(data.status!=='Perlu revisi')return;stage=data.revisionKind==='budget'?2:0;go('flow');if(stage===2&&data.activities.length){const a=data.activities[0];data.planSaved={...data.planSaved,[a.indicator]:false};plannerOpen[a.indicator]=1;save();render();document.getElementById(a.id+'-budget')?.focus()}}
function deleteCurrentDraft(){if(data.status!=='Draf')return;if(!confirm('Hapus draf RKT ini beserta seluruh isian dan lampirannya?'))return;const year=data.year;data=seed();data.year=year;save();go('home');toast('Draf dihapus.')}
function evaluationWindow(){return '1–30 Juni '+data.year.split('/')[1]+' (simulasi)'}
function openEvaluation(){if(data.status!=='Sudah ada rencana'||!data.evaluationOpen)return toast('Periode evaluasi belum dibuka.');stage=4;go('flow')}
function openFollowup(){if(data.status!=='Sudah ada rencana'||!data.evaluationSubmitted)return toast('Selesaikan evaluasi terlebih dahulu.');stage=5;go('flow')}
function start(){stage=0;go('flow')}function openCurrent(){if(['Draf','Perlu revisi'].includes(data.status))start();else go('detail')}
function goToPreviousStep(index){const from=pvStage();if(!Number.isInteger(index)||index<0||index>=from)return;save();previewFrom=from>=3&&index<3?from:null;stage=index;if(['menetapkan-alternative','menetapkan-cards'].includes(page))page='flow';render();window.scrollTo(0,0)}
function steps(){return `<nav class="steps" aria-label="Tahap Siklus 6M">${names.map((n,i)=>i<stage?`<button type="button" class="step done" onclick="goToPreviousStep(${i})" aria-label="Kembali ke tahap ${n}"><span class="num">${i+1}</span>${n}</button>`:`<div class="step ${i===stage?'on':''}" ${i===stage?'aria-current="step"':''}><span class="num">${i+1}</span>${n}</div>`).join('')}</nav>`}
const headings=['Tetapkan Prioritas Sekolah','Tentukan Akar Masalah Prioritas Sekolah','Ubah Prioritas Menjadi Langkah Nyata','Catat Langkah yang Sudah Berjalan','Pelajari Dampak Kegiatan Sekolah','Jadikan Pembelajaran sebagai Langkah Berikutnya'];
const descriptions=['Pilih 2–3 indikator yang paling perlu diperbaiki, lalu isi targetnya.','Telaah saran akar masalah dari data Rapor, lalu sesuaikan dengan kondisi nyata sekolah.','Pilih satu atau lebih kegiatan untuk setiap akar masalah, lalu lengkapi penjelasannya agar jelas, terukur, dan dapat dijalankan.','Setiap kemajuan berarti. Catat pelaksanaan, kendala, dan bukti dari kegiatan sehari-hari.','Tinjau implementasi, catatan, dan bukti pelaksanaan untuk menilai efektivitas kegiatan. Refleksi yang jujur membantu sekolah menentukan perbaikan selanjutnya.','Tentukan apa yang perlu diperbaiki, dipertahankan, atau dilanjutkan agar perubahan terus tumbuh. Kegiatan yang perlu penyesuaian ditampilkan lebih dulu.'];
/* Langkah 1-3 satu rangkaian: Indikator, Akar masalah, Kegiatan */
const chainName=r=>String(r||'').split(' · ').slice(1).join(' · ')||String(r||'');
function chainActsFor(id,root){return data.activities.filter(a=>a.indicator===id&&a.root===root)}
function chainScroll(el){if(!el)return;const pm=/^plan-(.+)-root-(\d+)$/.exec(el.id||'');if(pm&&stage===2)return planJump(pm[1],+pm[2]);if(stage===1&&el.dataset&&el.dataset.root&&(el.id||'').indexOf('root-card-')===0)return rootJump(el.dataset.root);const tg=el.closest('.work-act-toggle');if(tg&&tg.getAttribute('aria-expanded')==='false'&&tg.getAttribute('aria-controls')){toggleActForm(tg,tg.getAttribute('aria-controls').replace('act-body-',''),true);requestAnimationFrame(()=>chainScroll(el));return}const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,bb=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--band-bottom'))||0;let ref=el,off=bb+12;const head=el.closest('.plan-card-head');if(head&&head.parentElement)ref=head.parentElement;else{const nest=el.closest('.work-nest-sticky'),sh=nest?.querySelector(':scope > .plan-card-head');if(sh)off+=sh.getBoundingClientRect().height}window.scrollTo({top:Math.max(0,window.scrollY+ref.getBoundingClientRect().top-off),left:0,behavior:reduce?'instant':'smooth'});el.focus?.({preventScroll:true})}
