function flowStageDone(i){if(i>0&&i<=2&&!flowStageDone(i-1))return false;if(i===0)return data.priorities.length>=2&&data.priorities.every(plannerTargetValid);if(i===1)return data.priorities.length>0&&data.priorities.every(indRootsOk);if(i===2)return data.status==='Sudah ada rencana'||(data.priorities.length>0&&data.priorities.every(indPlanOk));return i<stage}
function activeStepCaption(i){const n=data.priorities.length;if(i===0)return n>=2&&data.priorities.every(plannerTargetValid)?'Siap dilanjutkan':'Sedang dikerjakan';if(i===1){const k=data.priorities.filter(indRootsOk).length;return n?`${k} dari ${n} indikator punya akar masalah`:'Sedang dikerjakan'}if(i===2){const k=data.activities.length;return k?`${k} kegiatan disusun`:'Belum ada kegiatan'}return 'Sedang dikerjakan'}
const stepPurposes=['Pilih prioritas perbaikan sekolah','Kenali akar masalahnya','Susun kegiatan dan anggaran','Jalankan kegiatan yang direncanakan','Nilai efektivitas kegiatan sekolah','Tentukan perbaikan dan tindak lanjut'];
