function step1GoTarget(id){if(!document.getElementById('target-'+id))revealIndicator(id);setTimeout(()=>{const f=document.getElementById('target-'+id);if(!f)return;f.scrollIntoView({block:'center',behavior:'smooth'});f.focus({preventScroll:true})},60)}
