function railGoAct(aid,key){const head=document.querySelector(`[aria-controls="act-body-${key}"]`);if(head&&head.getAttribute('aria-expanded')==='false')toggleActForm(head,key,true);railActCur=aid;syncRailOpen();requestAnimationFrame(()=>chainScroll(document.getElementById('act-row-'+aid)))}
function railLink(go,html,act){if(act&&go)return `<button type="button" class="rail-link" onclick="railGoAct('${act[0]}','${act[1]}')">${html}</button>`;if(!go)return `<span class="rail-link">${html}</span>`;return `<button type="button" class="rail-link" onclick="chainScroll(document.getElementById('${go}'))">${html}</button>`}
function railIndOpen(id){return stage===1?actOpen['rootind-'+id]===true:stage===2?(data.roots[id]||[]).some((r,j)=>actOpen['planroot-'+id+'-'+j]===true):false}
function syncRailOpen(){document.querySelectorAll('.priority-slot[data-ind]').forEach(li=>li.classList.toggle('is-open',railIndOpen(li.dataset.ind)));document.querySelectorAll('[data-nest]').forEach(li=>li.classList.toggle('is-open',railActCur===null&&actOpen[li.dataset.nest]===true));document.querySelectorAll('[data-act]').forEach(li=>li.classList.toggle('is-open',railActCur===li.dataset.act))}
function railX(label,call){return `<button type="button" class="slot-remove rail-remove" aria-label="${esc(label)}" title="${esc(label)}" onclick="${call}">${sdIcon('close')}</button>`}
function railRemoveRoot(id,r){const j=[...ind(id).roots,...(data.custom[id]||[])].indexOf(r);if(j<0)return;const y=window.scrollY;setRoot(id,j,false);render();window.scrollTo(0,y)}
function railChain(id,k){const late=stage>=3,rs=data.roots[id]||[];if(!rs.length)return stage===1?`<button type="button" class="rail-pick" onclick="rootJump('${esc(id)}')">Pilih akar masalah</button>`:`<p class="rail-empty">Belum ada akar masalah</p>`;return `<ul class="rail-tree">${rs.map((r,j)=>{const acts=stage>=2?data.activities.filter(a=>a.indicator===id&&a.root===r):[];const go=late?null:stage===1?'root-card-'+id:`plan-${id}-root-${j}`;const rx=stage===1?railX('Lepas akar masalah '+chainName(r),`railRemoveRoot('${esc(id)}','${esc(r).replace(/'/g,"\\'")}')`):'';return `<li${stage===2?` data-nest="planroot-${id}-${j}"${railActCur===null&&actOpen['planroot-'+id+'-'+j]===true?' class="is-open"':''}`:''}><div class="rail-row">${railLink(go,`<span class="rail-num">${k+1}.${j+1}</span><span>${esc(chainName(r))}</span>`)}${rx}</div>${stage>=2?(acts.length?`<ul class="rail-tree rail-acts">${acts.map(a=>`<li data-act="${a.id}"${railActCur===a.id?' class="is-open"':''}><div class="rail-row">${railLink(go,`<span class="rail-num">${actNo(a)}</span><span>${railActTitle(a)}</span>`,stage===2?[a.id,'planroot-'+id+'-'+j]:null)}${stage===2?railX('Lepas kegiatan '+(a.name||'ini'),`removeActivity('${a.id}')`):''}</div></li>`).join('')}</ul>`:(stage===2?`<button type="button" class="rail-pick" onclick="planJump('${esc(id)}',${j})">Pilih kegiatan</button>`:'<p class="rail-empty">Belum ada kegiatan</p>')):''}</li>`}).join('')}</ul>`}
function railHidden(){return false}
function prioritiesRail(){return prioritiesRailSection()}
