function flowPlanButton(){if(stage>2)return '';return sdBtn('Buka rencana Anda',{variant:'secondary',className:'sd-btn-inverse flow-plan-trigger',leadingIcon:'list',attrs:'aria-haspopup="dialog" aria-expanded="false" aria-controls="flow-plan-popover"',onclick:'toggleFlowPlan(this)'})}
