function flowSpy(){const btns=[...document.querySelectorAll('.flow-pv-node[data-anchor]')];if(!btns.length)return;let active=null;for(const b of btns){const el=document.getElementById(b.dataset.anchor);if(el&&el.getBoundingClientRect().top<=140)active=b}if(!active){const o=document.querySelector('.sd-accordion[open]');if(o)active=btns.find(b=>b.dataset.anchor===o.closest('.flow-acc-card')?.id)}btns.forEach(b=>b.removeAttribute('aria-current'));active?.setAttribute('aria-current','location')}
