const noTarget=data.priorities.filter(id=>!plannerTargetValid(id)).length,noRoots=data.priorities.filter(id=>!indRootsOk(id)).length,noActs=data.priorities.filter(id=>!data.activities.some(a=>a.indicator===id)).length;
