const info=stage===0?(n?n+' indikator dipilih'+(n>=3?' (batas maksimal)':' (maksimal 3)'):''):stage===1?`${data.priorities.filter(indRootsOk).length} dari ${n} indikator punya akar masalah`:`${n-noActs} dari ${n} indikator punya kegiatan`;
