const AKREDITASI_SUMBER='Panduan Akreditasi BAN-PDM 2024';
const AKREDITASI_KOMPONEN=[
 {no:1,name:'Kinerja Pendidik dalam Proses Pembelajaran',aspek:[
  ['AK.1.1','Interaksi positif antara pendidik dan peserta didik','Pendidik menghadirkan proses belajar yang sarat interaksi positif, aktif, dan empatik dengan peserta didik.','Pendidik merancang rutinitas interaksi yang hangat dan empatik di kelas, misalnya sapaan pembuka, kesempatan peserta didik menyampaikan pendapat, dan umpan balik yang membangun, lalu saling mengamati praktiknya dalam komunitas belajar. Inspirasi benahi ini mendukung pencapaian standar proses melalui peningkatan standar PTK.'],
  ['AK.1.2','Suasana belajar yang memberi rasa aman','Pendidik menghadirkan suasana belajar yang memberi rasa aman bagi peserta didik dan menunjang keteraturan belajar.','Pendidik dan kepala satuan pendidikan menyepakati aturan kelas yang disusun bersama peserta didik dan menerapkannya secara konsisten agar suasana belajar tertib dan aman. Inspirasi benahi ini mendukung pencapaian standar proses melalui peningkatan standar pengelolaan.'],
  ['AK.1.3','Pengelolaan pembelajaran yang efektif','Pendidik mengelola pembelajaran secara efektif, mulai dari perencanaan, pelaksanaan, hingga asesmen.','Pendidik menyusun perencanaan pembelajaran, kegiatan, dan asesmen yang selaras dengan tujuan pembelajaran pada kurikulum satuan pendidikan, lalu merefleksikannya bersama rekan sejawat secara berkala. Inspirasi benahi ini mendukung pencapaian standar proses melalui peningkatan standar penilaian.'],
  ['AK.1.4','Pembangunan kompetensi dan karakter peserta didik','Pendidik membangun kompetensi dan karakter yang menjadi bekal peserta didik menjadi pribadi yang utuh.','Pendidik merancang kegiatan pembelajaran yang secara sengaja membangun kompetensi dan karakter, misalnya proyek kolaboratif dan refleksi peserta didik, serta memantau perkembangannya. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses.']]},
 {no:2,name:'Kepemimpinan Kepala Satuan Pendidikan dalam Pengelolaan Satuan Pendidikan',aspek:[
  ['AK.2.1','Kepemimpinan yang menumbuhkan pendidik gemar belajar dan berkolaborasi','Kepala satuan pendidikan menghadirkan pendidik dan tenaga kependidikan yang gemar belajar, berefleksi, dan berkolaborasi untuk meningkatkan kualitas pembelajaran.','Kepala satuan pendidikan memfasilitasi komunitas belajar pendidik dan tenaga kependidikan yang rutin berbagi praktik baik dan berefleksi. Inspirasi benahi ini mendukung pencapaian standar pengelolaan melalui peningkatan standar PTK.'],
  ['AK.2.2','Perbaikan layanan berkelanjutan berbasis data','Kepala satuan pendidikan memimpin proses perbaikan layanan yang berkelanjutan, berbasis data, dan melibatkan berbagai pihak.','Kepala satuan pendidikan memimpin proses identifikasi, refleksi, dan perencanaan perbaikan layanan berdasarkan data, misalnya Rapor Pendidikan dan hasil evaluasi kegiatan, dengan melibatkan warga satuan pendidikan. Inspirasi benahi ini mendukung pencapaian standar pengelolaan melalui peningkatan standar proses.'],
  ['AK.2.3','Pemanfaatan anggaran sesuai fokus perbaikan layanan','Anggaran dimanfaatkan sesuai dengan fokus perbaikan layanan yang sudah direncanakan dan disepakati.','Kepala satuan pendidikan dan tim menyusun rencana kegiatan dan anggaran sekolah yang berangkat dari fokus perbaikan layanan yang telah disepakati, lalu memantau penggunaannya. Inspirasi benahi ini mendukung pencapaian standar pengelolaan melalui peningkatan standar pembiayaan.'],
  ['AK.2.4','Pengelolaan sarana dan prasarana untuk pembelajaran','Sarana dan prasarana dikelola secara optimal untuk kebutuhan pembelajaran sebagai pendukung utama belajar.','Satuan pendidikan memetakan kebutuhan sarana dan prasarana dari kebutuhan belajar peserta didik, lalu menata dan memanfaatkannya secara optimal untuk pembelajaran. Inspirasi benahi ini mendukung pencapaian standar sarana dan prasarana melalui peningkatan standar pengelolaan.'],
  ['AK.2.5','Pengelolaan kurikulum satuan pendidikan','Kurikulum satuan pendidikan menjadi rujukan suasana dan proses belajar satu tahun ajaran ke depan, serta memandu pendidik dan tenaga kependidikan.','Kepala satuan pendidikan dan pendidik meninjau dan menyusun kurikulum satuan pendidikan yang menjadi rujukan pembelajaran satu tahun ajaran ke depan dan selaras dengan kurikulum nasional. Inspirasi benahi ini mendukung pencapaian standar isi melalui peningkatan standar pengelolaan.']]},
 {no:3,name:'Iklim Lingkungan Belajar',aspek:[
  ['AK.3.1','Lingkungan belajar yang berkebinekaan','Lingkungan belajar menjaga peserta didik dari paparan contoh perilaku intoleran.','Satuan pendidikan membiasakan kegiatan yang mengenalkan dan menghargai keberagaman, serta menindaklanjuti setiap perilaku intoleran yang ditemukan. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses.'],
  ['AK.3.2','Lingkungan belajar yang inklusif','Satuan pendidikan memenuhi hak setiap peserta didik, termasuk peserta didik dengan kebutuhan yang memerlukan dukungan lebih.','Satuan pendidikan memastikan setiap peserta didik, termasuk yang membutuhkan dukungan lebih, mendapat layanan yang sesuai dengan menyesuaikan pembelajaran dan lingkungan belajar. Inspirasi benahi ini mendukung pencapaian standar proses melalui peningkatan standar sarana dan prasarana.'],
  ['AK.3.3','Rasa aman secara psikis','Seluruh warga satuan pendidikan merasa aman dari perundungan, hukuman fisik, dan kekerasan seksual.','Satuan pendidikan menetapkan dan mensosialisasikan mekanisme pencegahan dan penanganan perundungan, hukuman fisik, dan kekerasan seksual, serta melatih pendidik menjalankannya. Inspirasi benahi ini mendukung pencapaian standar pengelolaan melalui peningkatan standar PTK.'],
  ['AK.3.4','Keselamatan warga satuan pendidikan','Seluruh warga satuan pendidikan terjaga keselamatannya saat berkegiatan di lingkungan belajar.','Satuan pendidikan memeriksa risiko keselamatan di lingkungan belajar dan menyusun prosedur serta latihan keselamatan bagi seluruh warga satuan pendidikan. Inspirasi benahi ini mendukung pencapaian standar sarana dan prasarana melalui peningkatan standar pengelolaan.'],
  ['AK.3.5','Lingkungan belajar yang sehat','Lingkungan belajar menghargai, menjaga, dan membangun kesehatan fisik dan mental warga satuan pendidikan.','Satuan pendidikan membangun kebiasaan sehat fisik dan mental, misalnya kebersihan lingkungan, aktivitas fisik, dan layanan konseling bagi peserta didik. Inspirasi benahi ini mendukung pencapaian standar sarana dan prasarana melalui peningkatan standar proses.']]},
 {no:4,name:'Kompetensi Hasil Pembelajaran Lulusan dan/atau Peserta Didik',aspek:[
  ['AK.4.1','Kompetensi hasil belajar peserta didik','Kompetensi hasil belajar diukur dari data Evaluasi Sistem Pendidikan, yaitu Asesmen Nasional dan Rapor Pendidikan.','Satuan pendidikan menelaah hasil Asesmen Nasional dan Rapor Pendidikan untuk menentukan kompetensi yang perlu diperkuat, lalu merancang pembelajaran yang menjawabnya. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses.']]}
];
/* Hasil akreditasi keseluruhan (contoh dari dokumen tim produk). Skor komponen di bawah hanya contoh yang rata-ratanya 76,3 %, agar
   konsisten dengan 763 / 1000. Bobot antarkomponen dan rumus resminya belum tersedia di prototipe. */
const AKREDITASI_HASIL={skor:763,maks:1000,peringkat:'B',lembaga:'BSANP',keterangan:'Skor akhir visitasi'};
const AKREDITASI_KOMPONEN_SKOR={1:82,2:65,3:78,4:80.2};
const AKREDITASI_NAMA={1:'Kinerja Pendidik dalam Proses Pembelajaran',2:'Kepemimpinan Kepala Satuan Pendidikan',3:'Iklim Lingkungan Belajar',4:'Kompetensi Hasil Pembelajaran Peserta Didik'};
(function(){for(let k=indicators.length-1;k>=0;k--)if(indicators[k].id==='akre')indicators.splice(k,1);
AKREDITASI_KOMPONEN.forEach(k=>{const code='AK.'+k.no,h=AKREDITASI_HASIL;
indicators.push({id:code,code,name:AKREDITASI_NAMA[k.no],source:'Akreditasi',origin:h.lembaga,score:AKREDITASI_KOMPONEN_SKOR[k.no],unit:'%',max:100,level:'Nilai contoh',color:'blue',desc:'Mutu Manajemen',period:'Periode tidak dicantumkan',
definition:k.name+'. Komponen kinerja dalam instrumen akreditasi BAN-PDM 2024, dinilai bersama tiga komponen lain untuk menetapkan peringkat akreditasi satuan pendidikan.',
komponen:k.no,achievementDefinition:'Capaian komponen berupa contoh, dengan rata-rata keempat komponen 76,3 % agar sesuai skor akhir 763 / 1000. Bobot tiap komponen mengikuti instrumen resmi BAN-PDM dan belum tersedia di prototipe.',
children:k.aspek.map(([c,name,definition])=>({code:c,name,score:null,previous:null,unit:'',level:'',definition,achievementDefinition:'',unavailableReason:'Skor per aspek belum tersedia di prototipe',rankProvince:'',rankNational:'',source:AKREDITASI_SUMBER})),
roots:k.aspek.map(([c,name])=>c+' · '+name),rootReference:null});
activityRecommendations[code]=Object.fromEntries(k.aspek.map(([c,,,rec])=>[c,[rec]]))})})();

/* TKA: struktur kompetensi dan capaian nasional dari portal Hasil TKA (Pusat Asesmen Pendidikan, SMA/SMK, tahun pelajaran 2025/2026).
   Kompetensi menjadi sub-indikator dan calon akar masalah. Nilai sekolah ada di balik login portal, jadi yang tampil adalah capaian nasional.
   Saran kegiatan masih draf bertemplat. Mata pelajaran lain belum dimuat. */
const TKA_SUMBER='Hasil TKA 2025/2026, Pusat Asesmen Pendidikan';
const TKA_MAPEL={
 'tka2':{kode:'S.L1',jenis:'elemen',mapel:'Matematika',nasional:{rerata:36.10,istimewa:2.17,baik:19.21,memadai:33.90,kurang:44.71},
  kompetensi:[['Bilangan',[['Bilangan Real',30.09]]],['Aljabar',[['Fungsi',32.99],['Barisan dan Deret',28.11],['Persamaan dan Pertidaksamaan Linear',24.11]]],['Geometri dan Pengukuran',[['Objek Geometri',39.19],['Transformasi Geometri',18.28],['Pengukuran',22.67],['Perbandingan Trigonometri',46.14]]],['Data dan Peluang',[['Data',29.25],['Peluang',18.92]]]]},
 'tka-bindo':{kode:'S.L4',jenis:'kompetensi',mapel:'Bahasa Indonesia',nasional:{rerata:55.38,istimewa:39.92,baik:41.55,memadai:14.98,kurang:3.56},
  kompetensi:[['Pemahaman Tekstual',[['Mengidentifikasi penggunaan kata serapan dari bahasa daerah/asing dalam berbagai bidang',53.03],['Mengidentifikasi latar, karakter, dan/atau fenomena berdasarkan kosakata yang digunakan dalam teks fiksi atau nonfiksi',43.79],['Menyusun kerangka atau bagan berdasarkan bagian-bagian penting dalam teks',57.84]]],
   ['Pemahaman Inferensial',[['Menyimpulkan ide pokok, gagasan pendukung, tokoh, peristiwa, latar, konflik, atau nilai-nilai dalam teks',42.12],['Menjelaskan hubungan makna antarkalimat dan/atau antarparagraf dalam teks',47.24],['Memprediksi lanjutan atau akhir uraian/cerita berdasarkan bagian tertentu dalam teks',41.37]]],
   ['Evaluasi dan Apresiasi',[['Menilai ketepatan dan kesesuaian penggunaan bahasa dalam teks',35.62],['Menyimpulkan respons emosional terhadap unsur puisi, prosa, dan drama',53.34],['Menilai relevansi peristiwa dalam teks dengan kehidupan sehari-hari',64.28],['Menilai keakuratan, kesesuaian, kecukupan, atau ketepatan informasi dalam teks',48.86],['Menilai ketepatan bagian teks untuk menggambarkan karakter, peristiwa, atau latar dalam teks fiksi',43.90]]]]}
};
(function(){
 Object.entries(TKA_MAPEL).forEach(([id,m])=>{const a=indicators.find(i=>i.id===id);if(!a)return;let n=0;const rows=[];
  m.kompetensi.forEach(([komp,subs])=>subs.forEach(([name,pct])=>{n+=1;rows.push({code:m.kode+'.'+n,name,pct,komp})}));
  a.tkaNasional=m.nasional;a.tkaMapel=m.mapel;
  a.children=[...rows].sort((x,y)=>x.pct-y.pct).map(r=>({code:r.code,name:r.name,score:r.pct,previous:null,unit:'% nasional',level:'',definition:'Bagian dari '+m.jenis+' '+r.komp+' pada TKA '+m.mapel+'.',achievementDefinition:'Persentase capaian siswa SMA/SMK secara nasional pada tahun pelajaran 2025/2026. Capaian sekolah Anda tersedia di portal Hasil TKA setelah login.',unavailableReason:'',rankProvince:'',rankNational:'',source:TKA_SUMBER}));
  a.roots=rows.map(r=>r.code+' · '+r.name);a.rootReference=null;
  activityRecommendations[a.code]=Object.fromEntries(rows.map(r=>[r.code,['Pendidik merancang kegiatan pembelajaran dan latihan yang berfokus pada '+(m.mapel==='Matematika'?'topik '+r.name:'kemampuan "'+r.name+'"')+', lalu menelaah hasil asesmen formatif untuk menyesuaikan pembelajaran. Inspirasi benahi ini mendukung pencapaian standar kompetensi lulusan melalui peningkatan standar proses dan standar penilaian.']]))});
 const mat=indicators.find(i=>i.id==='tka2'),bi=indicators.find(i=>i.id==='tka-bindo');
 if(mat&&bi&&!indicators.some(i=>i.id==='tka-rerata'))indicators.splice(indicators.indexOf(mat),0,{id:'tka-rerata',code:'S.L2',name:'Rerata nilai TKA',source:'TKA',origin:'Hasil TKA',score:Math.round((mat.score+bi.distribution.istimewa+bi.distribution.baik)/2*10)/10,unit:'',max:100,level:'',color:'',desc:'Mutu Lulusan · SNP: SKL',period:'2025',definition:'Capaian hasil belajar peserta didik pada mata pelajaran yang diujikan melalui TKA.',tkaGabungan:true,roots:[],
  children:[mat,bi].map((x,k)=>({code:'S.L2.'+(k+1),name:x.tkaMapel||x.name,score:x.distribution?Math.round((x.distribution.istimewa+x.distribution.baik)*10)/10:x.score,previous:null,unit:x.distribution?'% siswa Baik atau Istimewa':'rerata nilai',level:'',definition:'Capaian sekolah pada TKA '+(x.tkaMapel||x.name)+'.',achievementDefinition:'',unavailableReason:'',rankProvince:'',rankNational:'',source:TKA_SUMBER}))})
})();
const plannerOpen={};
function plannerTargetValid(id){const v=Number(data.targets[id]);return data.targets[id]!==undefined&&data.targets[id]!==''&&Number.isFinite(v)&&v>=0&&v<=ind(id).max&&(typeof ind(id).score!=='number'||v>ind(id).score)}
function activityBasicsValid(a){return !!(a.name.trim()&&a.root&&(data.roots[a.indicator]||[]).includes(a.root)&&(a.implementation||'').trim())}

function activitySuccessValid(a){return a.target.trim()&&Number(a.quantity)>0&&a.unit.trim()&&a.proof.trim()}
function planningTargetPanel(id){const i=ind(id),target=data.targets[id],hasTarget=target!==undefined&&target!=='';return `<div class="planning-target-panel"><div><span>Capaian awal ${esc(i.period||'—')}</span><strong>${scoreText(i)} ${esc(i.unit||'')}</strong></div><div><span>Target ${esc(data.year)}</span><strong>${hasTarget?`${scoreText({score:Number(target)})} ${esc(i.unit||'skor')}`:'Belum ditetapkan'}</strong></div></div>`}
function planGroupHead(id){return `<div class="plan-card-title"><h3>Akar masalah dari ${esc(ind(id).name)}</h3></div>`}
function planRootRows(id,root,j){const out=[],none='<span class="table-no-comparison" aria-hidden="true">–</span><span class="sr-only">Belum ada</span>';const code=root.split(' · ')[0],list=(activityRecommendations[ind(id).code]||{})[code]||[],acts=chainActsFor(id,root),own=acts.filter(a=>!a.recommendationKey);
if(!list.length)out.push({full:`<div class="roots-own">${sdBanner({tone:'info',children:'<p>Belum ada rekomendasi kegiatan. Tambahkan sendiri di bawah.</p>'})}</div>`});
list.forEach((text,index)=>{const key=ind(id).code+':'+code+':'+index,chosenActivity=data.activities.find(a=>a.indicator===id&&a.recommendationKey===key&&a.root===root)||data.activities.find(a=>a.indicator===id&&a.recommendationKey===key),chosen=!!chosenActivity,title=activitySummaryTitle({name:text,recommendationKey:key}),rid=`rec-${id}-${code}-${index}`;
out.push({selected:chosen,set:chosen,cells:[sdCheckbox({ariaLabel:(chosen?'Batalkan pilihan ':'Pilih ')+title,checked:chosen,onchange:chosen?`removeActivity('${chosenActivity.id}')`:`selectRecommendedActivity('${id}','${code}',${index})`}),`<div class="table-indicator-title"><h3${chosenActivity?` id="act-row-${chosenActivity.id}" tabindex="-1"`:''}>${esc(title)}</h3></div>`,`<p class="plan-desc-text is-clamped" id="${rid}">${esc(text)}</p>${sdBtn('Selengkapnya',{variant:'quiet',size:'sm',className:'btn-link-dark',attrs:`aria-expanded="false" aria-controls="${rid}"`,onclick:'toggleRecommendation(this)'})}`]});
if(chosen)out.push({end:true,attrs:'class="sd-row-selected menetapkan-expand-row"',full:`<div class="plan-activity-form">${implField(chosenActivity)}${budgetPart(chosenActivity)}</div>`})});
own.forEach(a=>{out.push({selected:true,set:true,cells:[sdCheckbox({ariaLabel:'Batalkan pilihan '+(a.name||'kegiatan'),checked:true,onchange:`removeActivity('${a.id}')`}),`<div class="table-indicator-title"><h3 id="act-row-${a.id}" tabindex="-1">${esc(a.name||'Kegiatan belum diberi nama')} ${sdBadge('Dari sekolah','gray')}</h3></div>`,none]});out.push({end:true,attrs:'class="sd-row-selected menetapkan-expand-row"',full:`<div class="plan-activity-form">${implField(a)}${budgetPart(a)}</div>`})});
const ok=!!(data.actOther||{})[id+'-'+j];out.push({selected:ok,cells:[sdCheckbox({ariaLabel:'Tambah kegiatan lain dari sekolah',checked:ok,onchange:`toggleActOther('${id}',${j},this.checked)`}),'<div class="table-indicator-title"><h3>Kegiatan lain dari sekolah</h3></div>',none]});
if(ok)out.push({attrs:'class="sd-row-selected menetapkan-expand-row"',full:`<div class="plan-activity-form plan-own-field">${sdTextField({label:'Kegiatan dari sekolah',hideLabel:true,id:'own-'+id+'-'+j,placeholder:'Tulis nama kegiatan dari sekolah',attrs:`onkeydown="if(event.key==='Enter'){event.preventDefault();addOwnActivity('${id}',${j})}"`,trailing:sdBtn('Tambah',{variant:'secondary',leadingIcon:'add',onclick:`addOwnActivity('${id}',${j})`})})}</div>`})
return out}
function planOtherRows(id){const rs=data.roots[id]||[],orphan=data.activities.filter(a=>a.indicator===id&&!rs.includes(a.root)),out=[];
if(!rs.length)out.push({full:`<div class="roots-own">${sdBanner({tone:'warning',title:'Belum ada akar masalah',children:'<p>Pilih akar masalah di langkah 2 agar kegiatan bisa disusun untuk menjawabnya.</p>'})}</div>`});
if(orphan.length)out.push({full:`<div class="roots-own">${sdBanner({tone:'warning',title:'Kegiatan tanpa akar masalah terpilih',children:'<p>Akar masalah untuk kegiatan ini tidak dipilih lagi di langkah 2. Pilih kembali akar masalahnya, atau hapus kegiatannya.</p>'})}${orphan.map(a=>activityForm(a,false,true)).join('')}</div>`});
return out}
function planCard(headId,num,title,rows,caption,forName){return `<section class="plan-card menetapkan-table-scroll"><div class="plan-card-head" id="${headId}" tabindex="-1"><div class="plan-card-title">${num?`<span class="plan-card-num" aria-hidden="true">${num}</span>`:''}<div class="plan-card-text">${forName?`<span class="plan-card-for">Indikator: ${forName}</span>`:''}<h3>${title}</h3></div></div></div>${sdTable({caption,className:'menetapkan-indicator-table plan-table',columns:[{label:'Pilih'},{label:'Kegiatan'},{label:'Deskripsi'}],rows})}</section>`}
function planning(){const cards=data.priorities.map((id,k)=>{const rs=data.roots[id]||[],i=ind(id),other=planOtherRows(id);let inner=rs.map((r,j)=>{const key='planroot-'+id+'-'+j,open=nestOpen(key),n=data.activities.filter(a=>a.indicator===id&&a.root===r).length;return `<div class="work-root-group">`+nestHead(key,open,'work-root-head',`<span class="plan-card-num" aria-hidden="true">${k+1}.${j+1}</span><h4 id="plan-${id}-root-${j}" tabindex="-1">${esc(chainName(r))}</h4>${nestCount(n,'kegiatan dipilih','Belum ada kegiatan dipilih')}`)+`<div class="work-root-body" id="act-body-${key}"${open?'':' hidden'}>${sdTable({caption:'Kegiatan untuk '+chainName(r),className:'menetapkan-indicator-table plan-table',columns:[{label:'Pilih'},{label:'Kegiatan'},{label:'Deskripsi'}],rows:planRootRows(id,r,j)})}</div></div>`}).join('');if(other.length)inner+=`<div class="work-root-body work-root-other">${sdTable({caption:'Kegiatan tanpa akar masalah terpilih',className:'menetapkan-indicator-table plan-table',columns:[{label:'Pilih'},{label:'Kegiatan'},{label:'Deskripsi'}],rows:other})}</div>`;return `<section class="plan-card menetapkan-table-scroll work-nest work-nest-plan"><div class="plan-card-head" id="plan-${id}" tabindex="-1"><div class="plan-card-title"><span class="plan-card-num" aria-hidden="true">${k+1}</span><h3>${esc(i.name)}</h3></div></div>${inner}</section>`});return `<div class="chain-wrap menetapkan-table-layout"><section class="menetapkan-table-content" aria-label="Daftar kegiatan">${selectedCard()}<div class="step1-layout"><div class="step1-list"><h2 class="sd-sr-only">Pilih kegiatan</h2>${cards.join('')}</div></div></section></div>`}
function toggleDescription(btn){const p=document.getElementById(btn.getAttribute('aria-controls'));p.hidden=!p.hidden;btn.setAttribute('aria-expanded',String(!p.hidden));const t=[...btn.childNodes].find(n=>n.nodeType===3&&n.textContent.trim())||btn.querySelector('span');if(t)t.textContent=p.hidden?'Baca Deskripsi':'Sembunyikan Deskripsi'}
function toggleRecommendation(btn){const p=document.getElementById(btn.getAttribute('aria-controls'));const open=p.classList.toggle('is-clamped')===false;btn.setAttribute('aria-expanded',String(open));btn.firstChild.textContent=open?'Ringkas':'Selengkapnya'}
function chainRootGroup(id,root,j,total){const code=root.split(' · ')[0],list=(activityRecommendations[ind(id).code]||{})[code]||[],acts=chainActsFor(id,root),own=acts.filter(a=>!a.recommendationKey);const items=list.map((text,index)=>{const key=ind(id).code+':'+code+':'+index;const chosenActivity=data.activities.find(a=>a.indicator===id&&a.recommendationKey===key&&a.root===root)||data.activities.find(a=>a.indicator===id&&a.recommendationKey===key);const chosen=!!chosenActivity;return `<div class="recommendation-item ${chosen?'is-chosen':''}"><div class="recommendation-main"><h5 class="recommendation-title">${esc(activitySummaryTitle({name:text,recommendationKey:key}))}</h5><p class="recommendation-description is-clamped" id="rec-${id}-${code}-${index}">${esc(text)}</p>${sdBtn('Selengkapnya',{variant:'quiet',size:'sm',attrs:`aria-expanded="false" aria-controls="rec-${id}-${code}-${index}"`,onclick:'toggleRecommendation(this)'})}</div><div class="recommendation-choose">${sdCheckbox({label:chosen?'Dipilih':'Pilih',ariaLabel:(chosen?'Batalkan pilihan ':'Pilih ')+activitySummaryTitle({name:text,recommendationKey:key}),checked:chosen,onchange:chosen?`removeActivity('${chosenActivity.id}')`:`selectRecommendedActivity('${id}','${code}',${index})`})}</div>${chosen?activityForm(chosenActivity,true):''}</div>`}).join('');const ownItems=own.map(a=>`<div class="recommendation-item is-chosen"><div class="recommendation-main"><h5 class="recommendation-title">${esc(a.name||'Kegiatan belum diberi nama')} ${sdBadge('Dari sekolah','gray')}</h5></div><div class="recommendation-choose">${sdCheckbox({label:'Dipilih',ariaLabel:'Batalkan pilihan '+(a.name||'kegiatan'),checked:true,onchange:`removeActivity('${a.id}')`})}</div>${activityForm(a,true,true)}</div>`).join('');return `<section class="chain-group" id="plan-${id}-root-${j}" tabindex="-1" aria-label="Kegiatan untuk ${esc(chainName(root))}"><div class="chain-group-head"><div><p class="chain-eyebrow">Akar masalah ${j+1} dari ${total}</p><h3>${esc(chainName(root))}</h3></div><span class="chain-count">${acts.length?acts.length+' kegiatan dipilih':'Belum ada kegiatan'}</span></div><h4 class="chain-instruction">Pilih kegiatan yang akan dijalankan <span class="chain-aside">boleh lebih dari satu</span></h4>${list.length?items:sdBanner({tone:'info',children:'<p>Belum ada rekomendasi kegiatan. Tambahkan sendiri di bawah.</p>'})}${ownItems}${sdTextField({label:'Kegiatan dari sekolah',id:'own-'+id+'-'+j,placeholder:'Tulis nama kegiatan',trailing:sdBtn('Tambah',{variant:'secondary',leadingIcon:'add',onclick:`addOwnActivity('${id}',${j})`})})}</section>`}
function addOwnActivity(id,j){const input=document.getElementById('own-'+id+'-'+j),name=(input?.value||'').trim();if(!name)return toast('Tulis nama kegiatan dulu.');const rs=data.roots[id]||[];const a={id:'a'+Date.now(),indicator:id,name,root:rs[j]??rs[0]??'',target:'',quantity:'',unit:'',proof:'',realistic:'',relevant:'',months:[],budget:0};data.activities.push(a);data.actOther={...(data.actOther||{}),[id+'-'+j]:false};plannerOpen[id]=1;save();render();document.getElementById(a.id+'-implementation')?.focus()}
function toggleActOther(id,j,on){data.actOther={...(data.actOther||{}),[id+'-'+j]:on};save();render();if(on)setTimeout(()=>document.getElementById('own-'+id+'-'+j)?.focus(),0)}

function rememberPlanner(el){if(!el.isConnected)return;if(el.open){plannerOpen[el.dataset.plan]=Number(el.dataset.step);document.querySelectorAll('.guided-step').forEach(other=>{if(other!==el&&other.dataset.plan===el.dataset.plan)other.open=false})}}
function advancePlanner(id,step){if(!plannerTargetValid(id)){toast('Tetapkan target yang valid di atas capaian awal sesuai skala indikator.');plannerOpen[id]=0;render();return}const acts=data.activities.filter(a=>a.indicator===id);if(step===2&&(!acts.length||acts.some(a=>!activityBasicsValid(a)))){toast('Lengkapi penjelasan implementasi kegiatan. Seluruh rincian anggaran bersifat opsional.');return}plannerOpen[id]=step;render();document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function recommendationShortDescription(code,index){const topics={'A.1.1':'membaca teks informasi','A.2.1':'domain bilangan','D.8.1':'toleransi agama dan budaya','D.6.1':'kesetaraan gender','D.4.8':'pencegahan dan penanganan kekerasan seksual','D.1.2':'dukungan psikologis','A.3.5':'kebinekaan global'};if(code==='D.3.1')return ['Selaraskan visi-misi sekolah dengan kebutuhan murid, perencanaan, dan penganggaran.','Bantu guru menerjemahkan visi-misi sekolah menjadi praktik pembelajaran.','Refleksikan penerapan visi-misi bersama warga sekolah untuk menentukan perbaikan.'][index]||'';const topic=topics[code]||'prioritas sekolah';if(index===0)return 'Perkuat pemahaman tentang '+topic+' melalui pelatihan, komunitas belajar, atau belajar mandiri.';if(index===1)return 'Terapkan '+topic+' dalam kegiatan intrakurikuler, kokurikuler, atau ekstrakurikuler.';if(index===2)return 'Siapkan program dan kebijakan sekolah yang mendukung '+topic+'.';if(index===3)return 'Penuhi kebutuhan buku teks dan nonteks untuk mendukung pembelajaran dan literasi.';return ''}
function selectRecommendedActivity(id,code,index){const text=activityRecommendations[ind(id).code]?.[code]?.[index];const root=(data.roots[id]||[]).find(r=>r.split(' · ')[0]===code);if(!text||!root)return;const key=ind(id).code+':'+code+':'+index;if(data.activities.some(a=>a.indicator===id&&a.recommendationKey===key))return;const blank=data.activities.find(a=>a.indicator===id&&!a.name.trim()&&!a.target.trim()&&!a.realistic.trim()&&!a.relevant.trim()&&!a.months.length&&!Number(a.budget)&&!a.proof.trim()&&!a.quantity);const activity=blank||{id:'a'+Date.now(),indicator:id,target:'',quantity:'',unit:'',proof:'',realistic:'',relevant:'',months:[],budget:0};Object.assign(activity,{name:text,root,recommendationKey:key});if(!blank)data.activities.push(activity);plannerOpen[id]=1;data.planSaved={...data.planSaved,[id]:false};save();render();document.getElementById(activity.id+'-implementation')?.focus();toast('Kegiatan ditambahkan. Lengkapi penjelasan dan rencana pelaksanaannya.')}
function finishPlanner(id){const acts=data.activities.filter(a=>a.indicator===id);if(!acts.length)return toast('Pilih atau tambahkan minimal satu kegiatan untuk prioritas ini.');if(acts.some(a=>!activityBasicsValid(a)))return toast('Lengkapi penjelasan implementasi kegiatan. Rincian anggaran dapat dilengkapi nanti.');data.planSaved={...data.planSaved,[id]:true};save();render();document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});toast('Rencana prioritas tersimpan.')}

function upd(id,k,v){let a=data.activities.find(a=>a.id===id);a[k]=v;save()}
function field(a,k,label,placeholder,type='text'){return sdTextField({label:label.replace(/ \*$/,''),id:a.id+'-'+k,type,value:a[k],placeholder,attrs:type==='number'?'min="0"':'',oninput:`upd('${a.id}','${k}',this.value)`})}
function implField(a){return sdTextArea({label:'Apa yang akan dilakukan?',placeholder:'Tuliskan singkat apa yang akan dilakukan sekolah.',id:a.id+'-implementation',value:a.implementation||'',rows:3,oninput:`upd('${a.id}','implementation',this.value)`})}
function budgetPart(a){return `<div class="activity-budget-part">${sdRadioGroup({legend:'Apakah kegiatan ini membutuhkan anggaran?',name:'budget-'+a.id,options:[{value:'ya',label:'Ya'},{value:'tidak',label:'Tidak'}],value:a.needsBudget===true?'ya':a.needsBudget===false&&a.budgetAnswered?'tidak':'',onchange:`setActivityCost('${a.id}',this.value==='ya')`})}${a.needsBudget?budgetLineForm(a):''}</div>`}
function activityForm(a,inline=false,inGroup=false){return `<div class="card activity-card guided-activity">${inline?'':`<div class="row"><h3>Kegiatan ${data.activities.filter(x=>x.indicator===a.indicator).indexOf(a)+1}</h3>${sdBtn('Hapus kegiatan',{variant:'destructive-secondary',size:'sm',onclick:`removeActivity('${a.id}')`})}</div>`}${a.recommendationKey?(inline?'':`<p class="activity-chosen-name">${esc(a.name)}</p><p class="sub">Menjawab: ${esc(String(a.root||'').replace(' · ',', '))}</p>`):`${inline?'':field(a,'name','Nama kegiatan','Tuliskan kegiatan pilihan sekolah')}${inGroup&&(data.roots[a.indicator]||[]).includes(a.root)?'':sdSelect({label:'Akar masalah yang ingin dijawab',value:a.root,onchange:`upd('${a.id}','root',this.value)`,options:[...(data.roots[a.indicator]||[]),...((data.roots[a.indicator]||[]).includes(a.root)||!a.root?[]:[a.root])].map(r=>({value:r,label:r.replace(' · ',', ')}))})}`}${sdTextArea({label:'Apa yang akan dilakukan?',id:a.id+'-implementation',helper:'Tuliskan singkat apa yang akan dilakukan sekolah.',value:a.implementation||'',oninput:`upd('${a.id}','implementation',this.value)`})}${sdCheckbox({label:'Kegiatan ini membutuhkan anggaran',checked:a.needsBudget===true,onchange:`setActivityCost('${a.id}',this.checked)`})}${a.needsBudget?budgetLineForm(a):''}</div>`}
function setActivityCost(id,value){const a=data.activities.find(a=>a.id===id);a.needsBudget=value;a.budgetAnswered=true;if(value&&!a.budgetLines?.length)a.budgetLines=[{code:'',description:'',month:'',quantity:'',unit:'',price:''}];recalculateActivityBudget(a);save();render()}
function recalculateActivityBudget(a){a.budget=a.needsBudget?(a.budgetLines||[]).filter(r=>r.description.trim()).reduce((sum,r)=>sum+(Number(r.quantity)||0)*(Number(r.price)||0),0):0;a.months=a.needsBudget?[...new Set((a.budgetLines||[]).filter(r=>r.description.trim()&&r.month).flatMap(r=>budgetMonths(r.month)))]:[]}
const ARKAS_ACTIVITIES=["Peningkatan Kompetensi Guru untuk asesmen, umpan balik dan pelaporan yang berpusat pada peserta didik", "Penyiapan dan Pelaksanaan Asesmen di Awal Pembelajaran", "Penyusunan kisi-kisi dan penyusunan soal penilaian formatif (ulangan harian)", "Pelaksanaan refleksi pembelajaran", "Penyelenggaraan Perbaikan/Pengayaan (Remedial)", "Pelaksanaan supervisi pembelajaran semua mapel/guru di sekolah", "Pelaksanaan kegiatan komunitas belajar di satuan pendidikan", "Penyusunan kurikulum", "Peningkatan Kompetensi Kepala Sekolah", "Penyusunan silabus/tujuan pembelajaran", "Peningkatan kompetensi pendidik untuk memahami kurikulum dan cara mengajarkannya", "Pelaksanaan kegiatan orientasi murid baru yang bersifat akademik dan pengenalan lingkungan tanpa kekerasan", "Penerapan program pencegahan perundungan", "Peningkatan kompetensi pendidik untuk memahami tentang perundungan, kekerasan, dan kekerasan seksual", "Pengembangan program pencegahan dan penanganan kekerasan di satuan pendidikan (termasuk Program Roots)", "Peningkatan kompetensi pendidik untuk pengelolaan lingkungan pembelajaran yang aman dan nyaman", "Peningkatan kompetensi pendidik untuk memahami sikap inklusif, toleran, dan kesertaan gender (termasuk pendidikan inklusif/disabilitas)", "Pengembangan sekolah sehat, sekolah aman, sekolah ramah anak, sekolah inklusi, sekolah adiwiyata, dan sejenisnya", "Pengembangan/peningkatan kompetensi pendidik dan tenaga kependidikan yang menangani Murid berkebutuhan khusus", "Pengembangan pembelajaran berbasis proyek", "Pengembangan kegiatan pelibatan orang tua/wali/keluarga di pembelajaran", "Peningkatan kompetensi pendidik untuk memahami toleransi/kesetaraan/moderasi beragama dan budaya", "Peningkatan Kompetensi Guru untuk pengelolaan lingkungan pembelajaran yang aman dan nyaman", "Penguatan pendidikan karakter dan penumbuhan budi pekerti", "Peningkatan Kompetensi Guru untuk memahami toleransi/kesetaraan/moderasi beragama dan budaya", "Peningkatan Kompetensi Guru untuk Pemahaman Profil Pelajar Pancasila: Nalar Kritis", "Pelaksanaan Ekstrakurikuler Kepramukaan", "Pelaksanaan Kegiatan Ekstrakurikuler (diluar Kepramukaan)", "Peningkatan kompetensi pendidik untuk keterlibatan orangtua/wali dan masyarakat dalam pembelajaran", "Peningkatan kompetensi pendidik untuk memahami karakteristik dan cara belajar murid", "Pelatihan pembelajaran mendalam", "Pengembangan inovasi terkait konten pembelajaran dan metode pembelajaran", "Penyelenggaraan Pembelajaran aktif, kreatif, efektif, dan nyaman", "Mengembangkan media pembelajaran berbasis teknologi informasi dan komunikasi", "Pelatihan implementasi digitalisasi pembelajaran", "Peningkatan kompetensi pendidik untuk memperkuat literasi", "Pengembangan kegiatan literasi dan numerasi", "Kegiatan pemberdayaan perpustakaan terutama untuk pengembangan minat baca murid", "Pengadaan buku/koleksi perpustakaan (selain buku teks, pengayaan, dan referensi)", "Pengadaan Buku Teks Utama/Pendamping murid", "Pengadaan Buku Teks Utama/Pendamping Pendidik", "Pengadaan buku pengayaan dan referensi", "Penyediaan buku nonteks", "Penyusunan kisi-kisi dan penyusunan soal penilaian sumatif (ulangan tengah semester/akhir semester/kenaikan kelas)", "Pelaksanaan kegiatan kelompok belajar di satuan pendidikan", "Peningkatan Kompetensi Guru untuk memperkuat numerasi", "Peningkatan kompetensi pendidik untuk pembelajaran berorientasi pada murid", "Penyediaan atau pembuatan media pembelajaran", "Peningkatan Kompetensi Guru untuk memahami konten pembelajaran dan cara mengajarkannya", "Peningkatan Kompetensi Pendidik untuk asesmen, umpan balik dan pelaporan yang berpusat pada murid"].map((description,i)=>({code:`${12+i%4}.${120+i}.${30+(i*3)%40}`,description}));
const arkasLabel=r=>r.code&&r.description?r.code+' – '+r.description:(r.description||r.code||'');
function setBudgetArkas(id,j,el){const a=data.activities.find(a=>a.id===id),v=el.value.trim(),hit=ARKAS_ACTIVITIES.find(x=>arkasLabel(x)===v),typed=v.match(/^(\d{2}\.\d{3}\.\d{2})\s*[–-]\s*(.+)$/),r=a.budgetLines[j];r.code=hit?hit.code:typed?typed[1]:'';r.description=hit?hit.description:typed?typed[2]:v;recalculateActivityBudget(a);save();el.title=v;document.getElementById('activity-total-'+id).textContent=money(a.budget)}
function budgetLineForm(a){return `<section class="activity-budget-lines"><datalist id="arkas-options-${a.id}">${ARKAS_ACTIVITIES.map(x=>`<option value="${esc(arkasLabel(x))}"></option>`).join('')}</datalist><h4>Rincian anggaran kegiatan ${sdBadge('Opsional','gray')}</h4><div class="budget-line-list">${(a.budgetLines||[]).map((r,j)=>`<div class="budget-line" role="group" aria-label="Rincian ${j+1}"><div class="budget-line-head"><b>Rincian ${j+1}</b>${sdBtn('Hapus rincian '+(j+1),{variant:'destructive-secondary',size:'sm',leadingIcon:'close',onclick:`removeBudgetLine('${a.id}',${j})`})}</div><div class="budget-line-top">${sdTextField({label:'Kegiatan ARKAS',id:`${a.id}-bl${j}-arkas`,placeholder:'Pilih dari daftar atau ketik uraian sendiri',value:arkasLabel(r),attrs:`list="arkas-options-${a.id}" autocomplete="off" title="${esc(arkasLabel(r))}"`,oninput:`setBudgetArkas('${a.id}',${j},this)`})}</div><div class="budget-line-bottom"><div class="budget-line-cell"><span class="sd-field-label">Bulan dianggarkan</span>${budgetMonthPicker(a.id,j,r.month)}</div>${sdTextField({label:'Jumlah',id:`${a.id}-bl${j}-quantity`,type:'number',value:r.quantity,attrs:'min="0" step="any"',oninput:`updateBudgetLine('${a.id}',${j},'quantity',this.value)`})}${sdTextField({label:'Satuan',id:`${a.id}-bl${j}-unit`,placeholder:'Rim, kotak, orang/hari',value:r.unit,oninput:`updateBudgetLine('${a.id}',${j},'unit',this.value)`})}${sdTextField({label:'Harga satuan (Rp)',id:`${a.id}-bl${j}-price`,type:'number',value:r.price,attrs:'min="0" step="any"',oninput:`updateBudgetLine('${a.id}',${j},'price',this.value)`})}<div class="budget-line-cell"><span class="sd-field-label">Total</span><span class="budget-line-total" id="line-total-${a.id}-${j}">${money(Number(r.quantity)*Number(r.price))}</span></div></div></div>`).join('')}</div><div class="budget-lines-footer">${sdBtn('Tambah uraian',{variant:'secondary',leadingIcon:'add',onclick:`addBudgetLine('${a.id}')`})}<p>Total anggaran kegiatan: <b id="activity-total-${a.id}">${money(a.budget)}</b></p></div></section>`}
function addBudgetLine(id){const a=data.activities.find(a=>a.id===id);(a.budgetLines??=[]).push({code:'',description:'',month:'',quantity:'',unit:'',price:''});save();render()}
function removeBudgetLine(id,index){const a=data.activities.find(a=>a.id===id);a.budgetLines.splice(index,1);recalculateActivityBudget(a);save();render()}
function updateBudgetLine(id,index,key,value){const a=data.activities.find(a=>a.id===id);a.budgetLines[index][key]=value;recalculateActivityBudget(a);save();const r=a.budgetLines[index];document.getElementById('line-total-'+id+'-'+index).textContent=money(Number(r.quantity)*Number(r.price));document.getElementById('activity-total-'+id).textContent=money(a.budget)}

function successForm(a){return `<div class="card activity-card guided-activity"><h3>${esc(a.name||'Kegiatan belum diberi nama')}</h3>${field(a,'target','Perubahan atau hasil yang ingin dicapai *','Contoh: Guru menerapkan hasil refleksi dalam perangkat ajar')}<div class="grid two">${field(a,'quantity','Jumlah yang ditargetkan *','Contoh: 6','number')}${field(a,'unit','Satuan *','Contoh: sesi pendampingan')}</div>${field(a,'proof','Bukti keberhasilan yang akan digunakan *','Contoh: Catatan refleksi dan perubahan perangkat ajar')}<p class="sub">Gunakan bukti dari pekerjaan sehari-hari yang memperlihatkan hasil kegiatan.</p></div>`}
function month(id,m,on){let a=data.activities.find(a=>a.id===id);a.months=on?[...a.months,m]:a.months.filter(x=>x!==m);save()}
let lastRemoved=null;
function removeActivity(id){const idx=data.activities.findIndex(x=>x.id===id),a=data.activities[idx];if(a){plannerOpen[a.indicator]=1;lastRemoved={a:JSON.parse(JSON.stringify(a)),idx}}data.activities=data.activities.filter(x=>x.id!==id);save();render();if(a)toastAction('Kegiatan dilepas.','Urungkan','undoRemoveActivity()')}
function undoRemoveActivity(){if(!lastRemoved)return;const {a,idx}=lastRemoved;lastRemoved=null;if(!data.activities.some(x=>x.id===a.id))data.activities.splice(Math.min(idx,data.activities.length),0,a);plannerOpen[a.indicator]=1;save();render();document.querySelector('.toast')?.remove()}
function back(){flowError='';if(stage===0)go('home');else{stage--;render();window.scrollTo(0,0)}}
function next(){if(stage===0){if(data.priorities.length<2)return blockStep('Pilih minimal 2 indikator prioritas.');if(data.priorities.some(id=>!plannerTargetValid(id))){blockStep('Lengkapi target capaian untuk setiap indikator pilihan.');focusMissingTarget();return}}if(stage===1){const miss=data.priorities.find(id=>!(data.roots[id]||[]).length);if(miss)return blockStep('Pilih minimal satu akar masalah untuk setiap prioritas.','#root-card-'+miss)}if(stage===2){if(data.priorities.some(id=>!plannerTargetValid(id))){stage=0;go('flow');toast('Lengkapi target capaian setiap prioritas sebelum menyelesaikan rencana.');return}{const miss=data.priorities.find(id=>!data.activities.some(a=>a.indicator===id));if(miss)return blockStep('Pilih minimal satu kegiatan untuk setiap prioritas.','#plan-'+miss)}{const bad=data.activities.find(a=>!activityBasicsValid(a));if(bad)return blockStep('Lengkapi penjelasan kegiatan yang dipilih. Rincian anggaran dapat dilengkapi nanti.','#'+bad.id+'-implementation')}go('review');return}if(stage===4){if(!data.evaluationOpen)return toast('Periode evaluasi belum dibuka.');if(data.activities.some(a=>!data.evaluation[a.id]?.result))return toast('Pilih hasil evaluasi untuk setiap kegiatan.');data.evaluationSubmitted=true;save();go('home');toast('Evaluasi tersimpan. Lanjutkan ke tindak lanjut dari beranda.');return}if(stage===5){if(data.activities.some(a=>!data.follow[a.id]?.action?.trim()))return toast('Lengkapi rencana tindak lanjut untuk setiap kegiatan.');data.status='Selesai';save();window.__docJustDone=true;showDocRecord('current',0,'ringkasan');toast('Siklus selesai. Pembelajaran tersimpan untuk RKT berikutnya.');return}if(['menetapkan-alternative','menetapkan-cards'].includes(page))page='flow';flowError='';stage++;render();window.scrollTo(0,0)}
