function reviewRktTable(){const rows=rktRows().map(r=>[String(r[0]),r[1]?`<span class="sd-cell-title">${esc(r[1])}</span>`:'',esc(r[2]),esc(r[3]),r[4]?esc(r[4]):reviewMissing,r[5]]);return rows.length?sdTable({caption:'Pratinjau RKT',className:'review-doc-table',columns:RKT_HEADER.map(label=>({label})),rows}):sdBanner({tone:'info',children:'<p>Belum ada kegiatan. Kembali ke perencanaan untuk memilih kegiatan.</p>'})}
function reviewRkasTable(){const {rows,total}=rkasRows();if(!rows.length)return sdBanner({tone:'info',title:'Tidak ada kegiatan yang membutuhkan anggaran',children:'<p>RKAS terisi otomatis dari kegiatan yang ditandai membutuhkan anggaran.</p>'});const dash=reviewMissing,num=v=>v===''||v===undefined?dash:new Intl.NumberFormat('id-ID').format(v);const body=rows.map(r=>[String(r[0]),r[1]?`<span class="sd-cell-title">${esc(r[1])}</span><span class="review-cell-note">${r[2]?esc(r[2]):''}</span>`:'',r[3]?esc(r[3]):dash,r[4]?esc(r[4]):dash,r[5]?esc(r[5]):dash,{html:num(r[6]),className:'sd-right'},r[7]?esc(r[7]):dash,{html:num(r[8]),className:'sd-right'},{html:r[9]===''?dash:money(r[9]),className:'sd-right'}]);body.push({cells:['','','','','','','',{html:'<b>Total anggaran</b>',className:'sd-right'},{html:`<b>${money(total)}</b>`,className:'sd-right'}],attrs:'class="review-total-row"'});return sdTable({caption:'Pratinjau RKAS',className:'review-doc-table',columns:[{label:'No'},{label:'Kegiatan benahi'},{label:'Kegiatan ARKAS'},{label:'Uraian kegiatan ARKAS'},{label:'Bulan dianggarkan'},{label:'Jumlah',align:'right'},{label:'Satuan'},{label:'Harga satuan',align:'right'},{label:'Total',align:'right'}],rows:body})}
