function reviewSummary(){const budgeted=data.activities.filter(a=>a.needsBudget===true),total=budgeted.reduce((s,a)=>s+Number(a.budget||0),0),item=(label,value,note,action)=>`<div class="review-summary-item"><dt>${label}</dt><dd>${value}</dd>${note?`<dd class="review-summary-note">${note}</dd>`:''}${action?`<dd class="review-summary-action">${action}</dd>`:''}</div>`,targets=data.priorities.map(id=>{const i=ind(id),t=data.targets[id];return `${esc(i.name)}${t!==undefined&&t!==''?`, target ${esc(t)}${i.unit?' '+esc(i.unit):''}`:''}`}).join('<br>'),rootCount=id=>(data.roots[id]||[]).length,rootTotal=data.priorities.reduce((s,id)=>s+rootCount(id),0),rootNote=data.priorities.map(id=>`${esc(ind(id).name)}: ${rootCount(id)} akar masalah`).join('<br>'),edit=(label,js)=>sdBtn(label,{variant:'quiet',size:'sm',leadingIcon:'edit',onclick:js}),first=data.activities[0],actNote=`${budgeted.length?budgeted.length+' membutuhkan anggaran':'Tidak ada yang membutuhkan anggaran'}<br>Total anggaran ${money(total)}`;return `<section class="review-summary" aria-labelledby="review-summary-title"><div class="review-summary-head"><h2 id="review-summary-title">Ringkasan rencana</h2></div><dl>${item('Profil sekolah','SMA Rakyat 3','NPSN 20260001<br>Rencana kerja tahunan '+esc(data.year))}${item('Step 1: indikator prioritas',data.priorities.length+' indikator',targets,edit('Ubah prioritas',"stage=0;go('flow')"))}${item('Step 2: akar masalah',rootTotal+' akar masalah',rootNote,edit('Ubah akar masalah',"stage=1;go('flow')"))}${item('Step 3: kegiatan',data.activities.length+' kegiatan',actNote,first?edit('Ubah kegiatan',`editFromReview('${first.indicator}','activity','${first.id}')`):'')}</dl></section>`}
function review(){return `<div class="flow-heading"><div><div class="eyebrow">Sebelum disimpan</div><h1>Tinjau rencana</h1></div><div class="document-status">${badge(data.status)}<span class="sd-status" role="status">${sdIcon('check')}Draf tersimpan otomatis</span></div></div><section class="flow-content">${reviewSummary()}${reviewDocCard('review-rkt-title','Rencana Kerja Tahunan (RKT)','Tabel kegiatan benahi untuk lampiran RKT.',sdBtn('Unduh Word',{variant:'secondary',leadingIcon:'download',onclick:"downloadRkt('docx')"})+sdBtn('Unduh Excel',{variant:'secondary',leadingIcon:'download',onclick:"downloadRkt('xlsx')"}),reviewRktTable())}${reviewDocCard('review-rkas-title','Rancangan ARKAS (RKAS)','Rincian anggaran yang bisa dibawa ke ARKAS.',sdBtn('Unduh Excel',{variant:'secondary',leadingIcon:'download',onclick:'downloadRkas()'}),reviewRkasTable())}<section class="review-submit-panel" aria-labelledby="review-submit-title"><div class="review-submit-text"><h2 id="review-submit-title">Ketentuan penyimpanan</h2><p>Dengan menyimpan, Anda menyetujui ketentuan berikut.</p><ol class="review-terms"><li><b>Rencana dikunci.</b> Prioritas, akar masalah, kegiatan, dan anggaran tidak bisa diubah setelah rencana disimpan.</li><li><b>Perubahan lewat admin.</b> Jika rencana perlu diubah, hubungi admin untuk membuka revisi.</li><li><b>Menjadi acuan siklus.</b> Rencana yang disimpan dipakai untuk mencatat capaian, evaluasi, dan tindak lanjut.</li><li><b>ARKAS diisi manual.</b> Rincian anggaran belum terkirim otomatis. Unduh RKAS, lalu salin rinciannya ke ARKAS.</li></ol></div>${sdCheckbox({id:'confirm',label:'Saya telah membaca dan menyetujui ketentuan di atas.'})}<div class="review-submit-actions">${sdBtn('Simpan rencana',{onclick:'submit()'})}</div></section></section>`}
const FULL_MONTHS={Jul:'Juli',Agu:'Agustus',Sep:'September',Okt:'Oktober',Nov:'November',Des:'Desember',Jan:'Januari',Feb:'Februari',Mar:'Maret',Apr:'April',Mei:'Mei',Jun:'Juni'};
function fullMonthLabel(arr){if(!arr.length)return '';const full=arr.map(m=>FULL_MONTHS[m]||m);if(full.length===1)return full[0];const ix=arr.map(m=>BUDGET_MONTHS.indexOf(m)).sort((a,b)=>a-b);const ordered=ix.map(k=>FULL_MONTHS[BUDGET_MONTHS[k]]);return ix.every((v,k)=>k===0||v===ix[k-1]+1)?ordered[0]+' – '+ordered[ordered.length-1]:full.join(', ')}
const exportMeta=()=>[['Nama satuan pendidikan','SMA Rakyat 3'],['NPSN','20260001'],['Rencana kerja tahunan',data.year]];
const exportFile=(base,ext)=>base+'-'+String(data.year).replace(/[^0-9a-z]+/gi,'-')+'.'+ext;
function rktRows(){const rows=[];let n=0;data.priorities.forEach(id=>{const i=ind(id);let firstIndicator=true;(data.roots[id]||[]).forEach(r=>{const acts=data.activities.filter(a=>a.indicator===id&&a.root===r);let firstRoot=true;(acts.length?acts:[null]).forEach(a=>{n+=1;rows.push([n,firstIndicator?i.name:'',firstRoot?chainName(r):'',a?activitySummaryTitle(a):'',a?(a.implementation||''):'',a?(a.needsBudget===true?'Ya':'Tidak'):'']);firstIndicator=false;firstRoot=false})})});return rows}
const RKT_HEADER=['No','Indikator prioritas','Akar masalah','Kegiatan benahi','Penjelasan implementasi kegiatan','Apakah kegiatan membutuhkan biaya?'];
function downloadRkt(kind){if(!window.spmpExport)return toast('Fitur unduh belum siap. Muat ulang halaman.');const rows=rktRows();if(!rows.length)return toast('Belum ada kegiatan untuk diunduh.');const title='Lembar Kerja Rencana Kerja Tahunan (RKT)';const bytes=kind==='docx'?spmpExport.docx({title,meta:exportMeta(),header:RKT_HEADER,rows,widths:[700,2800,3000,3338,3900,1100]}):spmpExport.xlsx({sheetName:'RKT',title,meta:exportMeta(),header:RKT_HEADER,rows,widths:[6,28,30,36,48,16]});spmpExport.download(exportFile('rkt',kind),bytes,kind);toast('RKT siap diunduh.')}
function rkasRows(){const rows=[];let n=0,total=0;data.activities.filter(a=>a.needsBudget===true).forEach(a=>{const lines=(a.budgetLines||[]).filter(r=>Object.values(r).some(v=>String(v??'').trim()));(lines.length?lines:[{}]).forEach((r,j)=>{n+=1;const sum=(Number(r.quantity)||0)*(Number(r.price)||0);total+=sum;const num=v=>v===undefined||v===''?'':Number(v);rows.push([n,j===0?activitySummaryTitle(a):'',j===0?(a.implementation||''):'',r.code||'',r.description||'',fullMonthLabel(budgetMonths(r.month)),num(r.quantity),r.unit||'',num(r.price),sum||''])})});return {rows,total}}
function downloadRkas(){if(!window.spmpExport)return toast('Fitur unduh belum siap. Muat ulang halaman.');const {rows,total}=rkasRows();if(!rows.length)return toast('Belum ada kegiatan yang membutuhkan anggaran.');const header=['No','Kegiatan benahi','Penjelasan implementasi kegiatan','Kegiatan ARKAS','Uraian kegiatan ARKAS','Bulan dianggarkan','Jumlah','Satuan','Harga satuan (Rp)','Total (Rp)'];const bytes=spmpExport.xlsx({sheetName:'RKAS',title:'Lembar Kerja Rancangan ARKAS (RKAS)',meta:exportMeta(),header,rows,widths:[6,34,40,26,34,20,10,14,18,18],numberCols:[6,8,9],footer:['','','','','','','','','Total anggaran',total]});spmpExport.download(exportFile('rkas','xlsx'),bytes,'xlsx');toast('RKAS siap diunduh.')}
function submit(){if(!$('#confirm')?.checked)return toast('Centang persetujuan ketentuan terlebih dahulu.');if(!data.activities.length||data.activities.some(a=>!activityBasicsValid(a)))return toast('Lengkapi rencana kegiatan terlebih dahulu.');data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));data.status='Sudah ada rencana';save();go('home');toast('Rencana prioritas selesai disusun dan tersimpan.')}
