const EVIDENCE_KEYS=[['link','','snp'],['link2','2','snp2'],['link3','3','snp3']];
const evidenceLinks=p=>EVIDENCE_KEYS.map(([k,,sk])=>({url:String((p||{})[k]||'').trim(),snp:(snpOf((p||{})[sk])||[])[1]||''})).filter(x=>/^https?:\/\//i.test(x.url));
const evidenceFieldId=(field,sfx,id)=>'evidence-'+(field==='snp'?'snp':'link')+sfx+'-'+id;
function evidenceIssues(a){const p=data.progress[a.id]||{},out=[];EVIDENCE_KEYS.forEach(([k,sfx,sk],n)=>{const v=String(p[k]||'').trim();if(!v){if(!n)out.push({field:'link',sfx,msg:'Tautan bukti pelaksanaan wajib diisi.'});return}if(!validExecutionEvidence(v))out.push({field:'link',sfx,msg:'Masukkan tautan yang valid dengan awalan https:// atau http://.'});else if(!snpOf(p[sk]))out.push({field:'snp',sfx,msg:'Pilih SNP yang dirujuk tautan ini.'})});return out}
function validExecutionEvidence(value){try{const url=new URL(String(value||'').trim());return ['http:','https:'].includes(url.protocol)&&Boolean(url.hostname)}catch{return false}}
function saveExecutionProgress(){const missing=data.activities.filter(a=>evidenceIssues(a).length);if(missing.length){missing.forEach(a=>evidenceIssues(a).forEach(({field,sfx,msg})=>{const input=document.getElementById(evidenceFieldId(field,sfx,a.id)),error=document.getElementById('evidence-'+(field==='snp'?'snp-':'')+'error'+sfx+'-'+a.id);if(input){input.setAttribute('aria-invalid','true');input.setCustomValidity(msg)}if(error)error.textContent=msg}));const f0=evidenceIssues(missing[0])[0],first=document.getElementById(evidenceFieldId(f0.field,f0.sfx,missing[0].id));first?.focus();first?.reportValidity();toast('Lengkapi tautan bukti dan SNP yang dirujuk untuk setiap kegiatan.');return false}save();go('home');toast('Capaian berhasil disimpan.');return true}
function progressUpdate(id,k,v){const a=data.activities.find(a=>a.id===id);if(k==='achieved'&&v!==''){v=Math.max(0,Number(v)||0)}data.progress[id]={...data.progress[id],[k]:v};if(a){data.progress[id].percent=activityPercent(a);const value=document.getElementById('progress-percent-'+id);if(value)value.textContent=formatProgress(data.progress[id].percent)+'%';const bar=document.getElementById('progress-bar-'+id);if(bar){bar.style.width=data.progress[id].percent+'%';bar.parentElement.setAttribute('aria-valuenow',data.progress[id].percent)}}save()}
function activityPercent(a){const target=Number(a.quantity),actual=Number(data.progress[a.id]?.achieved);if(!Number.isFinite(target)||target<=0||!Number.isFinite(actual))return 0;return Math.min(100,Math.max(0,Math.round(actual/target*1000)/10))}
function formatProgress(value){return new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(value)}
