function workCard(num,title,tables,eyebrow='',id=''){return `<section class="plan-card menetapkan-table-scroll"${id?` id="${id}" tabindex="-1"`:''}><div class="plan-card-head"><div class="plan-card-title">${num?`<span class="plan-card-num" aria-hidden="true">${num}</span>`:''}<div class="work-card-text">${eyebrow?`<p class="work-card-eyebrow">${eyebrow}</p>`:''}<h3>${title}</h3></div></div></div>${tables}</section>`}
function workRows(cells){return [cells]}
function planNote(a){return `<p class="work-root">${esc(a.root||'Akar masalah belum ditentukan')}</p><p class="work-text">${esc(a.implementation||a.realistic||'Belum diisi')}</p>${a.recommendationKey?`<details class="saved-recommendation"><summary>Tampilkan teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}<p class="saved-budget-status">${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}`}
function actSection(a,body){return `<section class="work-act"><div class="work-act-head"><span class="plan-card-num" aria-hidden="true">${actNo(a)}</span><h4>${esc(activitySummaryTitle(a))}</h4></div>${body}</section>`}
function workByRoot(id,k,items,secFn){const rs=data.roots[id]||[],order=[...rs,...items.map(a=>a.root).filter(r=>!rs.includes(r))];return [...new Set(order)].map(r=>{const part=items.filter(a=>a.root===r);if(!part.length)return '';const j=rs.indexOf(r);return `<div class="work-root-head">${j>=0?`<span class="plan-card-num" aria-hidden="true">${k+1}.${j+1}</span>`:''}<h4>${esc(chainName(r))}</h4></div>`+part.map(secFn).join('')}).join('')}
function groupByIndicator(secFn,sortFn,emptyFn,withOutcome){return data.priorities.map((id,k)=>{let items=data.activities.filter(a=>a.indicator===id);if(sortFn)items=[...items].sort(sortFn);const i=ind(id);if(!items.length)return emptyFn?emptyFn(id,k):'';return workCard(String(k+1),esc(i.name),(withOutcome?indicatorOutcomeBlock(id):'')+workByRoot(id,k,items,secFn),'','work-ind-'+id)}).join('')}
function execution(){const cards=groupByIndicator(a=>{const p=data.progress[a.id]||{};const recap=`<dl class="work-recap"><div><dt>Yang akan dilakukan</dt><dd>${esc(a.implementation||a.realistic||'Belum diisi')}</dd></div><div><dt>Total anggaran</dt><dd>${a.needsBudget?money(a.budget):'Tidak membutuhkan anggaran'}</dd></div></dl>`;const link=`<fieldset class="evidence-links"><legend class="sd-field-label">Tautan bukti pelaksanaan</legend><p class="evidence-links-help">Tambahkan tautan yang dapat diakses, seperti dokumentasi kegiatan atau hasil kerja. Isi tautan pertama, dan tambahkan sampai 3 tautan bila perlu. Pilih SNP yang dirujuk oleh tiap tautan.</p>${EVIDENCE_KEYS.map(([k,sfx,sk],n)=>`<div class="evidence-link-group">`+sdTextField({label:'Tautan '+(n+1)+(n?'':' *'),optional:n>0,id:evidenceFieldId('link',sfx,a.id),type:'url',value:p[k]||'',placeholder:'https://…',attrs:n?'':`required aria-required="true"`,oninput:`progressUpdate('${a.id}','${k}',this.value);this.setCustomValidity('');this.removeAttribute('aria-invalid');document.getElementById('evidence-error${sfx}-${a.id}').textContent=''`})+`<p id="evidence-error${sfx}-${a.id}" class="evidence-link-error" role="alert"></p>`+sdSelect({label:'SNP yang dirujuk'+(n?'':' *'),id:evidenceFieldId('snp',sfx,a.id),options:[{value:'',label:'Pilih SNP'},...SNP_OPTIONS.map(o=>({value:o[0],label:o[1]}))],value:p[sk]||'',onchange:`progressUpdate('${a.id}','${sk}',this.value);this.setCustomValidity('');this.removeAttribute('aria-invalid');document.getElementById('evidence-snp-error${sfx}-${a.id}').textContent=''`})+`<p id="evidence-snp-error${sfx}-${a.id}" class="evidence-link-error" role="alert"></p></div>`).join('')}</fieldset>`;const notes=sdTextArea({label:'Catatan kemajuan dan kendala',optional:true,id:'progress-notes-'+a.id,placeholder:'Apa yang sudah berjalan? Dukungan apa yang masih diperlukan?',value:p.notes||'',rows:3,oninput:`progressUpdate('${a.id}','notes',this.value)`});return actionSection(a,`<div class="work-form work-form-2col">${recap}<div class="work-form-fields">${link}${notes}</div></div>`,'exec')});return workShell('Catat Pelaksanaan Kegiatan','Tambahkan tautan bukti pelaksanaan untuk setiap kegiatan. Catatan kemajuan dan kendala boleh diisi bila perlu.',cards)}
async function attach(id,files){let selected=Array.from(files);if(selected.some(f=>f.size>2*1024*1024))return toast('Ukuran setiap berkas maksimal 2 MB.');let encoded=await Promise.all(selected.map(f=>new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve({name:f.name,url:r.result});r.readAsDataURL(f)})));let old=data.progress[id];data.progress[id]={...old,files:encoded};try{save();toast('Bukti tersimpan di peramban ini.')}catch{data.progress[id]=old;toast('Penyimpanan peramban penuh. Gunakan tautan bukti.')}render()}
function activityPlanContext(a){return `<span class="tag">${esc(ind(a.indicator).name)}</span><h2 style="margin-top:12px">${numTag(a)}${esc(activitySummaryTitle(a))}</h2><p class="sub">Menjawab: ${esc(a.root)}</p><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(a.implementation||a.realistic||'Belum diisi')}</p></div>${a.recommendationKey?`<details class="saved-recommendation"><summary>Tampilkan teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}<p class="saved-budget-status">${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}`}
function executionReference(a){const p=data.progress[a.id]||{};const links=evidenceLinks(p),link=links.length;return `<section class="execution-reference"><h3>Catatan dan bukti pelaksanaan</h3><p class="sub">Informasi dari tahap Melaksanakan.</p><p class="execution-reference-notes">${esc(p.notes||'Belum ada catatan pelaksanaan.')}</p>${links.map((u,n)=>`<p><a href="${esc(u.url)}" target="_blank" rel="noopener noreferrer">Buka tautan bukti pelaksanaan${links.length>1?' '+(n+1):''} ↗</a>${u.snp?` <span class="sub">· ${esc(u.snp)}</span>`:''}</p>`).join('')}${(p.files||[]).map(f=>`<p><a href="${esc(f.url)}" download="${esc(f.name)}">Unduh bukti: ${esc(f.name)}</a></p>`).join('')}${!link&&!p.files?.length?'<p class="sub">Belum ada bukti pelaksanaan yang dilampirkan.</p>':''}</section>`}
function sourcedIndicatorOutcome(id){const i=ind(id);const year=data.year.split('/')[1];const result=i.annualResults?.[data.year]??i.annualResults?.[year];if(result!==undefined)return result;return String(i.period)===year||String(i.period)===data.year?i.score:undefined}
function dummyIndicatorOutcome(id){const i=ind(id);if(typeof i.score!=='number'||!Number.isFinite(i.score))return undefined;const hash=[...id+data.year].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,0);const increase=i.max*(0.08+(hash%1800)/10000);return Math.round(Math.min(i.max,Math.max(0,i.score+increase))*100)/100}
function currentIndicatorOutcome(id){return sourcedIndicatorOutcome(id)??dummyIndicatorOutcome(id)}
function isDummyIndicatorOutcome(id){return sourcedIndicatorOutcome(id)===undefined&&dummyIndicatorOutcome(id)!==undefined}
function indicatorOutcomeValid(id){const v=currentIndicatorOutcome(id);return v!==undefined&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=ind(id).max}
function indicatorOutcomeParts(id){const dash='<span class="table-no-comparison" aria-hidden="true">–</span><span class="sr-only">Belum tersedia</span>';if(!indicatorOutcomeValid(id))return {badge:dash,note:'Data belum tersedia – siklus masih berjalan'};if(!plannerTargetValid(id))return {badge:dash,note:'Target belum ditetapkan'};const diff=Math.round((Number(currentIndicatorOutcome(id))-Number(data.targets[id]))*100)/100;return {badge:sdBadge(diff>=0?'Target tercapai':'Belum mencapai target',badgeTone(diff>=0?'green':'amber')),note:scoreText({score:Math.abs(diff)})+' '+(ind(id).unit==='%'?'poin persentase':'poin')+' '+(diff>=0?'di atas / sesuai target':'di bawah target')}}
function indicatorOutcomeStatus(id){if(!indicatorOutcomeValid(id))return '<span class="muted">Hasil tahun berjalan belum tersedia</span>';if(!plannerTargetValid(id))return '<span class="muted">Target belum ditetapkan</span>';const diff=Math.round((Number(currentIndicatorOutcome(id))-Number(data.targets[id]))*100)/100;return `${sdBadge(diff>=0?'Target tercapai':'Belum mencapai target',badgeTone(diff>=0?'green':'amber'))}`+'<span>'+scoreText({score:Math.abs(diff)})+' '+(ind(id).unit==='%'?'poin persentase':'poin')+' '+(diff>=0?'di atas / sesuai target':'di bawah target')+'</span>'}
function evalProof(a){const p=data.progress[a.id]||{},links=evidenceLinks(p);const parts=[];links.forEach((u,n)=>parts.push(`<a href="${esc(u.url)}" target="_blank" rel="noopener noreferrer">Buka tautan bukti${links.length>1?' '+(n+1):''} ↗</a>${u.snp?` <span class="sub">· ${esc(u.snp)}</span>`:''}`));(p.files||[]).forEach(f=>parts.push(`<a href="${esc(f.url)}" download="${esc(f.name)}">Unduh ${esc(f.name)}</a>`));return parts.length?parts.join('<br>'):'Data belum tersedia – siklus masih berjalan'}
function outcomeLine(id){const i=ind(id);return `Awal <b>${scoreText(i)} ${esc(i.unit)}</b> · Target <b>${plannerTargetValid(id)?scoreText({score:Number(data.targets[id])})+' '+esc(i.unit):'belum ditetapkan'}</b> · Hasil <b>${indicatorOutcomeValid(id)?scoreText({score:Number(currentIndicatorOutcome(id))})+' '+esc(i.unit):'belum tersedia'}</b>${isDummyIndicatorOutcome(id)?' <em>(data dummy)</em>':''}<span class="work-outcome-status">${indicatorOutcomeStatus(id)}</span>`}
function activityRecap(a,extra=''){const p=data.progress[a.id]||{};return `<dl class="work-recap"><div><dt>Yang akan dilakukan</dt><dd>${esc(a.implementation||a.realistic||'Belum diisi')}</dd></div><div><dt>Total anggaran</dt><dd>${a.needsBudget?money(a.budget):'Tidak membutuhkan anggaran'}</dd></div><div><dt>Bukti pelaksanaan</dt><dd>${evalProof(a)}</dd></div>${p.notes?`<div><dt>Catatan kemajuan dan kendala</dt><dd>${esc(p.notes)}</dd></div>`:''}${extra}</dl>`}
function indicatorOutcomeBlock(id){const i=ind(id),pt=indicatorOutcomeParts(id);return `<div class="work-indicator-summary"><dl><div><dt>Capaian awal ${esc(i.period||'')}</dt><dd>${scoreText(i)} ${esc(i.unit)}</dd></div><div><dt>Target ${esc(data.year)}</dt><dd>${plannerTargetValid(id)?scoreText({score:Number(data.targets[id])})+' '+esc(i.unit):'Belum ditetapkan'}</dd></div><div><dt>Hasil ${esc(data.year)}</dt><dd>${indicatorOutcomeValid(id)?scoreText({score:Number(currentIndicatorOutcome(id))})+' '+esc(i.unit):'Belum tersedia'}${isDummyIndicatorOutcome(id)?' <em class="work-dummy">(data dummy)</em>':''}</dd></div><div class="work-summary-status"><dt>Status</dt><dd>${pt.badge}<span class="work-summary-note">${esc(pt.note)}</span></dd></div></dl></div>`}
function indicatorSummaryCard(){const rows=data.priorities.map((id,k)=>{const i=ind(id);return [`<span class="preview-num">${k+1}</span> <strong>${esc(i.name)}</strong>`,`${scoreText(i)} ${esc(i.unit)}`,plannerTargetValid(id)?scoreText({score:Number(data.targets[id])})+' '+esc(i.unit):'Belum ditetapkan',`${indicatorOutcomeValid(id)?scoreText({score:Number(currentIndicatorOutcome(id))})+' '+esc(i.unit):'Belum tersedia'}${isDummyIndicatorOutcome(id)?' <em class="work-dummy">(data dummy)</em>':''}`,indicatorOutcomeParts(id).badge,sdBtn('Cek Detail Kegiatan',{variant:'secondary',size:'sm',trailingIcon:'arrow-down',onclick:`chainScroll(document.getElementById('work-ind-${id}'))`})]});return `<section class="plan-card menetapkan-table-scroll"><div class="plan-card-head"><div class="plan-card-title"><h3>Hasil Indikator</h3></div></div>${sdTable({caption:'Hasil indikator prioritas',className:'sd-no-hover work-summary-table',columns:[{label:'Indikator'},{label:'Capaian awal'},{label:'Target '+data.year},{label:'Hasil '+data.year},{label:'Status'},{label:'Aksi'}],rows})}</section>`}
const actOpen={};
const ACT_KINDS={exec:{label:'Belum dicatat',done:'Pelaksanaan tercatat',filled:a=>!!(data.progress[a.id]||{}).link},eval:{label:'Belum dievaluasi',done:'Sudah dievaluasi',filled:a=>!!(data.evaluation[a.id]||{}).result},ctl:{label:'Belum ditentukan',done:'Tindak lanjut ditentukan',filled:a=>!!(data.follow[a.id]||{}).action}};
function actKey(e,key){if(e.type==='keydown'&&e.key!==' '&&e.key!=='Enter')return;if(e.target.closest('a,button,input,select,textarea')&&e.target!==e.currentTarget)return;e.preventDefault();toggleActForm(e.currentTarget,key)}
function openNest(key){actOpen[key]=true;setTimeout(syncRailOpen,0);const b=document.getElementById('act-body-'+key);if(b)b.hidden=false;document.querySelector('[aria-controls="act-body-'+key+'"]')?.setAttribute('aria-expanded','true')}
function nestOpen(key){return actOpen[key]===true}
function nestHead(key,open,cls,inner){return `<div class="${cls} work-act-toggle" role="button" tabindex="0" aria-expanded="${open}" aria-controls="act-body-${key}" onclick="toggleActForm(this,'${key}')" onkeydown="actKey(event,'${key}')">${inner}<span class="work-act-chev" aria-hidden="true">${sdIcon('expand-more')}</span></div>`}
function nestCount(n,one,none){return sdBadge(n?n+' '+one:none,n?'green':'gray')}
let actBusy=0;
function setActBody(body,open,ms){const reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;body.getAnimations().forEach(x=>x.cancel());if(reduce||typeof body.animate!=='function'){body.hidden=!open;return}const done=()=>{body.style.overflow='';if(--actBusy<=0){actBusy=0;document.body.classList.remove('act-animating')}};if(open){body.hidden=false;const h=body.scrollHeight;body.style.overflow='hidden';actBusy++;document.body.classList.add('act-animating');const an=body.animate([{height:'0px'},{height:h+'px'}],{duration:ms,easing:'ease'});an.onfinish=an.oncancel=done}else if(!body.hidden){const h=body.offsetHeight;body.style.overflow='hidden';actBusy++;document.body.classList.add('act-animating');const an=body.animate([{height:h+'px'},{height:'0px'}],{duration:ms,easing:'ease'});an.onfinish=()=>{if(actOpen[body.id.replace('act-body-','')]!==true)body.hidden=true;done()};an.oncancel=done}}
function pinDuring(el,ms){const y=el.getBoundingClientRect().top,t0=performance.now(),step=now=>{const d=el.getBoundingClientRect().top-y;if(Math.abs(d)>.5)window.scrollTo({top:Math.max(0,window.scrollY+d),left:0,behavior:'instant'});if(now<t0+ms+40)requestAnimationFrame(step)};requestAnimationFrame(step)}
function toggleActForm(btn,key,instant){const body=document.getElementById('act-body-'+key),willOpen=actOpen[key]!==true,ms=instant?0:200;railActCur=null;if(willOpen)document.querySelectorAll('.work-act-toggle[aria-expanded="true"]').forEach(o=>{if(o===btn)return;const ob=document.getElementById(o.getAttribute('aria-controls'));if(ob)setActBody(ob,false,ms);o.setAttribute('aria-expanded','false');actOpen[o.getAttribute('aria-controls').replace('act-body-','')]=false});{const de=document.documentElement;de.style.minHeight=de.scrollHeight+'px';clearTimeout(window.actLockT);window.actLockT=setTimeout(()=>{de.style.minHeight=''},ms+80)}if(!instant)pinDuring(btn,ms);actOpen[key]=willOpen;setActBody(body,willOpen,ms);btn.setAttribute('aria-expanded',String(willOpen));syncRailOpen()}
function actionSection(a,body,kind){const k=ACT_KINDS[kind],key=kind+'-'+a.id,open=actOpen[key]===true,done=k.filled(a);return `<section class="work-act" id="act-${key}" tabindex="-1"><div class="work-act-head work-act-toggle${done?' is-done':''}" role="button" tabindex="0" data-act-kind="${kind}" data-act-id="${a.id}" aria-expanded="${open}" aria-controls="act-body-${key}" onclick="toggleActForm(this,'${key}')" onkeydown="actKey(event,'${key}')"><span class="plan-card-num" aria-hidden="true">${actNo(a)}</span><h4>${esc(activitySummaryTitle(a))}</h4><span class="work-act-status">${sdBadge(done?k.done:k.label,done?'green':'gray')}</span><span class="work-act-chev" aria-hidden="true">${sdIcon('expand-more')}</span></div><div id="act-body-${key}"${open?'':' hidden'}>${body}</div></section>`}
function syncActButtons(){document.querySelectorAll('.work-act-toggle[data-act-kind]').forEach(b=>{const k=ACT_KINDS[b.dataset.actKind],a=data.activities.find(x=>x.id===b.dataset.actId);if(!a)return;const done=k.filled(a);b.classList.toggle('is-done',done);const st=b.querySelector('.work-act-status');if(st)st.innerHTML=sdBadge(done?k.done:k.label,done?'green':'gray')})}
function evaluation(){const outcomeOf=outcomeLine;const cards=groupByIndicator(a=>{const e=data.evaluation[a.id]||{},p=data.progress[a.id]||{};const recap=activityRecap(a);const select=sdSelect({label:'Bagaimana efektivitas kegiatan ini?',id:'evaluation-result-'+a.id,value:e.result||'',onchange:`evalUpd('${a.id}','result',this.value)`,options:[{value:'',label:'Pilih hasil evaluasi'},...['Efektif','Perlu penyesuaian','Tidak efektif'].map(r=>({value:r,label:r}))]});const sw=e.swot||{},notes=`<fieldset class="swot-fields"><legend class="sd-field-label">Alasan penilaian</legend><p class="swot-help">Gunakan kerangka SWOT sebagai panduan. Isi seperlunya, tidak harus semua kotak.</p>${!e.swot&&e.notes?`<p class="swot-legacy"><b>Catatan sebelumnya:</b> ${esc(e.notes)}</p>`:''}<div class="swot-grid">${SWOT_FIELDS.map(([k,term,hint,ph])=>sdTextArea({label:term+' · '+hint,id:'evaluation-'+k+'-'+a.id,placeholder:ph,value:sw[k]||'',rows:3,oninput:`evalSwot('${a.id}','${k}',this.value)`})).join('')}</div></fieldset>`;return actionSection(a,`<div class="work-form work-form-2col">${recap}<div class="work-form-fields">${select}${notes}</div></div>`,'eval')},null,(id,k)=>workCard(String(k+1),esc(ind(id).name),indicatorOutcomeBlock(id)+`<div class="work-form"><p class="work-text">Belum ada kegiatan untuk indikator ini.</p></div>`,'','work-ind-'+id),true);return workShell('Evaluasi Hasil dan Kegiatan','Nilai efektivitas setiap kegiatan, lalu jelaskan alasannya dengan panduan SWOT. Setelah selesai, simpan evaluasi dan lanjut ke Mengendalikan.',cards)}
function evaluationActivities(id){const acts=data.activities.filter(a=>a.indicator===id);return acts.map((a,index)=>`<section class="evaluation-activity"><p class="evaluation-eyebrow">Kegiatan pendukung · ${index+1} dari ${acts.length}</p><h3 class="evaluation-activity-title">${numTag(a)}${esc(activitySummaryTitle(a))}</h3><p class="sub evaluation-root">Menangani ${esc(a.root||'akar masalah belum ditentukan')}</p><details class="evaluation-context"><summary>Tampilkan implementasi, pelaksanaan, dan anggaran</summary><div class="evaluation-context-body"><span class="evaluation-context-label">Implementasi yang direncanakan</span><p>${esc(a.implementation||a.realistic||'Belum diisi')}</p>${a.recommendationKey?`<details class="saved-recommendation"><summary>Tampilkan teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}${executionReference(a)}<span class="evaluation-context-label">Anggaran</span><p>${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}</div></details><div class="evaluation-assessment"><label for="evaluation-result-${a.id}">Bagaimana efektivitas kegiatan ini?</label><select id="evaluation-result-${a.id}" required onchange="evalUpd('${a.id}','result',this.value)"><option value="">Pilih hasil evaluasi</option>${['Efektif','Perlu penyesuaian','Tidak efektif'].map(r=>`<option ${data.evaluation[a.id]?.result===r?'selected':''}>${r}</option>`).join('')}</select><label for="evaluation-notes-${a.id}">Alasan penilaian dan pembelajaran</label><textarea id="evaluation-notes-${a.id}" oninput="evalUpd('${a.id}','notes',this.value)" placeholder="Jelaskan perubahan yang terlihat dan bukti pendukungnya.">${esc(data.evaluation[a.id]?.notes||'')}</textarea></div></section>`).join('')}

const SWOT_FIELDS=[['s','Strength','Apa yang sudah baik','Contoh: guru antusias dan murid mulai rutin membaca.'],['w','Weakness','Apa yang belum baik','Contoh: jadwal kegiatan sering bentrok dengan jam pelajaran.'],['o','Opportunity','Apa yang mendukung','Contoh: dukungan komite dan komunitas belajar guru.'],['t','Threat','Apa yang menghambat','Contoh: keterbatasan buku bacaan dan waktu.']];
const swotText=sw=>SWOT_FIELDS.map(([k,term])=>String((sw||{})[k]||'').trim()?term+': '+String(sw[k]).trim():'').filter(Boolean).join('\n');
function evalSwot(id,k,v){const e=data.evaluation[id]||{},sw={...(e.swot||{}),[k]:v};data.evaluation[id]={...e,swot:sw,notes:swotText(sw)};save()}
function evalUpd(id,k,v){data.evaluation[id]={...data.evaluation[id],[k]:v};save()}
function control(){const tone=r=>r==='Efektif'?'green':r==='Perlu penyesuaian'?'amber':r==='Tidak efektif'?'red':'gray';const cards=groupByIndicator(a=>{const e=data.evaluation[a.id]||{},f=data.follow[a.id]||{},type=f.type||(e.result==='Efektif'?'Pemeliharaan':'Korektif');const recap=activityRecap(a,`<div><dt>Hasil evaluasi</dt><dd>${sdBadge(e.result||'Belum dievaluasi',tone(e.result))}</dd></div><div><dt>Alasan penilaian dan pembelajaran</dt><dd>${esc(e.notes||'Belum ada catatan evaluasi.')}</dd></div>`);const typeSel=sdSelect({label:'Jenis tindak lanjut',id:'follow-type-'+a.id,value:type,onchange:`followUpd('${a.id}','type',this.value)`,options:['Korektif','Preventif','Pemeliharaan','Peningkatan'].map(t=>({value:t,label:t}))});const action=sdTextArea({label:'Apa yang akan diperbaiki atau dipertahankan? *',id:'follow-action-'+a.id,placeholder:'Tuliskan tindak lanjut konkret berdasarkan hasil evaluasi kegiatan ini.',value:f.action||'',rows:3,oninput:`followUpd('${a.id}','action',this.value)`});const carry=sdCheckbox({label:'Bawa kegiatan ke RKT berikutnya sebagai draf yang dapat disesuaikan.',checked:!!f.carry,onchange:`followUpd('${a.id}','carry',this.checked)`});return actionSection(a,`<div class="work-form work-form-2col">${recap}<div class="work-form-fields">${typeSel}${action}${carry}</div></div>`,'ctl')},(a,b)=>(data.evaluation[a.id]?.result==='Efektif')-(data.evaluation[b.id]?.result==='Efektif'),null,true);return workShell('Tentukan Tindak Lanjut','Tentukan tindak lanjut berdasarkan evaluasi. Kegiatan yang perlu penyesuaian atau tidak efektif ditampilkan lebih dahulu.',cards)}

function followUpd(id,k,v){data.follow[id]={...data.follow[id],[k]:v};save()}
let reportIndicator='lit';
const reportIds=['lit','num','A.3','D.4','D.8','ajar'];
const reportDescriptions={lit:'Kemampuan peserta didik dalam memahami, menggunakan, merefleksi, dan mengevaluasi beragam jenis teks.',num:'Kemampuan peserta didik menggunakan konsep, prosedur, fakta, dan alat matematika untuk menyelesaikan masalah.', 'A.3':'Perkembangan karakter peserta didik dalam sikap, nilai, dan kebiasaan sehari-hari.','D.4':'Kondisi sekolah yang mendukung rasa aman dan melindungi warga sekolah dari kekerasan.','D.8':'Lingkungan belajar yang menghargai perbedaan agama, budaya, dan latar belakang peserta didik.',ajar:'Kualitas praktik pembelajaran yang mendukung keterlibatan dan kebutuhan belajar murid.'};
function reportDelta(i){if(typeof i.previous!=='number'||typeof i.score!=='number')return '<span class="muted">Data pembanding belum tersedia</span>';const d=i.score-i.previous;return `<span class="${d>0?'report-up':d<0?'report-down':'muted'}">${d>0?'↑':d<0?'↓':'−'}</span> Capaian ${d>0?'naik':d<0?'turun':'tidak berubah'}${d!==0?' <b>'+scoreText({score:Math.abs(d)})+' poin</b>':''} dari tahun 2024`}
function reportStatus(i){return `<span class="report-status ${i.color}">${esc(i.level)}${['lit','num'].includes(i.id)?' ('+scoreText(i)+'% murid mencapai kompetensi minimum)':''}</span>`}
function reportComparison(i){return `<div class="report-comparison"><div><span>Capaian tahun 2024</span><b>${typeof i.previous==='number'?scoreText({score:i.previous})+(i.unit?' '+esc(i.unit):''):'Belum tersedia'}</b></div><div><span>Capaian tahun 2025</span><b>${scoreText(i)}${i.unit?' '+esc(i.unit):''}</b></div></div>`}
function reportCard(i,related=false){return `<article class="report-indicator-card"><div class="report-card-content"><h3>${esc(i.name)}</h3>${reportStatus(i)}<p class="report-delta">${reportDelta(i)}</p><button class="report-meaning" onclick="reportMeaning('${i.id}')">ⓘ Apa arti capaian saya?</button><p class="report-compare-label">Perkembangan capaian sekolah</p>${reportComparison(i)}${related?`<p class="report-child-label">Beberapa indikator yang perlu ditingkatkan</p><div class="report-child-list">${i.children.length?i.children.slice(0,2).map((c,j)=>`<div><span>${esc(c.name)}<b>${scoreText(c)}${c.unit?' '+esc(c.unit):''}</b></span><button onclick="reportChildMeaning('${i.id}',${j})">Detail</button></div>`).join(''):'<p class="sub">Belum ada subindikator dalam referensi.</p>'}</div>${i.children.length>2?`<details class="report-more-children"><summary>Tampilkan ${i.children.length-2} indikator lainnya</summary>${i.children.slice(2).map(c=>`<p>${esc(c.name)} <b>${scoreText(c)} ${esc(c.unit)}</b></p>`).join('')}</details>`:''}`:''}</div>${related?'':`<div class="report-card-footer">${selectable?`<button class="${data.priorities.includes(i.id)?'priority-selected':''}" aria-pressed="${data.priorities.includes(i.id)}" onclick="choose('${i.id}',${!data.priorities.includes(i.id)})">${data.priorities.includes(i.id)?'✓ Dipilih · Batalkan':'Jadikan prioritas'}</button>${data.priorities.includes(i.id)?`<p class="priority-card-target">Target: <b>${esc(data.targets[i.id]??'—')} ${esc(i.unit)}</b> <button class="quiet" onclick="requestPriorityTarget('${i.id}')">Ubah target</button></p>`:''}`:`<button onclick="openReportRoot('${i.id}')">Pelajari Akar Masalah</button>`}</div>`}</article>`}
function reportDialog(){return `<dialog id="report-dialog" class="report-dialog" tabindex="-1"><div id="report-dialog-content"></div><button class="primary" onclick="document.getElementById('report-dialog').close()">Mengerti</button></dialog>`}
let reportGroupFilter='Semua',reportSort='code',diagnosisSource='Rapor Pendidikan';
function setReportSort(value){reportSort=value;render();document.getElementById('report-indicators')?.scrollIntoView({behavior:'smooth',block:'start'})}
function setReportGroupFilter(value){reportGroupFilter=value;if(page==='rapor'){updateDiagnosisFilters();return}render()}
function reportDimensionGroups(){const topIds=new Set(['lit','num','A.3','D.4','D.8','ajar']);const groups=['Semua','Rekomendasi Indikator',...dimensionNames];const visible=indicators.filter(i=>reportGroupFilter==='Semua'||(reportGroupFilter==='Rekomendasi Indikator'?topIds.has(i.id):dimensionOf(i)===reportGroupFilter));visible.sort((a,b)=>{if(reportSort==='name')return a.name.localeCompare(b.name,'id');if(reportSort==='asc'||reportSort==='desc'){const aValid=typeof a.score==='number',bValid=typeof b.score==='number';if(aValid!==bValid)return aValid?-1:1;if(aValid&&a.score!==b.score)return reportSort==='asc'?a.score-b.score:b.score-a.score;}return a.code.localeCompare(b.code,'id',{numeric:true})});return `<div class="report-group-filters" role="group" aria-label="Filter kelompok indikator">${groups.map(name=>`<button type="button" aria-pressed="${reportGroupFilter===name}" onclick="setReportGroupFilter('${name}')">${esc(name)}</button>`).join('')}</div><div class="report-list-toolbar"><p class="sub report-result-count" role="status">${visible.length} indikator ditampilkan</p><div class="report-sort"><label for="report-sort">Urutkan</label><select id="report-sort" onchange="setReportSort(this.value)">${[['code','Urutan kode'],['name','Nama A–Z'],['asc','Skor terendah'],['desc','Skor tertinggi']].map(([value,label])=>`<option value="${value}" ${reportSort===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="report-dimension-list"><div class="indicator-list">${visible.map(i=>indicatorCard(i,topIds,true)).join('')}</div></div>`}

let diagnosisLayout='grid';
function setDiagnosisLayout(value){if(!['grid','priority','groups'].includes(value))return;diagnosisLayout=value;render()}
function diagnosisReferenceCard(i,selectable=false,plain=false){const hasScore=typeof i.score==='number',rank=(value)=>value?esc(value):'Data peringkat belum tersedia';const status=['lit','num'].includes(i.id)?`${i.level} (${scoreText(i)}% peserta didik sudah mencapai kompetensi minimum)`:`${i.level||'Capaian'}${hasScore?' · '+scoreText(i)+(i.unit?' '+i.unit:''):''}`;return `<article class="diagnosis-reference-card ${selectable&&data.priorities.includes(i.id)?'priority-card-selected':''}"><div class="diagnosis-reference-body">${plain?'':`<div class="diagnosis-card-meta"><span>${esc(i.code)}</span>${['lit','num','A.3','D.4','D.8','ajar'].includes(i.id)?'<span class="diagnosis-priority">Indikator Prioritas</span>':''}</div>`}${selectable?`<div class="priority-indicator-heading"><h3>${esc(i.name)}</h3>${['Rapor','TKA','Akreditasi'].includes(indicatorSourceLabel(i))?`<p class="priority-source-caption">${esc(i.source==='Rapor Pendidikan'?'Rapor Pendidikan':indicatorSourceLabel(i))}</p>`:''}</div>`:`<h3>${esc(i.name)}</h3>`}<div class="diagnosis-achievement ${hasScore?esc(i.color):'unavailable'}">${esc(hasScore?status:(i.unavailableReason||'Data capaian belum tersedia'))}</div><p class="report-delta">${reportDelta(i)}</p>${selectable||i.source==='Rapor Pendidikan'?`<button class="diagnosis-meaning" onclick="reportMeaning('${i.id}')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4C6.5 4 2.2 8.4 1 12c1.2 3.6 5.5 8 11 8s9.8-4.4 11-8c-1.2-3.6-5.5-8-11-8Zm0 13a5 5 0 1 1 0-10 5 5 0 0 1 0 10Zm0-2a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/></svg> Apa arti capaian saya?</button>`:''}<p class="diagnosis-rank-heading">Dibandingkan satuan pendidikan lain</p><div class="diagnosis-rank"><p><strong>${rank(i.rankProvince)}</strong><span>di provinsi</span></p><p><strong>${rank(i.rankNational)}</strong><span>secara nasional</span></p></div>${plain?'':`<p class="diagnosis-card-source">${esc(i.source)} · ${esc(i.period)}</p>`}</div>${selectable?`<div class="diagnosis-reference-footer">${priorityReferenceFooter(i)}</div>`:['lit','num','A.3','ajar','D.4','D.8'].includes(i.id)?`<div class="diagnosis-reference-footer"><button onclick="openReportRoot('${i.id}')">Pelajari Akar Masalah</button></div>`:''}</article>`}

function diagnosisAlternatives(){if(!['Semua',...dimensionNames].includes(reportGroupFilter))reportGroupFilter='Semua';const visible=diagnosisVisibleIndicators();const cards=diagnosisResultsMarkup(visible);return `<section class="diagnosis-alternatives">${diagnosisSummary()}<div class="diagnosis-alternative-header"><div><h1>Diagnosis</h1><p class="muted">SMA Rakyat 3 · NPSN 20260001 · Tahun data 2025</p></div></div><section id="report-indicators" aria-labelledby="diagnosis-indicators-title"><h2 id="diagnosis-indicators-title" class="diagnosis-indicators-title">Bagaimana situasi yang dihadapi oleh satuan pendidikan saya saat ini?</h2><div class="report-group-filters diagnosis-dimension-tabs" role="group" aria-label="Filter dimensi mutu">${['Semua',...dimensionNames].map(name=>`<button data-diagnosis-dimension="${esc(name)}" aria-pressed="${reportGroupFilter===name}" onclick="setReportGroupFilter('${name}')">${esc(name==='Semua'?'Semua Dimensi':name)}</button>`).join('')}</div><div class="diagnosis-source-toolbar"><span class="diagnosis-source-toolbar-label">Sumber data</span><div class="diagnosis-source-filters" role="group" aria-label="Filter sumber data">${['Rapor Pendidikan','TKA','Akreditasi'].map(source=>`<button type="button" data-diagnosis-source="${source}" aria-pressed="${diagnosisSource===source}" onclick="setDiagnosisSource('${source}')">${source}</button>`).join('')}</div></div><div class="report-list-toolbar"><span class="sub" id="diagnosis-result-count" role="status">${visible.length} indikator ditampilkan</span></div><div id="diagnosis-results">${cards}</div></section><p class="source-text">Data peringkat mengikuti referensi yang tersedia. Peringkat yang belum tersedia tidak diperkirakan. Identitas sekolah digunakan untuk demonstrasi.</p>${reportDialog()}</section>`}

const raporSituationIds=['lit','num','A.3','D.4','D.8','ajar'];
function raporSituation(){const [school,overview]=diagnosisSummary().split('<section class="diagnosis-overview-banner"');return `<section class="diagnosis-alternatives rapor-situation"><div class="rapor-band">${raporEntryBanners()}${school}</div><section class="diagnosis-overview-banner"${overview}<section id="report-indicators" aria-labelledby="diagnosis-indicators-title"><h2 id="diagnosis-indicators-title" class="diagnosis-indicators-title">Bagaimana situasi yang dihadapi oleh satuan pendidikan saya saat ini?</h2><div class="diagnosis-reference-grid">${raporSituationIds.map(id=>diagnosisReferenceCard(ind(id),false,true)).join('')}</div></section>${entryOn('kartu')?raporCta():''}${reportDialog()}</section>`}
function rapor(){return RAPOR?raporSituation():diagnosisAlternatives()}
function legacyRapor(){return `<div class="diagnosis-legacy-heading"><span class="tag">Alternatif desain · Diagnosis lama</span><button onclick="go('rapor')">Kembali ke Diagnosis utama</button></div><div class="report-school"><div><h2>SMA Rakyat 3</h2><dl><dt>NPSN</dt><dd>20260001 <span class="sub">· Contoh</span></dd><dt>Tahun data</dt><dd>2025</dd><dt>Satuan pendidikan</dt><dd>SMA · Data demonstrasi</dd></dl></div><div class="report-accreditation"><span>ⓘ Akreditasi</span><div>A</div></div></div><section id="report-indicators" class="report-indicators-section"><h2>Kondisi mutu satuan pendidikan</h2><p class="sub">Lihat seluruh indikator atau pilih kelompok mutu untuk melihat capaian dan subindikatornya.</p>${reportDimensionGroups()}</section><div class="report-download"><div><h3>Pelajari capaian sekolah secara menyeluruh</h3><p class="sub">Unduh data indikator utama dan subindikator untuk membantu refleksi bersama guru.</p></div><button onclick="downloadReport()">Unduh data indikator ↓</button></div><p class="source-text">Referensi data: Laporan Rapor Pendidikan Barokatul Huda tahun 2025, diperbarui 16 Juni 2026. Identitas SMA Rakyat 3 digunakan untuk demonstrasi. Data TKA dan akreditasi tetap berupa contoh terpisah.</p>${reportDialog()}`}
function openReportRoot(id){reportIndicator=id;go('rapor-root')}
function reportRelated(i){const codes=new Set(i.roots.map(r=>r.split(' · ')[0]).map(code=>code.split('.').slice(0,2).join('.')));const all=indicators.filter(r=>r.source==='Rapor Pendidikan'&&codes.has(r.code)&&r.id!==i.id);return all.length?all.slice(0,3):['ajar','D.2','D.3'].map(ind).filter(r=>r.id!==i.id)}
function rcRank(v){return v?esc(v):'Data peringkat belum tersedia'}
function rcSpmpBtn(i){return entryOn('indikator')?`<div class="rc-spmp-entry">${sdBtn('Susun rencana perbaikan',{variant:'primary',fullWidth:true,trailingIcon:'open-in-new',onclick:`openSpmp('${i.id}')`})}</div>`:''}
function rcRule(t){return `<div class="rc-rule"><span>${t}</span><i></i></div>`}
function rcComparison(i){return `<div class="rc-comparison">${rcRule('Dibandingkan Satdik lain, Satdik Anda termasuk')}<ul class="rc-rank"><li><p><strong>${rcRank(i.rankProvince)}</strong> di provinsi</p></li><li><p><strong>${rcRank(i.rankNational)}</strong> secara nasional</p></li></ul></div>`}
function rcScoreList(i,limit,inline){const kids=i.children||[];if(!kids.length)return '<p class="rc-empty">Belum ada subindikator dalam referensi.</p>';const row=(c,j)=>inline?`<li class="rc-score-row has-detail"><div class="rc-score-text"><p class="rc-score-name">${esc(c.name)}</p><p class="rc-score-value"><strong>${scoreText(c)}</strong>${c.unit?' '+esc(c.unit):''}</p></div><button type="button" class="rc-trigger" aria-expanded="false" aria-controls="cd-${esc(i.id)}-${j}" aria-label="Cek detail ${esc(c.name)}" onclick="toggleChildDetail(this)">Cek detail</button><div class="rc-child-detail rd-body" id="cd-${esc(i.id)}-${j}" hidden>${childDetailSections(i,c)}</div></li>`:`<li class="rc-score-row"><div class="rc-score-text"><p class="rc-score-name">${esc(c.name)}</p><p class="rc-score-value"><strong>${scoreText(c)}</strong>${c.unit?' '+esc(c.unit):''}</p></div><button type="button" class="rc-trigger" onclick="reportChildMeaning('${i.id}',${j})">Detail</button></li>`;const shown=kids.slice(0,limit).map(row).join('');const rest=kids.length-limit;return `<ul class="rc-score-list">${shown}</ul>${rest>0?`<details class="rc-more"><summary>Tampilkan ${rest} indikator lainnya<img src="assets/akar/keyboard-arrow-right.svg" width="24" height="24" alt=""></summary><ul class="rc-score-list">${kids.slice(limit).map((c,j)=>row(c,j+limit)).join('')}</ul></details>`:''}`}
function rcHead(i,main){return `<div class="rc-head"><h4 class="rc-card-name">${esc(i.name)}</h4><div class="rc-progress">${reportStatus(i)}<p class="report-delta">${reportDelta(i)}</p></div><div class="rc-triggers"><button type="button" class="rc-trigger" onclick="reportMeaning('${i.id}')">Apa arti capaian saya?</button></div></div>`}
function rcReflection(){const L=[['8a10c','48.11% 0 32.44% 8.44%'],['51473','0 0 0 3.99%'],['f4ae2','36.13% 29.72% 28.41% 61.29%'],['2092b','4.1% 15.51% 50.32% 64.69%'],['12fe3','41.5% 6.78% 0 59.1%'],['3e9b5','97.95% 35.01% 0 60.29%'],['495b0','46.32% 15.66% 0 58.87%'],['efdc4','3.92% 45.75% 3.38% 19.94%'],['c76a9','6.72% 46.88% 6.18% 21.06%'],['9e435','57.12% 46.88% 6.18% 21.06%','0px -112.891px'],['7a768','80.15% 46.88% 10.64% 44.95%','-93.156px -164.469px'],['61094','6.72% 46.88% 26.75% 21.06%','-0.008px 0.01px'],['52888','10.35% 41.03% 4.72% 21.06%','0px -8.135px'],['a39c9','4.08% 46.88% 3.7% 18.84%'],['efcf4','5.14% 45.66% 73.54% 43.11%']];const mask='url(assets/hero/c2326.svg)';return L.map(l=>`<div class="rc-layer" style="inset:${l[1]};${l[2]?`-webkit-mask-image:${mask};mask-image:${mask};-webkit-mask-size:125.03px 195.099px;mask-size:125.03px 195.099px;-webkit-mask-position:${l[2]};mask-position:${l[2]};-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;`:''}"><img src="assets/hero/${l[0]}.svg" alt="" draggable="false"></div>`).join('')}
function rcIcon(n,w=24){return `<img src="assets/rekom/${n}.svg" width="${w}" height="${w}" alt="">`}
function rcInspirations(c){const items=[['Pelajari strategi pembelajaran melalui komunitas belajar guru.','info-1','primary'],['Uji strategi di kelas, lalu refleksikan hasilnya bersama rekan guru.','kelas-1','success'],['Siapkan dukungan waktu dan sumber daya agar perbaikan berkelanjutan.','dukungan-1','warning']];return items.map((t,j)=>`<li class="rc-card"><div class="rc-card-copy"><p class="rc-card-eyebrow">Inspirasi ${j+1}</p><p class="rc-card-text">${t[0]}</p></div><div class="rc-thumb"><img src="assets/rekom/${t[1]}.png" width="64" height="64" alt=""><span class="rc-thumb-mark ${t[2]}"></span></div></li>`).join('')}
function rcPanel(c,g){const safe=esc(c.name);return `<article class="rc-panel"><div class="rc-panel-copy"><p class="rc-eyebrow-sm">Membenahi</p><h4 class="rc-panel-title">${safe}</h4><p class="rc-panel-desc">Mulai dari hasil asesmen dan pengamatan kelas. Diskusikan kebutuhan murid, pilih perbaikan praktik mengajar, lalu amati perubahan yang terjadi.</p></div><div class="rc-highlight"><img class="rc-sparkle" src="assets/rekom/sparkle-orange.svg" width="22" height="22" alt=""><p>Salah satu upaya yang bisa dilakukan adalah <strong>memulai dari hasil asesmen dan pengamatan kelas terkait ${safe.toLowerCase()}</strong>. Berikut beberapa cara konkret yang bisa dijadikan inspirasi:</p></div><div class="rc-carousel"><ul class="rc-cards" tabindex="0" aria-label="Daftar inspirasi" onscroll="rcSync(this)">${rcInspirations(c)}</ul><div class="rc-controls"><div class="rc-pagination"><button type="button" class="rc-arrow" data-dir="-1" onclick="rcSlide(this,-1)" aria-label="Inspirasi sebelumnya" disabled>${rcIcon('chevron-left')}</button><div class="rc-dots">${[0,1,2].map(k=>`<button type="button" class="rc-dot" onclick="rcSlideTo(this,${k})" aria-label="Inspirasi ${k+1}" ${k===0?'aria-current="true"':''}>${rcIcon(k===0?'toggle-active':'toggle-inactive',20)}</button>`).join('')}</div><button type="button" class="rc-arrow flip" data-dir="1" onclick="rcSlide(this,1)" aria-label="Inspirasi berikutnya">${rcIcon('chevron-right')}</button></div><button type="button" class="rc-cta" onclick="rcMaterials('${safe.replace(/'/g,"\\'")}')">Cek Materi</button></div></div></article>`}
function rcRecommendations(i,related){const groups=[i,...related];return `<section id="report-inspiration" class="rc-reco"><div class="rc-reco-inner"><div class="rc-reco-title">${rcIcon('sparkle-white')}<h2>Inspirasi cara membenahi ${esc(i.name)}</h2></div><div class="rc-reco-groups">${groups.map((r,j)=>`<section class="rc-acc"><div class="rc-acc-head"><h3>${esc(r.name)}</h3><div class="rc-acc-right">${reportStatus(r)}<img src="assets/rekom/divider.svg" width="1" height="26" alt=""><button type="button" class="rc-acc-toggle" aria-expanded="${j===0}" aria-controls="rc-panels-${j}" onclick="rcToggle(this)"><span>${j===0?'Tutup Detail':'Buka Detail'}</span>${rcIcon('expand-more')}</button></div></div><div id="rc-panels-${j}" class="rc-panels" ${j===0?'':'hidden'}>${(r.children.length?r.children:[{name:r.name}]).slice(0,2).map(c=>rcPanel(c,r)).join('')}</div></section>`).join('')}</div></div></section>`}
function rcToggle(b){const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.querySelector('span').textContent=open?'Tutup Detail':'Buka Detail';document.getElementById(b.getAttribute('aria-controls')).hidden=!open}
function rcSync(list){const step=422,atEnd=list.scrollLeft+list.clientWidth>=list.scrollWidth-2,n=list.children.length,idx=atEnd?n-1:Math.round(list.scrollLeft/step);const box=list.closest('.rc-carousel');box.querySelectorAll('.rc-dot').forEach((d,k)=>{const on=k===idx;if(on)d.setAttribute('aria-current','true');else d.removeAttribute('aria-current');d.querySelector('img').src='assets/rekom/'+(on?'toggle-active':'toggle-inactive')+'.svg'});box.querySelector('.rc-arrow:not(.flip)').disabled=idx===0;box.querySelector('.rc-arrow.flip').disabled=idx===n-1}
function rcSlideTo(btn,k){const list=btn.closest('.rc-carousel').querySelector('.rc-cards');list.scrollTo({left:k*422,behavior:'smooth'})}
function rcSlide(btn,d){const list=btn.closest('.rc-carousel').querySelector('.rc-cards');const cur=Math.round(list.scrollLeft/422);list.scrollTo({left:Math.max(0,Math.min(list.children.length-1,cur+d))*422,behavior:'smooth'})}
function rcMaterials(name){document.getElementById('report-dialog').dataset.variant='';const items=['Strategi mengajar di kelas','Panduan diskusi bersama rekan guru','Contoh praktik baik dari sekolah lain'];document.getElementById('report-dialog-content').innerHTML=`<p class="rc-eyebrow-sm">Materi pendukung</p><h2>${name}</h2><ol class="rc-materials">${items.map((t,k)=>`<li><span class="rc-material-no" aria-hidden="true">${k+1}</span><span>${t}</span></li>`).join('')}</ol><p class="sub">Contoh daftar materi. Tautan materi sebenarnya belum tersedia di prototipe.</p>`;document.getElementById('report-dialog').showModal()}
function raporRoot(){const i=ind(reportIndicator),related=reportRelated(i);const desc=reportDescriptions[i.id]||i.desc;return `<section class="rc-header"><div class="rc-inner"><nav class="rc-breadcrumb" aria-label="Breadcrumb"><button type="button" onclick="go('rapor')">Ringkasan</button><img src="assets/header/chevron-right.svg" width="24" height="24" alt=""><span aria-current="page">${esc(i.name)}</span></nav><div class="rc-header-content">${i.id==='lit'?'<img class="rc-header-art" src="assets/header/img-literasi.svg" width="84" height="84" alt="">':''}<div class="rc-header-copy"><div class="rc-titles"><p class="rc-eyebrow">Pelajari Akar Masalah dari</p><h1>${esc(i.name)}</h1></div><p class="rc-desc">${esc(desc)}</p></div></div></div></section><div class="rc-tabbar"><nav class="rc-tabs" aria-label="Bagian halaman"><button type="button" class="active" onclick="reportSection('report-root-factors',this)"><span>Akar Masalah</span><i></i></button><button type="button" onclick="reportSection('report-inspiration',this)"><span>Inspirasi Benahi</span><i></i></button></nav></div><section id="report-root-factors" class="rc-section"><div class="rc-content"><h2 class="rc-question">Apa saja faktor yang memengaruhi ${esc(i.name)} satuan pendidikan saya?</h2><div class="rc-group"><h3 class="rc-group-title">Subindikator dari ${esc(i.name)}</h3><div class="rc-main"><article class="rc-main-card">${rcHead(i,true)}${rcComparison(i)}${rcSpmpBtn(i)}</article><div class="rc-list-panel"><div class="rc-list-content">${rcRule('Beberapa subindikator yang perlu ditingkatkan')}${rcScoreList(i,3)}</div></div></div></div><div class="rc-group"><h3 class="rc-group-title">Faktor dari indikator lain yang memengaruhi capaian indikator prioritas</h3><div class="rc-related">${related.map(r=>`<article class="rc-related-card">${rcHead(r)}${rcComparison(r)}<div class="rc-related-list">${rcRule('Beberapa subindikator yang perlu ditingkatkan')}${rcScoreList(r,2)}</div>${rcSpmpBtn(r)}</article>`).join('')}</div></div></div><div class="rc-download"><div class="rc-download-inner"><div class="rc-download-copy"><h3>Unduh data indikator untuk melihat capaian dan subindikator</h3><p>Gunakan sebagai bahan diskusi dan refleksi bersama warga sekolah.</p></div><button type="button" class="rc-download-btn" onclick="downloadReport()"><span>Unduh data indikator</span><img src="assets/akar/arrow-right.svg" width="20" height="20" alt=""></button></div></div></section><section class="rc-reflection" aria-labelledby="rc-reflection-title"><div class="rc-illustration" aria-hidden="true">${rcReflection()}</div><h2 id="rc-reflection-title">Mari berhenti dan berpikir sejenak...</h2><ul class="rc-dialogue"><li>Seberapa sering guru membahas hasil asesmen murid bersama?</li><li>Dukungan apa yang sudah diberikan sekolah untuk meningkatkan ${esc(i.name.toLowerCase())}?</li></ul></section>${rcRecommendations(i,related)}${reportDialog()}`}
function reportSection(id,button){document.querySelectorAll('.rc-tabs button').forEach(b=>b.classList.toggle('active',b===button));document.getElementById(id).scrollIntoView({behavior:'smooth',block:'start'})}
function reportMeaning(id){const i=ind(id);document.getElementById('report-dialog').dataset.variant='';document.getElementById('report-dialog-content').innerHTML=`<span class="tag">${esc(i.code)}</span><h2>${esc(i.name)}</h2><p>${esc(i.definition||reportDescriptions[id]||i.desc)}</p><div class="line"></div><p><b>Capaian ${/^20\d\d$/.test(String(i.period))?i.period:'terbaru'}: ${scoreText(i)} ${esc(i.unit)}</b></p><p>${esc(i.achievementDefinition||i.unavailableReason)}</p>${i.average?`<p>Nilai rerata (berbeda dari persentase murid): <b>${scoreText(i.average)}</b></p>`:''}<p>Kategori pada data referensi: <b>${esc(i.level)}</b>.</p>${['lit','num'].includes(id)?'<p>Persentase menunjukkan proporsi murid yang mencapai kompetensi minimum pada indikator ini.</p>':''}<p class="sub">Gunakan capaian ini bersama subindikator dan bukti dari sekolah untuk memahami area perbaikan.</p>`;document.getElementById('report-dialog').showModal()}
function childDetailSections(i,c){const has=typeof c.score==='number',prev=typeof c.previous==='number';const val=scoreText(c)+(has&&c.unit?' '+esc(c.unit):'');const d=has&&prev?c.score-c.previous:0;const cmp=has&&prev?(d===0?', tidak berubah dari tahun 2024 ('+scoreText({score:c.previous})+')':', '+(d>0?'naik ':'turun ')+scoreText({score:Math.abs(d)})+' dari tahun 2024 ('+scoreText({score:c.previous})+')'):'';const how=c.achievementDefinition||'';const src=String(c.source||i.source||'').replace(/\s*20\d{2}$/,'');
return `<section><h3>${esc(c.name)} artinya</h3><p>${esc(c.definition||'Definisi belum tersedia.')}</p></section>${how?`<section><h3>Bagaimana cara mengukur capaian indikator ini?</h3><p>${esc(how)}</p></section>`:''}<section><p>${has?`Nilai capaian ${esc(c.name)} Anda <b>tahun ini ${val}</b>${cmp}.`:esc(c.unavailableReason||'Nilai capaian belum tersedia untuk satuan pendidikan Anda.')}</p></section>${src?`<p class="rd-source">${sdIcon('folder')}<span>Sumber data: ${esc(src)}</span></p>`:''}`}
function reportChildMeaning(id,index){const i=ind(id),c=i.children[index];const dlg=document.getElementById('report-dialog');dlg.dataset.variant='detail';document.getElementById('report-dialog-content').innerHTML=`<header class="rd-head"><h2>Detail ${esc(c.name)}</h2>${modalClose('report-dialog')}</header><div class="rd-body">${childDetailSections(i,c)}</div>`;dlg.showModal();dlg.focus()}
function toggleChildDetail(btn){const open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',String(open));btn.textContent=open?'Tutup detail':'Cek detail';document.getElementById(btn.getAttribute('aria-controls')).hidden=!open}
const glossaryTerms=[['A','Angka Partisipasi Kasar (APK) SD/MI/Paket A/SDLB','Jumlah peserta didik di jenjang SD sederajat dibagi jumlah penduduk usia 7 (tujuh) sampai dengan 12 (dua belas) tahun pada kab/kota yang bersangkutan.'],['A','APM per kelompok gender','Selisih APK jenjang SMA sederajat di daerah dengan kriteria individu berjenis kelamin perempuan dengan APK jenjang SMA sederajat di daerah dengan kriteria individu berjenis kelamin laki-laki.'],['A','APK berdasarkan kelompok gender','Selisih APS usia 16-18 di daerah dengan kriteria individu berjenis kelamin perempuan dengan APS usia 16-18 di daerah dengan kriteria individu berjenis kelamin laki-laki.'],['A','Aktivasi kognitif','Rata-rata nilai untuk instruksi yang adaptif, panduan guru, aktivitas interaktif, pembelajaran literasi, pembelajaran numerasi, skor iklim pembelajaran terbuka di survei lingkungan belajar.'],['B','Beriman, Bertakwa kepada Tuhan yang Maha Esa, dan Berakhlak Mulia','Penerapan ajaran agama dan kepercayaan dalam kehidupan sehari-hari melalui perbuatan pada manusia, alam, dan negara.'],['B','Bekerja','Persentase lulusan SMK yang mendapatkan pekerjaan dalam satu tahun setelah lulus.'],['B','Bekerja','Persentase lulusan SMK dengan pendapatan sama dengan atau di atas Upah Minimum Provinsi dalam satu tahun setelah lulus.'],['B','Belajar tentang pembelajaran','Aktivitas belajar guru yang bertujuan meningkatkan pengetahuan dan keterampilan mengajar.']];
const glossaryLetters=['A','B','C'];
let glossaryQuery='';
function glossaryResults(q){const k=String(q||'').trim().toLowerCase(),hit=glossaryTerms.filter(t=>!k||(t[1]+' '+t[2]).toLowerCase().includes(k));if(!hit.length)return `<p class="gloss-empty" role="status">Tidak ada istilah untuk "${esc(q)}". Periksa ejaan atau coba kata kunci lain.</p>`;return glossaryLetters.map(L=>{const items=hit.filter(t=>t[0]===L);if(k&&!items.length)return '';return `<section class="gloss-group" id="gloss-${L}" aria-label="Istilah huruf ${L}"><h2 class="gloss-letter">${L}</h2><div class="gloss-list">${items.length?items.map(t=>`<article class="gloss-item"><h3>${esc(t[1])}</h3><p>${esc(t[2])}</p></article>`).join(''):`<p class="gloss-none">Tidak ada istilah yang diawali huruf ${L}.</p>`}</div></section>`}).join('')}
function glossarySearch(v){glossaryQuery=v;const el=document.getElementById('gloss-results');if(el)el.innerHTML=glossaryResults(v)}
function glossaryJump(L){const el=document.getElementById('gloss-'+L);if(!el){toast('Belum ada istilah yang diawali huruf '+L+'.');return}el.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function glossaryPage(){const letters='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');return `<section class="gloss-page"><div class="gloss-hero"><h1>Glosarium</h1><p>Temukan definisi dari istilah-istilah yang ada di Rapor Pendidikan.</p><form class="gloss-form" role="search" onsubmit="event.preventDefault();glossarySearch(document.getElementById('gloss-q').value)"><div class="gloss-search">${sdTextField({label:'Cari istilah atau kata kunci',id:'gloss-q',value:glossaryQuery,placeholder:'Cari istilah atau kata kunci',hideLabel:true,oninput:'glossarySearch(this.value)',trailing:''})}${sdIcon('search')}</div>${sdBtn('Cari',{variant:'ultimate',size:'lg',type:'submit'})}</form></div><nav class="gloss-letters" aria-label="Loncat ke huruf">${letters.map(L=>sdBtn(L,{variant:'quiet',size:'sm',className:'gloss-letter-btn',onclick:`glossaryJump('${L}')`,attrs:`aria-label="Huruf ${L}"`})).join('')}</nav><div id="gloss-results" class="gloss-results">${glossaryResults(glossaryQuery)}</div></section>`}
let downloadYear='2025';
function setDownloadYear(value){if(!['2025','2024','2023'].includes(value))return;downloadYear=value;render()}
function downloadSelectedReport(){if(downloadYear!=='2025')return;downloadReport()}
function downloadsPage(){const available=downloadYear==='2025';
const parts=['1. Panduan Pemanfaatan Rapor & PBD','2. Laporan Rapor Pendidikan','2.1 Rekomendasi Keseluruhan','2.2 Rekomendasi Prioritas','3. Lembar Kerja RKT','4. Lembar Kerja ARKAS'];
const steps=[['Kumpulkan dan maknai data kondisi Satuan Pendidikan','Gunakan data Rapor Pendidikan dan data penunjang lain yang relevan untuk memahami kondisi Satuan Pendidikan Anda.'],['Tetapkan perbaikan prioritas layanan Anda','Penetapan prioritas dapat dilakukan lewat analisis mandiri atau dengan alat bantu rekomendasi PBD dari Kemendikbudristek.'],['Rencanakan upaya perbaikan layanan Anda','Buatlah rencana perbaikan yang meliputi aspek pembelajaran, pengembangan profesional PTK, dan pengelolaan sumber daya.'],['Implementasi dan evaluasi hasilnya secara berkala','Dalam penerapannya, Anda dapat menyesuaikan kembali perencanaan yang dibuat sesuai dengan kebutuhan.']];
return `<section class="unduh-page"><div class="unduh-hero"><h1>Unduh Laporan Rapor Pendidikan</h1><p>Unduh Rapor Pendidikan dan dapatkan rekomendasi Perencanaan Berbasis Data satuan pendidikan Anda.</p></div>
<article class="unduh-card"><section class="unduh-report" aria-labelledby="unduh-laporan"><h2 id="unduh-laporan" class="unduh-title">Laporan Rapor Pendidikan</h2><p class="unduh-sub">Laporan akan terunduh dalam 1 file Excel yang terdiri dari 6 bagian:</p><ul class="unduh-parts">${parts.map(t=>`<li>${sdIcon('check')}<span>${esc(t)}</span></li>`).join('')}</ul>
<div class="unduh-input">${sdSelect({label:'Tahun',options:['2025','2024','2023'].map(y=>({value:y,label:y})),value:downloadYear,onchange:'setDownloadYear(this.value)'})}${sdBtn('Unduh Rapor Pendidikan',{variant:'ultimate',size:'lg',disabled:!available,onclick:'downloadSelectedReport()'})}</div>${available?'':`<div class="unduh-unavailable">${sdBanner({tone:'warning',title:'Rapor Pendidikan tahun '+downloadYear+' belum tersedia',children:'<p>Pilih tahun 2025 untuk mengunduh laporan pada prototipe ini.</p>'})}</div>`}</section>
<section class="unduh-pbd" aria-labelledby="unduh-pbd"><div class="unduh-rule"><h2 id="unduh-pbd" class="unduh-heading">Tahapan Penerapan Perencanaan Berbasis Data</h2></div><p class="unduh-body">Berikut adalah gambaran umum 4 tahap melakukan PBD. Kumpulan materi panduan dan alat bantu terlengkap terkait pemanfaatan Rapor Pendidikan dan PBD dapat Anda temukan melalui tautan <a href="#" onclick="return false">berikut</a> (diperbarui berkala).</p>
<ol class="unduh-steps">${steps.map((t,i)=>`<li><img src="assets/unduh/langkah-${i+1}.svg" width="276" height="140" alt=""><div class="unduh-step-text"><span class="unduh-num" aria-hidden="true">${i+1}</span><h3>${esc(t[0])}</h3><p>${esc(t[1])}</p></div></li>`).join('')}</ol></section>${entryOn('unduh')?`<section class="unduh-spmp" aria-labelledby="unduh-spmp-title"><div class="unduh-rule"><h2 id="unduh-spmp-title" class="unduh-heading">Lanjutkan ke perencanaan</h2></div><p class="unduh-body">Setelah mengunduh laporan, kerjakan Lembar Kerja RKT langsung di Platform SPMP: tetapkan prioritas, petakan akar masalah, dan susun kegiatan.</p>${sdBtn('Buka Platform SPMP',{variant:'ultimate',size:'lg',trailingIcon:'open-in-new',onclick:'openSpmp()'})}</section>`:''}</article></section>`}
function downloadReport(){const rows=[['Kode','Indikator','Induk','Skor 2025','Satuan','Kategori','Sumber'],...indicators.filter(i=>i.source==='Rapor Pendidikan').flatMap(i=>{return [[i.code,i.name,'',i.score,i.unit,i.level,i.origin],...i.children.map(c=>[c.code,c.name,i.code,c.score,c.unit,c.level,c.source])]})];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='rapor-pendidikan-sma-rakyat-3-2025.csv';link.click();URL.revokeObjectURL(url);toast('Data indikator siap diunduh.')}
function help(){return `<h1>Pusat Bantuan</h1><p class="muted">Panduan singkat menyusun dan menjalankan Rencana Kerja Tahunan.</p>${[['Apa itu Siklus 6M?','Siklus 6M membantu sekolah memperbaiki mutu melalui enam tahap: Menetapkan prioritas dan target, Memetakan akar masalah, Merencanakan kegiatan, Melaksanakan kegiatan, Mengevaluasi hasil, dan Mengendalikan perbaikan untuk siklus berikutnya.'],['Kapan RKT disusun?','RKT disusun untuk satu tahun ajaran, dari Juli hingga Juni. Anda dapat menyimpan draf dan melanjutkannya kembali.'],['Berapa indikator yang perlu dipilih?','Pilih 2–3 indikator prioritas dari sumber data mana pun. Setiap indikator perlu memiliki target dan minimal satu kegiatan.'],['Kapan rencana dapat diperbaiki?','Rencana dapat dilengkapi saat berstatus Draf. Selesaikan rencana pada tahap Merencanakan untuk mulai mencatat capaian.'],['Kapan capaian dapat dimasukkan?','Setelah rencana prioritas disimpan. Status menjadi Sudah ada rencana dan tombol Lanjutkan pelaksanaan tersedia di daftar siklus.'],['Bagaimana menggunakan menu demo?','Klik Menu demo di pojok kanan bawah. Anda dapat berpindah tahap, mengisi contoh rencana, dan mencoba status draf, pelaksanaan, evaluasi, dan tindak lanjut. Semua simulasi hanya tersimpan di peramban ini.']].map(([q,a])=>`<details class="card"><summary><b>${q}</b></summary><p class="muted" style="margin-top:15px">${a}</p></details>`).join('')}`}
const demoStatuses=[['draft','Draf — rencana belum disimpan'],['active','Sudah ada rencana — masukkan capaian'],['evaluation-open','Masa evaluasi'],['followup','Evaluasi selesai — tindak lanjut'],['completed','Selesai']];
function resetSelfEvaluationDemo(){reflections={};reflectionYear='';reflectionStep=0;localStorage.removeItem('spmp-self-reflections-v2');demo=false;go('self-evaluation');toast('Evaluasi diri direset. Data siklus tetap tersimpan.')}
function ensureSample(){if(data.priorities.length<2){data.priorities=['lit','num'];data.targets={lit:35,num:50};}data.priorities.forEach((id,j)=>{if(!data.targets[id])data.targets[id]=Math.min(ind(id).max,(typeof ind(id).score==='number'?ind(id).score:0)+15);if(!data.roots[id]?.length)data.roots[id]=ind(id).roots.length?[ind(id).roots[0]]:['Hasil pengamatan sekolah perlu ditelaah bersama'];if(!data.activities.some(a=>a.indicator===id))data.activities.push({id:'demo-'+id,indicator:id,name:id==='lit'?'Pendampingan guru untuk pembelajaran literasi':id==='num'?'Pembelajaran numerasi berbasis masalah sehari-hari':'Komunitas belajar untuk '+ind(id).name,root:data.roots[id][0],implementation:j?'Guru merancang dan mencoba pembelajaran numerasi dengan masalah sehari-hari, kemudian membahas hasilnya dalam komunitas belajar.':'Guru mengikuti pendampingan membaca teks informasi bersama dua guru inti melalui komunitas belajar sekolah.',target:'',quantity:'',unit:'',proof:'',realistic:'',relevant:'',months:[],needsBudget:j===0,budget:j===0?2500000:0,budgetLines:j===0?[{description:'Bahan pendampingan dan bacaan',month:'Agu',quantity:25,unit:'paket',price:100000}]:[]})});if(data.priorities.includes('lit')&&data.activities.some(a=>a.id==='demo-lit')&&!data.activities.some(a=>a.id==='demo-lit-2')){data.activities.push({id:'demo-lit-2',indicator:'lit',name:'Klub membaca mingguan di kelas',root:data.roots.lit[0],implementation:'Wali kelas menyediakan sesi membaca teks informasi 30 menit tiap pekan, lalu murid menceritakan ulang isi bacaannya.',target:'',quantity:'',unit:'',proof:'',realistic:'',relevant:'',months:[],needsBudget:false,budget:0,budgetLines:[]})}prepareSampleActivityForms();save()}
function prepareDemo(){const year=data.year;data=seed();data.year=year;ensureSample();data.status='Draf';data.budget='Belum diisi';data.evaluationOpen=false;data.evaluationSubmitted=false;data.revisionKind=null;data.planSaved={};demo=false;history=[];localStorage.setItem('spmp-history-spreadsheet-v3','[]')}
function prepareSampleActivityForms(){data.activities.forEach(a=>{if(a.implementation===undefined)a.implementation=a.realistic||a.name;if(a.needsBudget===undefined){a.needsBudget=Number(a.budget)>0;a.budgetLines=a.needsBudget?[{description:'Pendukung kegiatan',month:a.months[0]||'Agu',quantity:1,unit:'paket',price:Number(a.budget)}]:[]}})}
function seedDemoProgress(){data.activities.forEach((a,j)=>{data.progress[a.id]={notes:j?'Pembelajaran mulai dicoba di kelas. Diskusi refleksi perlu penyesuaian jadwal.':'Pendampingan berjalan sesuai rencana. Guru mulai menggunakan teks informasi dalam pembelajaran.',link:'',files:[]}})}
function seedDemoEvaluation(){data.activities.forEach((a,j)=>data.evaluation[a.id]={result:j?'Perlu penyesuaian':'Efektif',notes:j?'Jadwal kegiatan perlu disesuaikan dengan beban mengajar.':'Guru mulai menerapkan hasil pendampingan dalam pembelajaran.'})}
function demoReview(){prepareDemo();save();go('review')}
function demoSummary(){jump(5);data.status='Selesai';data.evaluationOpen=true;data.evaluationSubmitted=true;save();window.__docJustDone=true;showDocRecord('current',0,'ringkasan')}
function demoSavedPlan(){prepareDemo();data.status='Sudah ada rencana';data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));save();go('home')}
function archiveCycle(year,v){const s=sampleArchive();s.year=year;if(v){s.targets={lit:30,num:45};s.activities.forEach(a=>{a.id='old'+v+'-'+a.indicator;if(a.indicator==='lit'){a.name='Komunitas belajar membaca teks informasi';a.needsBudget=false;a.budget=0;a.budgetLines=[]}else{a.needsBudget=true;a.budget=1800000;a.budgetLines=[{description:'Alat peraga numerasi',month:'Sep',quantity:6,unit:'set',price:300000}]}});s.progress={};s.evaluation={};s.follow={};s.activities.forEach(a=>{s.progress[a.id]={notes:'Kegiatan terlaksana dan dibahas dalam refleksi bersama guru.',link:'',files:[]};s.evaluation[a.id]={result:a.indicator==='lit'?'Perlu penyesuaian':'Efektif',notes:'Praktik pembelajaran disepakati dan dicoba di kelas.'};s.follow[a.id]={type:'Korektif',action:'Lanjutkan dengan penyesuaian jadwal.',carry:a.indicator==='lit'}})}return s}
function demoOpenEvaluation(){if(data.status==='Sudah ada rencana'&&data.activities.length&&!data.evaluationSubmitted){data.evaluationOpen=true;save();go('home');return}simulate('evaluation-open')}
function demoDraft(){prepareDemo();data.activities=[];data.planSaved={};data.lastStep=2;save();go('home')}
function demoCyclesDone(){simulate('completed');data.year='2026/2027';history=[archiveCycle('2022/2023',0),archiveCycle('2023/2024',1),archiveCycle('2024/2025',0),archiveCycle('2025/2026',1)];localStorage.setItem('spmp-history-spreadsheet-v3',JSON.stringify(history));save();go('home')}
function demoCycles(){prepareDemo();data.year='2027/2028';data.status='Sudah ada rencana';data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));seedDemoProgress();history=[archiveCycle('2023/2024',0),archiveCycle('2024/2025',1),archiveCycle('2025/2026',0),archiveCycle('2026/2027',1)];localStorage.setItem('spmp-history-spreadsheet-v3',JSON.stringify(history));save();go('home')}
function jump(i){if(!Number.isInteger(i)||i<0||i>5)return;prepareDemo();if(i<=2){data.activities=[];data.planSaved={};if(i===0){data.priorities=[];data.targets={};data.roots={}}if(i===1)data.roots={};}if(i>=3){data.status='Sudah ada rencana';data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));seedDemoProgress()}if(i>=4)data.evaluationOpen=true;if(i===5){data.evaluationSubmitted=true;seedDemoEvaluation()}stage=i;save();go('flow')}
function simulate(s){if(s!=='empty'&&!demoStatuses.some(([key])=>key===s))return;prepareDemo();if(s==='empty'){const year=data.year;data=seed();data.year=year}else if(['active','evaluation-open','followup','completed'].includes(s)){data.status='Sudah ada rencana';data.planSaved=Object.fromEntries(data.priorities.map(id=>[id,true]));seedDemoProgress();if(s!=='active')data.evaluationOpen=true;if(s==='followup'||s==='completed'){data.evaluationSubmitted=true;seedDemoEvaluation()}if(s==='completed'){data.status='Selesai';data.activities.forEach(a=>data.follow[a.id]={type:'Korektif',action:'Lanjutkan kegiatan dengan penyesuaian jadwal dan diskusikan hasilnya bersama guru.',carry:true})}}save();go('home')}
function demoReflection(mode){if(!['start','review','saved'].includes(mode))return;simulate('completed');const year=data.year,ev=reflectionEvidence(data);const r={scores:{},notes:{},justifications:{},completed:false};if(mode!=='start'){ev.forEach((e,i)=>r.scores[i]=e.score);r.scores[1]=Math.max(0,ev[1].score-1);r.scores[2]=Math.min(4,ev[2].score+1)}if(mode==='saved'){r.justifications[1]='Sekolah masih perlu memverifikasi akar masalah melalui diskusi guru sebelum menilai praktik ini lebih tinggi.';r.justifications[2]='Sekolah telah meninjau rancangan anggaran bersama tim, tetapi catatannya belum dimasukkan ke prototipe.';r.completed=true;r.evidenceSnapshot=ev;r.savedAt=new Date().toISOString()}reflections[year]=r;reflectionSave();page='self-evaluation';reflectionYear=mode==='saved'?'':year;reflectionStep=mode==='start'?0:6;demo=false;render();window.scrollTo(0,0)}

function resetDemo(){if(!confirm('Hapus semua isian siklus, lampiran, dan evaluasi diri demo di peramban ini?'))return;data=seed();history=[];reflections={};reflectionYear='';reflectionStep=0;localStorage.removeItem('spmp-history-spreadsheet-v3');localStorage.removeItem('spmp-self-reflections-v2');save();go('home');toast('Seluruh data demo telah diatur ulang. Riwayat contoh bawaan tetap tersedia.')}
function archive(){const current=data;data={...seed(),year:'2026/2027',priorities:['lit','num'],targets:{lit:70,num:75},roots:{lit:[ind('lit').roots[0]],num:[ind('num').roots[0]]},status:'Selesai',budget:'Disetujui'};page='detail';render();data=current;$('.wrap').insertAdjacentHTML('afterbegin','<div class="notice">Riwayat contoh tahun ajaran 2026/2027 · Arsip hanya dapat dilihat.</div>')}
render();

function newCycle(){let old=JSON.parse(JSON.stringify(data));history.push(old);localStorage.setItem('spmp-history-spreadsheet-v3',JSON.stringify(history));let year=Number(old.year.split('/')[0])+1;data=seed();data.year=year+'/'+(year+1);data.activities=old.activities.filter(a=>old.follow[a.id]?.carry).map(a=>({...a,id:'next-'+a.id}));data.priorities=[...new Set(data.activities.map(a=>a.indicator))];data.priorities.forEach(id=>{data.roots[id]=old.roots[id];data.custom[id]=old.custom[id]||[]});save();start();toast('Draf tahun berikutnya dibuat. Tinjau kembali prioritas, target, dan kegiatan.')}
function viewHistory(i){const current=data;data=history[i];page='detail';render();data=current;document.querySelector('.wrap').insertAdjacentHTML('afterbegin','<div class="notice">Arsip siklus sekolah · Hanya dapat dilihat.</div>')}

function scoreText(i){return typeof i.score==='number'?new Intl.NumberFormat('id-ID',{maximumFractionDigits:2}).format(i.score):i.score===null?'Tidak tersedia':esc(i.score)}
function referenceDetails(i){return `<p class="source-text">${esc(i.origin)} · ${esc(i.period)}${typeof i.previous==='number'&&typeof i.score==='number'?` · Perubahan ${new Intl.NumberFormat('id-ID',{signDisplay:'always',maximumFractionDigits:2}).format(i.score-i.previous)} poin dari 2024`:''}</p>${i.children.length?`<div class="line"></div><b class="sub">Subindikator</b>${i.children.map(c=>`<div class="listitem"><span class="source-text">${esc(c.code)}</span> ${esc(c.name)}<br><b>${scoreText(c)} ${esc(c.unit)}</b>${c.level?' · '+esc(c.level):''}</div>`).join('')}`:''}`}

function chosenPanel(){return `<aside class="chosen-panel"><div class="card"><div class="row"><h3>Prioritas pilihan Anda</h3>${sdBadge(`${data.priorities.length}/3`,'blue')}</div>${data.priorities.length?data.priorities.map(id=>`<div class="chosen-item"><span>${esc(ind(id).name)}</span><span class="chosen-target"><b>${scoreText(ind(id))}${ind(id).unit?' '+esc(ind(id).unit):''} → ${esc(data.targets[id]??'—')}${esc(ind(id).unit)}</b><button class="quiet" onclick="requestPriorityTarget('${id}')">Ubah target</button></span><button class="remove-priority" aria-label="Hapus prioritas ${esc(ind(id).name)}" title="Hapus prioritas" onclick="choose('${id}',false)">×</button></div>`).join(''):'<p class="sub">Belum ada indikator dipilih.</p>'}<div class="chosen-actions"><button class="primary" onclick="next()">Lanjutkan →</button><button onclick="save();go('home')">Simpan draf & keluar</button></div></div></aside>`}

function activitySummaryTitle(a){if(!a.recommendationKey)return a.name;const parts=a.recommendationKey.split(':');const index=Number(parts[2]);const topics={'A.1.1':'membaca teks informasi','A.2.1':'domain bilangan','D.3.1':'visi-misi satuan pendidikan','D.8.1':'toleransi agama dan budaya','D.6.1':'kesetaraan gender','D.4.8':'pencegahan dan penanganan kekerasan seksual','D.1.2':'dukungan psikologis','A.3.5':'kebinekaan global'};const topic=topics[parts[1]];if(!topic)return a.name;if(parts[1]==='D.3.1')return ['Penyelarasan visi-misi satuan pendidikan','Penerjemahan visi-misi ke dalam pembelajaran','Refleksi penerapan visi-misi sekolah'][index]||a.name;if(index===0)return 'Peningkatan kompetensi dalam '+topic;if(index===1)return 'Penerapan '+topic+' dalam pembelajaran';if(index===2)return 'Penguatan program dan kebijakan tentang '+topic;if(index===3&&parts[1]==='A.1.1')return 'Pemenuhan buku teks dan bahan bacaan';return a.name}
function activityBudgetSummary(a){if(!a.needsBudget)return 'Tidak membutuhkan anggaran';const lines=a.budgetLines||[];const started=lines.filter(r=>r.description.trim());if(!started.length)return 'Membutuhkan anggaran <span class="sub">· Rincian anggaran belum diisi</span>';const incomplete=started.some(r=>!r.month||!r.quantity||!r.unit.trim()||r.price==='');return 'Membutuhkan anggaran <span class="sub">· '+(incomplete?'Rincian anggaran belum lengkap':money(a.budget))+'</span>'}
function savedActivityBudgetDetails(a){const lines=(a.budgetLines||[]).filter(r=>Object.values(r).some(v=>String(v??'').trim()));if(!a.needsBudget||!lines.length)return '';return `<details class="saved-budget-details"><summary>Tampilkan detail anggaran</summary><div class="budget-lines-scroll"><table><thead><tr><th>Kode Kegiatan ARKAS</th><th>Uraian Kegiatan ARKAS</th><th>Bulan Dianggarkan</th><th>Jumlah</th><th>Satuan</th><th>Harga Satuan</th><th>Total</th></tr></thead><tbody>${lines.map(r=>`<tr><td>${esc(r.code||'—')}</td><td>${esc(r.description||'—')}</td><td>${esc(r.month||'—')}</td><td>${esc(r.quantity||'—')}</td><td>${esc(r.unit||'—')}</td><td>${r.price!==''&&r.price!==undefined?money(r.price):'—'}</td><td>${r.quantity!==''&&r.quantity!==undefined&&r.price!==''&&r.price!==undefined?money(Number(r.quantity)*Number(r.price)):'—'}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="6">Total anggaran kegiatan</td><td><b>${money(a.budget)}</b></td></tr></tfoot></table></div></details>`}
function savedPlanOverview(id,acts){const i=ind(id);return `<article class="card guided-plan saved-plan layered-summary" id="plan-${id}"><header class="guided-header"><span class="tag">Prioritas perbaikan</span><h2>${esc(i.name)}</h2>${indicatorTargetContext(id)}</header><div class="saved-activities"><div class="row saved-list-heading"><h3>Kegiatan yang direncanakan</h3><span class="sub">${acts.length} kegiatan</span></div>${acts.map((a,j)=>`<section class="saved-activity"><h3>${j+1}. ${esc(activitySummaryTitle(a))}</h3><p class="sub">Menjawab: ${esc(a.root)}</p><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(a.implementation)}</p></div>${a.recommendationKey?`<details class="saved-recommendation"><summary>Tampilkan teks rekomendasi lengkap</summary><p>${esc(a.name)}</p></details>`:''}<p class="saved-budget-status">${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}</section>`).join('')}</div><footer class="hierarchy-footer"><span>✓ Rencana prioritas tersimpan</span><button onclick="editSavedPlan('${id}')">Ubah rencana</button></footer></article>`}

function editSavedPlan(id){if(!['Draf','Perlu revisi'].includes(data.status))return toast('Rencana telah disimpan dan tidak dapat diedit lagi.');data.planSaved={...data.planSaved,[id]:false};plannerOpen[id]=0;save();render();document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'})}


function reviewCards(readOnly=false){return data.priorities.map((id,index)=>{const i=ind(id),acts=data.activities.filter(a=>a.indicator===id);return `<article class="card review-flow-card"><div class="review-flow-head"><span class="hierarchy-eyebrow">Menetapkan, prioritas ${index+1}</span><h2>${esc(i.name)}</h2><p class="source-text">${esc(i.code)}, ${esc(i.source)}, periode ${esc(i.period)}</p>${indicatorTargetContext(id)}${readOnly?'':`${sdBtn('Ubah target',{variant:'quiet',size:'sm',onclick:`editFromReview('${id}','target')`})}`}</div><div class="review-flow-body"><section class="review-chain"><div><div class="row review-chain-title"><h3>Memetakan: akar masalah yang dipilih</h3>${readOnly?'':`${sdBtn('Ubah',{variant:'quiet',size:'sm',onclick:`editFromReview('${id}','roots')`})}`}</div>${(data.roots[id]||[]).map(root=>`<p class="review-root">${esc(root)}</p>`).join('')}</div></section><div class="review-planned-activities"><h3>Merencanakan: kegiatan yang direncanakan</h3>${acts.map((activity,j)=>`<section class="review-aligned-activity"><div class="row"><h4>${j+1}. ${esc(activitySummaryTitle(activity))}</h4>${readOnly?'':`${sdBtn('Ubah kegiatan',{variant:'quiet',size:'sm',onclick:`editFromReview('${id}','activity','${activity.id}')`})}`}</div><p class="source-text">Menjawab: ${esc(activity.root)}</p><div class="review-activity-columns"><div class="review-implementation-column"><div class="hierarchy-result"><span>Penjelasan Implementasi Kegiatan</span><p>${esc(activity.implementation||'Belum diisi')}</p></div>${activity.recommendationKey?`<details class="saved-recommendation"><summary>Tampilkan teks rekomendasi lengkap</summary><p>${esc(activity.name)}</p></details>`:''}</div><aside class="review-budget-column"><span class="review-budget-label">Anggaran kegiatan</span><p>${activityBudgetSummary(activity)}</p>${savedActivityBudgetDetails(activity)}</aside></div></section>`).join('')}</div></div><div class="review-flow-footer"><span>${acts.length} kegiatan, total anggaran terisi <b>${money(acts.reduce((sum,a)=>sum+Number(a.budget||0),0))}</b></span></div></article>`}).join('')}

function editFromReview(id,part,activityId){if(!['Draf','Perlu revisi'].includes(data.status))return toast('Rencana telah disimpan sebagai acuan pelaksanaan.');if(part==='target'){requestPriorityTarget(id);return}if(part==='roots'){stage=1;go('flow');document.getElementById('root-card-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});return}data.planSaved={...data.planSaved,[id]:false};plannerOpen[id]=part==='target'?0:part==='success'?2:1;stage=2;save();go('flow');document.getElementById('plan-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});const fieldId=activityId+'-implementation';document.getElementById(fieldId)?.focus({preventScroll:true})}

function budgetReview(readOnly=false){const funded=data.activities.filter(a=>a.needsBudget===true||Number(a.budget)>0),total=funded.reduce((sum,a)=>sum+Number(a.budget||0),0);return `<section class="card budget-review"><div class="row"><div><span class="hierarchy-eyebrow">Tinjauan anggaran</span><h2>Rincian anggaran untuk ARKAS</h2><p class="sub">Rangkuman kebutuhan anggaran dari kegiatan yang direncanakan. Rincian yang belum diisi tetap bersifat opsional.</p></div>${sdBadge(`${funded.length} kegiatan membutuhkan anggaran`,'blue')}</div>${funded.length?funded.map(a=>`<section class="review-aligned-activity"><div class="row"><h3>${esc(activitySummaryTitle(a))}</h3>${readOnly?'':`${sdBtn('Ubah',{variant:'quiet',size:'sm',onclick:`editFromReview('${a.indicator}','budget','${a.id}')`})}`}</div><p class="sub">Prioritas: ${esc(ind(a.indicator).name)}</p><p>${activityBudgetSummary(a)}</p>${savedActivityBudgetDetails(a)}</section>`).join(''):'<p class="sub">Tidak ada kegiatan yang ditandai membutuhkan anggaran.</p>'}<p>Total anggaran terisi: <b>${money(total)}</b></p>${!readOnly&&funded.some(a=>Number(a.budget)>0)?sdCheckbox({id:'budget-confirm',label:'Saya telah meninjau rincian anggaran yang terisi untuk disampaikan ke ARKAS.'}):''}<p class="source-text">Prototipe ini belum mengirim data ke ARKAS. Persetujuan anggaran dan rencana dilakukan terpisah.</p></section>`}


function listRktStatus(rkt){if(rkt.status==='Selesai')return 'Selesai';if(rkt.evaluationSubmitted)return 'Tindak lanjut belum selesai';if(rkt.evaluationOpen)return 'Masa evaluasi';return rkt.status==='Sudah ada rencana'||Object.values(rkt.planSaved||{}).some(Boolean)?'Sudah ada rencana':'Draf'}

function approvedRktView(){return `<div class="flow-heading"><div><div class="eyebrow">Rencana Kerja Tahunan · ${esc(data.year)}</div><h1>Rencana perbaikan sekolah</h1><p class="muted">${period()} · SMA Merdeka Belajar 1</p></div><div class="document-status">${badge(data.status==='Sudah ada rencana'?'Sudah ada rencana':data.status==='Selesai'?'Selesai':listRktStatus(data))}<span class="sub">Hanya dapat dilihat</span></div></div><div class="notice approved-notice">${data.status==='Sudah ada rencana'?'Rencana telah disimpan dan menjadi acuan pelaksanaan. Perbarui capaian melalui tombol Lanjutkan pelaksanaan pada daftar siklus.':data.status==='Selesai'?'Siklus RKT ini telah selesai. Rencana tersimpan sebagai arsip sekolah.':'Ringkasan rencana beserta rincian anggaran. Halaman ini hanya dapat dilihat.'}</div><section class="flow-content">${reviewCards(true)}${budgetReview(true)}<div class="card approved-total"><span>${data.priorities.length} prioritas · ${data.activities.length} kegiatan</span><b>Total anggaran: ${money(data.activities.reduce((sum,a)=>sum+Number(a.budget||0),0))}</b></div></section>`}
function openExecution(){if(data.status!=='Sudah ada rencana')return toast('Selesaikan rencana prioritas terlebih dahulu.');stage=3;go('flow')}

document.addEventListener('click',event=>{if(!event.target.closest('.row-overflow'))document.querySelectorAll('.row-overflow[open]').forEach(el=>el.open=false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.row-overflow[open]').forEach(el=>{el.open=false;el.querySelector('summary').focus()})});


let menetapkanFilter='Rekomendasi Indikator',menetapkanSource='Semua sumber';
let menetapkanReminderDismissed=false;
function dismissMenetapkanReminder(button){menetapkanReminderDismissed=true;button.closest('.menetapkan-recommendation-reminder')?.remove()}
function menetapkanRecommendationReminder(){return menetapkanFilter==='Rekomendasi Indikator'&&!menetapkanReminderDismissed?sdBanner({tone:'info',className:'menetapkan-recommendation-reminder',onClose:'dismissMenetapkanReminder(this)',children:'<p>Daftar ini hanya rekomendasi dari capaian tahun lalu. Sekolah boleh memilih indikator lain yang lebih sesuai dengan kondisi saat ini.</p>'}):''}

function openMenetapkanAlternative(){prepareDemo();stage=0;menetapkanFilter='Rekomendasi Indikator';menetapkanSource='Semua sumber';save();go('menetapkan-alternative')}
function setMenetapkanFilter(value){menetapkanFilter=value;render();document.getElementById('menetapkan-filter')?.focus()}
function menetapkanTabBadge(name,recommended){const count=indicators.filter(i=>data.priorities.includes(i.id)&&(name==='Rekomendasi Indikator'?recommended.has(i.id):dimensionOf(i)===name)).length;return count?`<span class="menetapkan-tab-count" aria-label="${count} indikator dipilih">${count}</span>`:''}
function menetapkanAlternative(){const top=new Set(['lit','num','A.3','D.4','D.8','ajar','tka2']);if(!['Rekomendasi Indikator',...dimensionNames].includes(menetapkanFilter))menetapkanFilter='Rekomendasi Indikator';const visible=indicators.filter(i=>menetapkanFilter==='Rekomendasi Indikator'?top.has(i.id):dimensionOf(i)===menetapkanFilter).sort(compareIndicatorAchievement);return `${page==='flow'?'':`${sdBtn('Kembali ke daftar siklus',{variant:'quiet',size:'sm',onclick:"go('home')",leadingIcon:'arrow-left'})}${steps()}`}<div class="priority-selection-bar" role="status" aria-live="polite" aria-atomic="true"><div><strong>${data.priorities.length} indikator sudah dipilih</strong><span>Pilih 2–3 indikator sesuai kebutuhan murid.</span></div><div class="priority-bar-actions">${sdBtn('Simpan draf dan keluar',{variant:'secondary',onclick:"save();go('home')"})}${sdBtn('Lanjutkan',{onclick:'next()',trailingIcon:'arrow-right'})}</div></div>${sdTabs({label:'Filter indikator Menetapkan',className:'menetapkan-dimension-tabs',value:menetapkanFilter,onselect:v=>`setMenetapkanFilter('${v}')`,items:['Rekomendasi Indikator',...dimensionNames].map(name=>({value:name,label:name,count:indicators.filter(i=>data.priorities.includes(i.id)&&(name==='Rekomendasi Indikator'?top.has(i.id):dimensionOf(i)===name)).length}))})}<div class="report-list-toolbar"><p class="sub" role="status">${visible.length} indikator ditampilkan</p></div>${menetapkanRecommendationReminder()}<div class="diagnosis-reference-grid menetapkan-reference-grid">${visible.map(i=>diagnosisReferenceCard(i,true)).join('')||'<p class="muted source-filter-empty">Belum ada indikator untuk kelompok yang dipilih.</p>'}</div>${reportDialog()}`}

function priorityReferenceFooter(i){const selected=data.priorities.includes(i.id);return `<button class="${selected?'priority-selected':''}" aria-pressed="${selected}" onclick="choose('${i.id}',${!selected})">${selected?'Batalkan':'Pilih'}</button>${selected?`<p class="priority-card-target">Target: <b>${esc(data.targets[i.id]??'—')} ${esc(i.unit)}</b><button class="quiet" onclick="requestPriorityTarget('${i.id}')">Ubah target</button></p>`:''}`}

function indicatorSourceLabel(i){if(i.source==='Rapor Pendidikan')return 'Rapor';if(/akreditasi/i.test(i.source+' '+i.origin))return 'Akreditasi';return i.source}
function setMenetapkanSource(value){menetapkanSource=value;render()}

function legacyMenetapkan(){return `${sdBtn('Kembali ke daftar siklus',{variant:'quiet',size:'sm',onclick:"go('home')",leadingIcon:'arrow-left'})}${steps()}<div class="priority-layout"><section class="flow-content">${priorities()}</section>${chosenPanel()}</div>`}

function editCurrentPlan(){if(listRktStatus(data)!=='Sudah ada rencana'||data.status==='Selesai')return;stage=2;go('flow')}

function localDesignAlternatives(){return typeof location!=='undefined'&&['localhost','127.0.0.1','[::1]'].includes(location.hostname)}

function diagnosisSummary(){return `<section class="diagnosis-school-summary" aria-label="Identitas sekolah"><div><p class="diagnosis-summary-label">Rapor Pendidikan</p><h2>SMA Rakyat 3</h2><dl><dt>NPSN</dt><dd>20260001</dd><dt>Alamat</dt><dd>Jl. Merdeka No. 12, Kec. Menteng</dd><dt>Kota/Provinsi</dt><dd>Kota Jakarta Pusat, DKI Jakarta</dd></dl></div><div class="diagnosis-school-side"><div class="diagnosis-year-picker"><span class="year-select-label" id="diagnosis-data-year-label">Pilih Tahun Data</span><div class="year-select"><button type="button" class="year-select-trigger" id="diagnosis-data-year" aria-haspopup="listbox" aria-expanded="false" aria-labelledby="diagnosis-data-year-label diagnosis-data-year"><span class="year-select-value">2025</span><svg class="year-select-caret" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10l5 5 5-5z"/></svg></button><ul class="year-select-list" role="listbox" aria-labelledby="diagnosis-data-year-label" hidden><li role="option" aria-selected="true" data-year="2025">2025</li><li role="option" aria-selected="false" aria-disabled="true" data-year="2024">2024</li><li role="option" aria-selected="false" aria-disabled="true" data-year="2023">2023</li><li role="option" aria-selected="false" aria-disabled="true" data-year="2022">2022</li></ul></div></div><div class="diagnosis-accreditation"><b><svg class="accreditation-info" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"/></svg>Akreditasi</b><span class="accreditation-badge" aria-label="Akreditasi A">A</span></div></div></section><section class="diagnosis-overview-banner" aria-labelledby="diagnosis-overview-title"><h2 id="diagnosis-overview-title">Ringkasan kondisi Satuan Pendidikan Anda berdasarkan Rapor Pendidikan Tahun 2025</h2><div class="diagnosis-highlight-grid"><article><img class="diagnosis-highlight-icon" src="assets/icons/peningkatan-tertinggi.svg" width="60" height="60" alt="" aria-hidden="true"><div><p>Peningkatan Tertinggi</p><h3>Iklim keamanan satuan pendidikan</h3></div></article><article><img class="diagnosis-highlight-icon" src="assets/icons/capaian-terbaik.svg" width="60" height="60" alt="" aria-hidden="true"><div><p>Capaian Terbaik</p><h3>Karakter</h3></div></article><article><img class="diagnosis-highlight-icon" src="assets/icons/capaian-terendah.svg" width="60" height="60" alt="" aria-hidden="true"><div><p>Capaian Terendah</p><h3>Kemampuan literasi</h3></div></article></div><div class="diagnosis-improvement-tip"><img src="assets/icons/emoji-objects.svg" width="24" height="24" alt="" aria-hidden="true"><div><p>Contoh cara membenahi Kemampuan Literasi</p><b>Kemampuan untuk memahami teks informasi berkaitan erat dengan kemampuan literasi siswa secara keseluruhan.</b></div></div><div class="diagnosis-overview-actions"><button onclick="document.getElementById('report-indicators').scrollIntoView({behavior:'smooth',block:'start'})">Buka Seluruh Capaian Satdik Saya ↓</button><p>Perlu panduan? <button class="diagnosis-guide-link" aria-label="Buka cara menggunakan Rapor Pendidikan dan PBD di tab baru" onclick="openHelp()">Buka cara menggunakan Rapor Pendidikan & PBD</button></p></div></section>`}

function setDiagnosisSource(value){if(!['Rapor Pendidikan','TKA','Akreditasi'].includes(value))return;diagnosisSource=value;updateDiagnosisFilters()}

function compareIndicatorAchievement(a,b){const rank=i=>{if(typeof i.score!=='number'||!Number.isFinite(i.score))return 3;const label=String(i.level||'').toLowerCase();return label.startsWith('kurang')?0:label.startsWith('sedang')||label.startsWith('memadai')?1:label.startsWith('baik')?2:3};const difference=rank(a)-rank(b);if(difference)return difference;const aScore=typeof a.score==='number'&&Number.isFinite(a.score)?a.score:Infinity,bScore=typeof b.score==='number'&&Number.isFinite(b.score)?b.score:Infinity;if(aScore!==bScore)return aScore-bScore;return String(a.code).localeCompare(String(b.code),'id',{numeric:true})}
function diagnosisVisibleIndicators(){return indicators.filter(i=>(reportGroupFilter==='Semua'||dimensionOf(i)===reportGroupFilter)&&(diagnosisSource==='Akreditasi'?indicatorSourceLabel(i)==='Akreditasi':i.source===diagnosisSource)).sort(compareIndicatorAchievement)}
function diagnosisResultsMarkup(items){return items.length?`<div class="diagnosis-reference-grid">${items.map(i=>diagnosisReferenceCard(i)).join('')}</div>`:'<div class="card empty"><p class="muted">Belum ada data indikator untuk sumber dan dimensi yang dipilih.</p></div>'}
function updateDiagnosisFilters(){const results=document.getElementById('diagnosis-results');if(!results){render();return}const position=window.scrollY;const requiredHeight=Math.max(0,window.innerHeight-results.getBoundingClientRect().top);results.style.minHeight=requiredHeight+'px';document.querySelectorAll('[data-diagnosis-dimension]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.diagnosisDimension===reportGroupFilter)));document.querySelectorAll('[data-diagnosis-source]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.diagnosisSource===diagnosisSource)));const visible=diagnosisVisibleIndicators();document.getElementById('diagnosis-result-count').textContent=visible.length+' indikator ditampilkan';results.innerHTML=diagnosisResultsMarkup(visible);window.scrollTo({top:position,left:0,behavior:'instant'})}
function openMenetapkanCards(){prepareDemo();data.activities=[];stage=0;menetapkanFilter='Rekomendasi Indikator';save();go('menetapkan-cards')}
function scrollToSelectedIndicator(id){if(!data.priorities.includes(id))return;let row=document.getElementById('menetapkan-row-'+id);if(!row){menetapkanDim='Semua';menetapkanCat='Semua';render();row=document.getElementById('menetapkan-row-'+id)}if(row){row.focus({preventScroll:true});row.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center',inline:'nearest'})}}
let menetapkanDim='Semua',menetapkanCat='Semua';
const levelKnown=i=>['Kurang','Sedang','Baik'].includes(i.level)||(i.source==='TKA'&&['Memadai','Istimewa'].includes(i.level));
const menetapkanLevel=i=>levelKnown(i)?i.level:'Tidak tersedia';
let step1Source='Semua';
const STEP1_SOURCES=['Rapor','TKA','Akreditasi','Lainnya'];
const originGroup=o=>{o=String(o||'').toLowerCase();return /dapodik/.test(o)?'Dapodik':/sulingjar/.test(o)?'Sulingjar':/sikerma/.test(o)?'Sikerma':/dit\. ?smk/.test(o)?'Dit. SMK':'Data internal sekolah'};
const sourceGroup=i=>i.own?'Sekolah':i.source==='Rapor Pendidikan'?'Rapor':(i.source==='TKA'||/hasil tka/i.test(i.origin||''))?'TKA':i.source==='Akreditasi'?'Akreditasi':originGroup(i.origin);
const filterGroup=i=>{const g=sourceGroup(i);return ['Rapor','TKA','Akreditasi','Sekolah'].includes(g)?g:'Lainnya'};
const isOtherSource=i=>!['Rapor','TKA','Sekolah'].includes(sourceGroup(i));
function step1SourceText(i){const g=sourceGroup(i);return g==='Rapor'?'Rapor Pendidikan':g==='Sekolah'?'Dari sekolah':g==='Akreditasi'?(i.origin||'Akreditasi'):g}
const step1SourceList=()=>[...STEP1_SOURCES,...((data.ownIndicators||[]).length?['Sekolah']:[])];
function step1Filters(){const opts=[['Semua','Semua',indicators.length],...step1SourceList().map(x=>[x,x==='Sekolah'?'Dari sekolah':x,indicators.filter(i=>filterGroup(i)===x).length])];return `<div class="step1-filters" id="step1-filters" role="group" aria-label="Sumber data"><span class="step1-filters-label">Sumber data</span>${opts.map(([v,l,n])=>`<button type="button" class="step1-chip" data-src="${v}" aria-pressed="${step1Source===v}" onclick="setStep1Source('${v}')">${l}<span class="step1-chip-count">${n}</span></button>`).join('')}</div>`}
function setStep1Source(v){step1Source=step1SourceList().includes(v)?v:'Semua';updateStep1();document.querySelector('.step1-chip[data-src][aria-pressed="true"]')?.focus()}
function step1SourceSelect(){return sdSelect({label:'Sumber data',hideLabel:true,id:'step1-source',value:step1Source,onchange:'setStep1Source(this.value)',options:[{value:'Semua',label:'Semua sumber data ('+indicators.length+')'},...step1SourceList().map(x=>({value:x,label:(x==='Sekolah'?'Dari sekolah':x)+' ('+indicators.filter(i=>filterGroup(i)===x).length+')'}))]})}
function menetapkanItems(){return indicators.filter(i=>(menetapkanDim==='Semua'||dimensionOf(i)===menetapkanDim)&&(menetapkanCat==='Semua'||menetapkanLevel(i)===menetapkanCat)&&(step1Source==='Semua'||filterGroup(i)===step1Source)).sort((a,b)=>(a.own?1:0)-(b.own?1:0)||compareIndicatorAchievement(a,b))}
function targetSuggestion(id){const i=ind(id);if(typeof i.score!=='number')return '';const t=Math.min(Math.round(i.score+10),i.max);return t>i.score?t:''}
function menetapkanLevels(){return ['Kurang','Sedang','Baik','Tidak tersedia']}
function setMenetapkanDim(v){menetapkanDim=v;render();document.getElementById('menetapkan-dim')?.focus()}
function setMenetapkanCat(v){menetapkanCat=v;render();document.getElementById('menetapkan-cat')?.focus()}
const selTargetText=id=>data.targets[id]===''||data.targets[id]===undefined?'Belum diisi':chainTargetText(id).replace(/ %$/,'%');
let previewOpen=null,previewFrom=null;
const pvStage=()=>previewFrom!==null&&stage<3?previewFrom:stage;
const PLAN_LOCK_NOTE='Masa perencanaan sudah lewat. Hubungi admin untuk melakukan perubahan rencana.';
const readonlyFlow=html=>{const note=sdBanner({tone:'warning',className:'flow-readonly-note',children:`<p>${PLAN_LOCK_NOTE}</p>`});return `<div class="flow-readonly">${html.replace('<h2 class="sd-sr-only">',m=>note+m)}</div>`};
function lockReadonlyFlow(){document.querySelectorAll('.flow-readonly input,.flow-readonly select,.flow-readonly textarea,.flow-readonly button').forEach(el=>{if(el.closest('.preview-band,summary,.sd-banner')||(el.getAttribute('aria-label')||'').startsWith('Deskripsi'))return;el.disabled=true})}
function previewUser(el){previewOpen=!el.open}
