const actNo=a=>{const k=data.priorities.indexOf(a.indicator),rs=data.roots[a.indicator]||[],j=rs.indexOf(a.root);if(k<0||j<0)return '';const n=data.activities.filter(x=>x.indicator===a.indicator&&x.root===a.root).indexOf(a);return `${k+1}.${j+1}.${n+1}`};
const numTag=a=>{const n=actNo(a);return n?`<span class="activity-num">${n}</span> `:''};
const previewLink=(go,label,num='',cls='')=>`<button type="button" class="preview-link${cls?' '+cls:''}" onclick="${go}">${num?`<span class="preview-num">${num}</span>`:''}<span>${label}</span></button>`;
function openPlanDetail(){document.getElementById('plan-detail-dialog')?.showModal()}
const pdLabel=(n,t)=>`<span class="pd-label"><span class="pd-label-text">${t}</span></span>`;
function planDetailLate(a){const stage=pvStage();if(stage<3)return '';const p=data.progress[a.id]||{},e=data.evaluation[a.id]||{},f=data.follow[a.id]||{},row=(t,v)=>`<div><dt>${t}</dt><dd>${v}</dd></div>`,sec=(n,t,rows)=>`<div class="pd-late">${pdLabel(n,t)}<dl>${rows}</dl></div>`,none='Belum diisi';let h=sec(3,'Pelaksanaan',row('Bukti pelaksanaan',evalProof(a))+row('Catatan kemajuan dan kendala',p.notes?esc(p.notes):none));if(stage>=4)h+=sec(4,'Evaluasi',row('Hasil evaluasi',e.result?esc(e.result):none)+row('Alasan penilaian dan pembelajaran',e.notes?esc(e.notes):none));if(stage>=5)h+=sec(5,'Tindak lanjut',row('Jenis tindak lanjut',f.type?esc(f.type):none)+row('Tindakan',f.action?esc(f.action):none));return h}
function planDetailDialog(){const body=data.priorities.map((id,k)=>{const i=ind(id),rs=data.roots[id]||[],tv=data.targets[id],has=tv!==''&&tv!==undefined;return `<section class="pd-ind"><div class="pd-ind-head"><h3><span class="pd-num">${k+1}</span>${esc(i.name)}</h3>${indicatorTargetContext(id)}</div>${rs.length?rs.map((r,j)=>{const acts=data.activities.filter(a=>a.indicator===id&&a.root===r);return sdAccordion({open:true,className:'pd-root',title:`<span class="pd-head">${pdLabel(1,'Akar masalah')}<span class="pd-name"><span class="pd-num">${k+1}.${j+1}</span>${esc(chainName(r))}</span></span>`,body:acts.length?acts.map(a=>sdAccordion({open:false,className:'pd-act',title:`<span class="pd-head">${pdLabel(2,'Kegiatan')}<span class="pd-name"><span class="pd-num">${actNo(a)}</span>${esc(a.recommendationKey?activitySummaryTitle(a):(a.name||'Kegiatan belum diberi nama'))}</span></span>`,body:`<dl><div><dt>Yang akan dilakukan</dt><dd>${esc(a.implementation||a.realistic||'Belum diisi')}</dd></div><div><dt>Total anggaran</dt><dd>${a.needsBudget?money(a.budget):'Tidak membutuhkan anggaran'}</dd></div></dl>${planDetailLate(a)}`})).join(''):'<p class="pd-empty">Belum ada kegiatan dipilih.</p>'})}).join(''):'<p class="pd-empty">Belum ada akar masalah dipilih.</p>'}</section>`}).join('');return `<dialog id="plan-detail-dialog" class="plan-detail-dialog" aria-labelledby="plan-detail-heading"><header class="pd-header"><div><h2 id="plan-detail-heading">Detail Rencana Kerja Tahunan</h2><p>SMA Rakyat 3 · Tahun Ajaran ${esc(data.year)}</p></div>${sdBtn('Tutup',{variant:'quiet',size:'sm',icon:'close',onclick:"document.getElementById('plan-detail-dialog').close()"})}</header><div class="pd-body">${body||'<p class="pd-empty">Belum ada indikator prioritas dipilih.</p>'}</div><footer class="pd-footer">${sdBtn('Tutup',{variant:'secondary',onclick:"document.getElementById('plan-detail-dialog').close()"})}</footer></dialog>`}
function previewGoAct(t,aid){const key=['','','','exec','eval','ctl'][t]+'-'+aid;actOpen[key]=true;stage=t;render();window.scrollTo(0,0);setTimeout(()=>chainScroll(document.getElementById('act-'+key)),0)}
function previewGo(t,id,j=0){if(stage>=3)previewFrom=stage;const run=()=>{if(t===0){scrollToSelectedIndicator(id);return}chainScroll(document.getElementById(t===1?'root-card-'+id:(j>0?`plan-${id}-root-${j}`:'plan-'+id)))};if(stage===0&&t===0){revealIndicator(id);return}if(stage===t){run();return}stage=t;if(t===0)mutuOpenKey=MENETAPKAN_TOP.has(id)?'rec':'d'+dimensionNames.indexOf(dimensionOf(ind(id)));render();window.scrollTo(0,0);setTimeout(run,0)}
function previewLate(none){const cur=pvStage(),stage=5;const dash='<span class="preview-na" aria-hidden="true">–</span><span class="sr-only">Belum tersedia</span>',pick='<span class="preview-na">Belum dipilih</span>';const ey=n=>names[n],tone={'Efektif':'green','Perlu penyesuaian':'amber','Tidak efektif':'red'};const cols=[{label:'Indikator'},{label:'Akar masalah'},{label:'Kegiatan'},{label:'Pelaksanaan'},...(stage>=4?[{label:'Evaluasi'}]:[]),...(stage>=5?[{label:'Tindak lanjut'}]:[])];
const late=a=>{if(!a)return [dash,dash,dash];const p=data.progress[a.id]||{},e=data.evaluation[a.id],f=data.follow[a.id];const go=t=>`previewGoAct(${t},'${a.id}')`;return [cur>=3?previewLink(go(3),sdBadge(p.link?'Bukti ada':'Belum ada bukti',p.link?'green':'gray')):dash,cur>=4?previewLink(go(4),sdBadge(e?.result||'Belum dievaluasi',tone[e?.result]||'gray')):dash,cur>=5?previewLink(go(5),f&&(f.type||f.action)?`${f.type?sdBadge(f.type,'blue'):''}${f.action?`<span class="preview-follow">${esc(f.action)}</span>`:''}`:dash):dash]};
const rows=data.priorities.flatMap((id,k)=>{const i=ind(id),filled=data.targets[id]!==''&&data.targets[id]!==undefined,name=`<div class="preview-ind"><span class="preview-num">${k+1}</span><div class="preview-ind-body">${previewLink(`previewGo(0,'${id}')`,esc(i.name),'','preview-strong')}<div class="preview-label">${sdBadge(filled?'Target '+selTargetText(id):'Target belum diisi',filled?'blue':'gray')}</div></div></div>`,no={html:String(k+1),className:'preview-no'},rs=data.roots[id]||[];if(!rs.length)return [[name,pick,pick,...late(null)]];
const groups=rs.map(r=>({r,acts:data.activities.filter(a=>a.indicator===id&&a.root===r)})),total=groups.reduce((n,g)=>n+Math.max(1,g.acts.length),0),out=[];
groups.forEach((g,gi)=>{const n=Math.max(1,g.acts.length);for(let x=0;x<n;x++){const a=g.acts[x],first=gi===0&&x===0;out.push([first?{html:name,rowspan:total}:null,x?null:{html:previewLink(`previewGo(1,'${id}')`,esc(chainName(g.r)),`${k+1}.${gi+1}`),rowspan:n},a?previewLink(`previewGo(2,'${id}',${gi})`,esc(a.recommendationKey?activitySummaryTitle(a):(a.name||'Kegiatan belum diberi nama')),actNo(a)):pick,...late(a)])}});return out});return {cols,rows}}
function hasPreview(){return pvStage()<=5}
function previewIsOpen(){return previewOpen===null?pvStage()>=2:previewOpen}
function previewBandHtml(){return '<div class="preview-band is-compact">'+planDetailDialog()+`<section class="preview-card compact-bar" aria-label="Langkah Siklus 6M">${flowStepper()}${railToggleBtn()?`<div class="compact-bar-rail">${railToggleBtn()}</div>`:''}</section>${prioritiesRailSection()}</div>`}
