const change=i.caption?`<div class="table-indicator-change"><span class="muted">${esc(i.caption)}</span></div>`:`<div class="table-indicator-change">${reportDelta(i).replace('Capaian ','').replace(/ dari tahun \d{4}/,'').replace(/<span class="muted">[^<]*<\/span>/,'<span class="table-no-comparison">Belum ada pembanding</span>')}</div>`;
const cat=i.badge?sdBadge(i.badge,i.badgeTone||'green'):i.source==='TKA'&&i.unit!=='%'?'':levelKnown(i)?sdBadge(menetapkanLevel(i),badgeTone(typeof i.score==='number'?esc(i.color):'')):'';
