document.addEventListener('click',event=>{if(!event.target.closest('.rapor-account'))document.querySelectorAll('.rapor-account[open]').forEach(el=>el.open=false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.rapor-account[open]').forEach(el=>{el.open=false;el.querySelector('summary')?.focus()})});

(function(){if(RAPOR)return;const id=new URLSearchParams(location.search).get('indikator');if(!id||!indicators.some(i=>i.id===id))return;window.history.replaceState(null,'',location.pathname);if(!['Draf','Perlu revisi'].includes(data.status))return toast('Indikator dari Rapor tidak ditambahkan karena rencana sudah disimpan.');if(!data.priorities.includes(id)){if(data.priorities.length>=3)toast('Maksimal 3 indikator prioritas.');else{data.priorities=[...data.priorities,id];save()}}stage=0;go('flow')})();
(function(){if(!RAPOR)return;const id=new URLSearchParams(location.search).get('akar');if(!id||!indicators.some(i=>i.id===id))return;window.history.replaceState(null,'',location.pathname);openReportRoot(id)})();

;(function(){try{const q=new URLSearchParams(location.search);if(q.get('tinjau')==='1'&&typeof demoReview==='function'){q.delete('tinjau');window.history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():''));demoReview();return}if(q.get('tersimpan')==='1'&&typeof demoSavedPlan==='function'){q.delete('tersimpan');window.history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():''));demoSavedPlan();return}if(q.get('ringkasan')==='1'&&typeof demoSummary==='function'){q.delete('ringkasan');window.history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():''));demoSummary();return}if(q.get('beranda')==='siklus-selesai'&&typeof demoCyclesDone==='function'){q.delete('beranda');window.history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():''));demoCyclesDone();return}if(q.get('beranda')==='siklus'&&typeof demoCycles==='function'){q.delete('beranda');window.history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():''));demoCycles();return}const bh=q.get('beranda');if(['evaluation-open','followup','empty','draft'].includes(bh)&&typeof simulate==='function'){q.delete('beranda');window.history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():''));bh==='evaluation-open'?demoOpenEvaluation():bh==='draft'?demoDraft():simulate(bh);return}const ed=q.get('evaluasidiri');if(['start','review','saved'].includes(ed)&&typeof demoReflection==='function'){q.delete('evaluasidiri');window.history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():''));demoReflection(ed);return}}catch(e){}})();
;(function(){try{const p=new URLSearchParams(location.search),s=Number(p.get('step'));if(s>=1&&s<=6&&typeof jump==='function'){p.delete('step');window.history.replaceState(null,'',location.pathname+(p.toString()?'?'+p.toString():''));jump(s-1)}}catch(e){}})();

;(function(){function sync(){const b=document.querySelector('.preview-band.is-compact'),root=document.documentElement.style;{const pn=document.getElementById('priority-rail');root.setProperty('--rail-push',((stage===1||stage===2)&&railPref===null&&pn&&!pn.hidden?Math.ceil(pn.offsetHeight):0)+'px')}if(b){const r=b.getBoundingClientRect();let bt=r.bottom;[...b.children].filter(c=>c.id!=='priority-rail').forEach(c=>{bt=Math.max(bt,c.getBoundingClientRect().bottom)});root.setProperty('--band-bottom',Math.ceil(bt-r.top+64)+'px')}document.querySelectorAll('.work-nest-sticky,.work-nest-plan').forEach(c=>{const h=c.querySelector(':scope > .plan-card-head');if(h)c.style.setProperty('--nest-head-h',Math.ceil(h.getBoundingClientRect().height)+'px')});document.querySelectorAll('.work-root-group').forEach(g=>{const h=g.querySelector(':scope > .work-root-head');if(h)g.style.setProperty('--root-head-h',Math.ceil(h.getBoundingClientRect().height)+'px');const th=g.querySelector('thead th');if(th&&th.getBoundingClientRect().height)g.style.setProperty('--thead-h',Math.ceil(th.getBoundingClientRect().height)+'px')})}
try{function pushRows(){document.querySelectorAll('.work-nest-plan tr.sd-row-selected:not(.menetapkan-expand-row)').forEach(r=>{const f=r.nextElementSibling;if(!f||!f.classList.contains('menetapkan-expand-row'))return;const top=parseFloat(getComputedStyle(r).top)||0,dy=Math.min(0,f.getBoundingClientRect().bottom-r.offsetHeight-top);r.style.transform=dy?'translateY('+Math.round(dy)+'px)':''})}addEventListener('scroll',pushRows,{passive:true});new ResizeObserver(()=>{sync();pushRows()}).observe(document.body);addEventListener('resize',sync);document.addEventListener('click',()=>setTimeout(()=>{sync();pushRows()},0));sync();pushRows();{const r0=render;render=function(){const v=r0.apply(this,arguments);requestAnimationFrame(()=>{sync();pushRows()});return v}}}catch(e){}})();
